package com.runie.overlay;

import com.runie.support.TestRunieConfig;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Shiny render effect (rework part 4): a runtime shimmer over the decoded
 * frames — no per-creature shiny art. Tints are cached per frame; the static
 * thumbnail variant stays confined to the sprite's alpha.
 */
public class ShinyRendererTest
{
	private static BufferedImage sprite()
	{
		BufferedImage img = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(90, 160, 90));
		g.fillOval(4, 4, 24, 24); // opaque blob, transparent corners
		g.dispose();
		return img;
	}

	@Test
	public void shimmerDrawsAndCachesTintsPerFrame()
	{
		ShinyRenderer r = new ShinyRenderer();
		TestRunieConfig config = new TestRunieConfig();
		BufferedImage frame = sprite();
		BufferedImage canvas = new BufferedImage(48, 48, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		g.drawImage(frame, 8, 8, null);
		int before = canvas.getRGB(20, 20);
		r.renderShimmer(g, frame, 8, 8, 0, config);
		assertEquals(1, r.cachedFrameCount());
		// many render calls at different times reuse the same cached tints
		for (long t = 100; t < 4_000; t += 100)
		{
			r.renderShimmer(g, frame, 8, 8, t, config);
		}
		g.dispose();
		assertEquals(1, r.cachedFrameCount());
		assertTrue("shimmer must visibly alter the sprite", canvas.getRGB(20, 20) != before);
	}

	@Test
	public void reducedMotionShimmerIsFullyStatic()
	{
		// two independent renders at very different times must be pixel-identical
		// under reduced motion (fixed hue, no sparkle motion — §6.4)
		BufferedImage a = renderReducedAt(0);
		BufferedImage b = renderReducedAt(123_456);
		for (int y = 0; y < a.getHeight(); y++)
		{
			for (int x = 0; x < a.getWidth(); x++)
			{
				assertEquals("pixel " + x + "," + y, a.getRGB(x, y), b.getRGB(x, y));
			}
		}
	}

	private static BufferedImage renderReducedAt(long nowMs)
	{
		ShinyRenderer r = new ShinyRenderer();
		TestRunieConfig config = new TestRunieConfig();
		config.reducedMotion = true;
		BufferedImage frame = sprite();
		BufferedImage canvas = new BufferedImage(48, 48, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		g.drawImage(frame, 8, 8, null);
		r.renderShimmer(g, frame, 8, 8, nowMs, config);
		g.dispose();
		return canvas;
	}

	@Test
	public void staticShinyThumbnailStaysInsideTheSpriteAlpha()
	{
		BufferedImage src = sprite();
		BufferedImage out = ShinyRenderer.applyStaticShiny(src);
		assertNotNull(out);
		assertEquals(src.getWidth(), out.getWidth());
		// transparent corner stays transparent (wash is SrcIn-clipped)
		assertEquals(0, out.getRGB(0, 0) >>> 24);
		// opaque center stays opaque and changed color (the iridescent wash)
		assertEquals(255, out.getRGB(16, 16) >>> 24);
		assertTrue(out.getRGB(16, 16) != src.getRGB(16, 16));
		// source untouched
		assertEquals(0, src.getRGB(0, 0) >>> 24);
	}
}

package com.runie.overlay;

import com.google.gson.Gson;
import com.runie.assets.ArtStyleService;
import com.runie.assets.AssetLoader;
import com.runie.core.EggService;
import com.runie.core.ProgressionService;
import com.runie.core.PullResult;
import com.runie.creatures.CreatureRegistry;
import com.runie.creatures.Rarity;
import com.runie.state.RunieStateStore;
import com.runie.state.TestStateStores;
import com.runie.support.FakeClock;
import com.runie.support.TestRunieConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Bug 5 regression: the hatch reveal must present IMMEDIATELY when onPull
 * fires (it used to stay hidden until logout because a stuck danger flag —
 * the Long.MIN_VALUE combat-window overflow in RuniePlugin — re-anchored the
 * presentation every frame). Also pins the intended §7.3 semantics: a genuine
 * danger defers only the CINEMATIC, never the committed result.
 */
public class RuniePullOverlayTest
{
	private ScheduledExecutorService executor;
	private FakeClock clock;
	private TestRunieConfig config;
	private RuniePullOverlay overlay;
	private RunieStateStore store;

	@Before
	public void setUp() throws IOException
	{
		Path dir = Files.createTempDirectory("runie-pulloverlay-test");
		executor = Executors.newSingleThreadScheduledExecutor();
		Gson gson = new Gson();
		CreatureRegistry registry = new CreatureRegistry(gson);
		registry.load();
		store = TestStateStores.create(gson, executor, registry, dir);
		store.switchAccount(11L);
		clock = new FakeClock(1_784_721_600_000L);
		EggService eggs = new EggService(store, clock);
		ProgressionService progression = new ProgressionService(store, registry, eggs);
		AssetLoader assets = new AssetLoader();
		ArtStyleService styles = new ArtStyleService(config = new TestRunieConfig(), () -> "true", v -> { });
		// direct executor: presentation prep is synchronous, like the mockup seam
		overlay = new RuniePullOverlay(registry, progression, assets, styles, config, clock, Runnable::run);
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private PullResult result()
	{
		return new PullResult("grubnak", Rarity.COMMON, true, false, 0, false, false, false,
			new PullResult.PitySnapshot(0, 0, 0, 1, 0));
	}

	private Dimension renderOnce()
	{
		BufferedImage img = new BufferedImage(300, 240, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		Dimension d = overlay.render(g);
		g.dispose();
		return d;
	}

	@Test
	public void revealPresentsImmediatelyOnHatch()
	{
		assertFalse(overlay.isPresenting());
		assertNull(renderOnce()); // nothing to show before a hatch

		overlay.onPull(result()); // the hatch — direct executor: prep is done now

		assertTrue("presentation must exist right after onPull", overlay.isPresenting());
		assertNotNull("first frame after the hatch must render the cinematic", renderOnce());
	}

	@Test
	public void revealPlaysThroughAndDismissesOnItsOwnTimeline()
	{
		overlay.onPull(result());
		assertNotNull(renderOnce());                 // anchors the presentation clock
		clock.advanceMs(RuniePullOverlay.HATCH_MS + 100);
		assertNotNull(renderOnce());                 // reveal card phase
		clock.advanceMs(RuniePullOverlay.REVEAL_MS); // past the total
		assertNull(renderOnce());                    // dismissed
		assertFalse(overlay.isPresenting());
	}

	@Test
	public void genuineDangerDefersTheCinematicUntilClear()
	{
		AtomicBoolean danger = new AtomicBoolean(true);
		overlay.setDangerSupplier(danger::get);
		overlay.onPull(result());

		assertNull("cinematic must wait while in danger", renderOnce());
		clock.advanceMs(10_000);
		assertNull(renderOnce());                    // still deferred, still pending
		assertTrue(overlay.isPresenting());          // result is committed; only presentation waits

		danger.set(false);
		assertNotNull("cinematic starts as soon as danger clears", renderOnce());
	}

	@Test
	public void reducedMotionStillPresentsImmediately()
	{
		config.reducedMotion = true;
		overlay.onPull(result());
		assertNotNull(renderOnce());
	}
}

package com.runie.overlay;

import com.runie.config.AnimationIntensity;
import com.runie.core.AuraState;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.runie.support.TestRunieConfig;

/**
 * AuraRenderer: aura-state → effect selection, ms-driven shimmer,
 * reduced-motion / intensity gating, and the pre-rendered glow raster
 * (Appendix B: auras are composited, never baked).
 */
public class AuraRendererTest
{
	private AuraRenderer renderer;
	private TestRunieConfig config;

	@Before
	public void setUp()
	{
		renderer = new AuraRenderer();
		config = new TestRunieConfig();
	}

	// ------------------------------------------------------------------
	// Aura state → effect selection
	// ------------------------------------------------------------------

	@Test
	public void effectSelectionMapsAuraStates()
	{
		assertEquals(AuraRenderer.Effect.NONE, AuraRenderer.effectFor(AuraState.NONE));
		assertEquals(AuraRenderer.Effect.PRESTIGE_RING, AuraRenderer.effectFor(AuraState.PRESTIGE));
		assertEquals(AuraRenderer.Effect.GOLDEN_RADIANCE, AuraRenderer.effectFor(AuraState.GOLDEN));
		assertEquals(AuraRenderer.Effect.NONE, AuraRenderer.effectFor(null));
	}

	// ------------------------------------------------------------------
	// ms-driven shimmer, reduced-motion / intensity gating (§6.2 / §6.4)
	// ------------------------------------------------------------------

	@Test
	public void glowAlphaIsStaticUnderReducedMotion()
	{
		float a0 = AuraRenderer.glowAlpha(0, true, AnimationIntensity.NORMAL);
		float a1 = AuraRenderer.glowAlpha(AuraRenderer.SHIMMER_PERIOD_MS / 4, true, AnimationIntensity.NORMAL);
		float a2 = AuraRenderer.glowAlpha(999_999, true, AnimationIntensity.FULL);
		assertEquals(a0, a1, 0f); // constant: no shimmer at all
		assertEquals(a0, a2, 0f);
	}

	@Test
	public void glowAlphaPulsesMsDriven()
	{
		long quarter = AuraRenderer.SHIMMER_PERIOD_MS / 4; // sine peak
		float base = AuraRenderer.glowAlpha(0, false, AnimationIntensity.NORMAL);
		float peak = AuraRenderer.glowAlpha(quarter, false, AnimationIntensity.NORMAL);
		assertEquals(0.55f, base, 0.001f);
		assertEquals(0.75f, peak, 0.001f);   // base + NORMAL amplitude 0.20
		// full period wraps back to base — pure function of elapsed ms
		assertEquals(base, AuraRenderer.glowAlpha(AuraRenderer.SHIMMER_PERIOD_MS, false,
			AnimationIntensity.NORMAL), 0.001f);
	}

	@Test
	public void shimmerAmplitudeScalesWithIntensity()
	{
		long quarter = AuraRenderer.SHIMMER_PERIOD_MS / 4;
		float subtle = AuraRenderer.glowAlpha(quarter, false, AnimationIntensity.SUBTLE);
		float normal = AuraRenderer.glowAlpha(quarter, false, AnimationIntensity.NORMAL);
		float full = AuraRenderer.glowAlpha(quarter, false, AnimationIntensity.FULL);
		assertTrue(subtle < normal && normal < full);
	}

	@Test
	public void sparklesGatedByReducedMotionAndIntensity()
	{
		assertEquals(0, AuraRenderer.sparkleCount(true, AnimationIntensity.NORMAL));
		assertEquals(0, AuraRenderer.sparkleCount(true, AnimationIntensity.FULL));
		assertEquals(0, AuraRenderer.sparkleCount(false, AnimationIntensity.SUBTLE));
		assertEquals(5, AuraRenderer.sparkleCount(false, AnimationIntensity.NORMAL));
		assertEquals(7, AuraRenderer.sparkleCount(false, AnimationIntensity.FULL));
	}

	// ------------------------------------------------------------------
	// Pre-rendered glow raster (§13: no image allocation in render())
	// ------------------------------------------------------------------

	@Test
	public void glowRasterIsPreRenderedOnceAndReused()
	{
		BufferedImage glow = renderer.getGlowRaster();
		assertNotNull(glow);
		assertEquals(AuraRenderer.GLOW_RASTER_PX, glow.getWidth());
		assertSame(glow, renderer.getGlowRaster()); // cached, never rebuilt
		// golden core is actually golden and opaque-ish; edge fades out
		int center = glow.getRGB(glow.getWidth() / 2, glow.getHeight() / 2);
		assertTrue("core must be visible", ((center >>> 24) & 0xFF) > 150);
		int corner = glow.getRGB(1, 1);
		assertEquals("corner must be transparent", 0, (corner >>> 24) & 0xFF);
	}

	// ------------------------------------------------------------------
	// Composited render paths (headless smoke: effect draws iff selected)
	// ------------------------------------------------------------------

	private int paintedPixels(AuraState aura, boolean reducedMotion)
	{
		config.reducedMotion = reducedMotion;
		BufferedImage canvas = new BufferedImage(200, 200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		renderer.renderUnder(g, aura, 60, 60, 80, 80, 1234, config);
		renderer.renderOver(g, aura, 60, 60, 80, 80, 1234, config);
		g.dispose();
		int painted = 0;
		for (int y = 0; y < canvas.getHeight(); y++)
		{
			for (int x = 0; x < canvas.getWidth(); x++)
			{
				if (((canvas.getRGB(x, y) >>> 24) & 0xFF) != 0)
				{
					painted++;
				}
			}
		}
		return painted;
	}

	@Test
	public void noneDrawsNothingGoldenDrawsRadiance()
	{
		assertEquals(0, paintedPixels(AuraState.NONE, false));
		int prestige = paintedPixels(AuraState.PRESTIGE, false);
		int golden = paintedPixels(AuraState.GOLDEN, false);
		assertTrue("prestige ring paints", prestige > 0);
		assertTrue("golden radiance paints far more than the prestige ring", golden > prestige * 3);
	}

	@Test
	public void reducedMotionStillShowsAStaticAura()
	{
		// §6.4: aura remains visible as a STATIC ring/glow under reduced motion
		assertTrue(paintedPixels(AuraState.GOLDEN, true) > 0);
		assertTrue(paintedPixels(AuraState.PRESTIGE, true) > 0);
	}
}

package com.runie.overlay;

import com.runie.support.TestRunieConfig;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Evolution burst VFX (rework part 2): one-shot, ms-driven, self-clipping to
 * its progress window, reduced-motion aware; the GOLDEN variant is the grander
 * L120 milestone burst.
 */
public class EvolutionBurstTest
{
	private static boolean drawsAnything(double progress, boolean golden, boolean reducedMotion)
	{
		AuraRenderer renderer = new AuraRenderer();
		TestRunieConfig config = new TestRunieConfig();
		config.reducedMotion = reducedMotion;
		BufferedImage canvas = new BufferedImage(160, 160, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		renderer.renderEvolutionBurst(g, 48, 48, 64, 64, progress, golden, config);
		g.dispose();
		for (int y = 0; y < canvas.getHeight(); y += 2)
		{
			for (int x = 0; x < canvas.getWidth(); x += 2)
			{
				if ((canvas.getRGB(x, y) >>> 24) != 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	@Test
	public void burstRendersWithinItsWindowOnly()
	{
		assertTrue(drawsAnything(0.05, false, false));
		assertTrue(drawsAnything(0.6, false, false));
		assertFalse("past the window: nothing may draw", drawsAnything(1.0, false, false));
		assertFalse(drawsAnything(1.5, false, false));
		assertFalse(drawsAnything(-0.1, false, false));
	}

	@Test
	public void goldenVariantRendersToo()
	{
		assertTrue(drawsAnything(0.3, true, false));
		assertTrue("golden burst window is longer",
			AuraRenderer.GOLDEN_BURST_MS > AuraRenderer.EVOLUTION_BURST_MS);
	}

	@Test
	public void reducedMotionStillShowsAFadingGlow()
	{
		// reduced motion keeps a static fading glow but drops ring + particles;
		// something must still draw so the moment is not lost entirely
		assertTrue(drawsAnything(0.3, false, true));
		assertTrue(drawsAnything(0.3, true, true));
	}
}

package com.runie;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Bug 5 root cause: {@code nowMs - lastCombatMs < WINDOW} overflowed when
 * {@code lastCombatMs} still held the {@code Long.MIN_VALUE} "never hit"
 * sentinel, evaluating TRUE — the danger flag stayed stuck on from plugin
 * start, so the hatch reveal was deferred every frame while logged in and only
 * slipped out around logout. The window check must treat the sentinel as
 * "not in combat".
 */
public class RuniePluginDangerTest
{
	private static final long NOW = 1_784_721_600_000L;

	@Test
	public void sentinelNeverHitMeansNotInCombat_noOverflow()
	{
		// the old expression: NOW - Long.MIN_VALUE overflows negative → was "true"
		assertTrue("precondition: the naive check really does overflow",
			NOW - Long.MIN_VALUE < 10_000);
		assertFalse(RuniePlugin.withinCombatWindow(NOW, Long.MIN_VALUE));
	}

	@Test
	public void recentHitIsInsideTheWindow()
	{
		assertTrue(RuniePlugin.withinCombatWindow(NOW, NOW - 1));
		assertTrue(RuniePlugin.withinCombatWindow(NOW, NOW - 9_999));
	}

	@Test
	public void oldHitIsOutsideTheWindow()
	{
		assertFalse(RuniePlugin.withinCombatWindow(NOW, NOW - 10_000));
		assertFalse(RuniePlugin.withinCombatWindow(NOW, NOW - 86_400_000L));
	}
}

package com.runie.support;

import com.runie.assets.ArtStyle;
import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import javax.imageio.ImageIO;

/**
 * Test-only art seeding. Since the real animation frames no longer ship in the
 * jar (they stream into RUNELITE_DIR/runie/assets via {@link
 * com.runie.core.RunieAssetService}), tests that need resolvable art point an
 * {@link com.runie.assets.AssetLoader} at a cache directory populated here with
 * synthetic sprite sheets. The whole roster is seeded once per JVM and shared.
 */
public final class TestArt
{
	public static final int IDLE_FRAMES = 16;

	private static Path shared;

	private TestArt()
	{
	}

	/**
	 * A cache dir seeded with a 16-frame idle sheet for every roster line × style
	 * × stage, plus a baked golden (aura_gold) fallback for grubnak stage 3 in
	 * both styles. Seeded once and reused. Point AssetLoader at it via
	 * {@code loader.setAssetCacheDir(TestArt.roster(registry))}.
	 */
	public static synchronized Path roster(CreatureRegistry registry)
	{
		if (shared != null)
		{
			return shared;
		}
		try
		{
			Path cache = Files.createTempDirectory("runie-art-cache");
			for (CreatureDefinition def : registry.all())
			{
				for (ArtStyle style : ArtStyle.values())
				{
					for (int stage = 1; stage <= 3; stage++)
					{
						writeSheet(cache, def.getId(), style, stage, "idle", IDLE_FRAMES);
					}
				}
			}
			// baked golden variant exists ONLY for grubnak stage 3 (optional fallback)
			writeSheet(cache, "grubnak", ArtStyle.KAWAII, 3, "aura_gold", IDLE_FRAMES);
			writeSheet(cache, "grubnak", ArtStyle.PIXEL, 3, "aura_gold", IDLE_FRAMES);
			shared = cache;
			return cache;
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	/** Write a synthetic horizontal sprite sheet of {@code n} equal cells. */
	public static void writeSheet(Path cache, String id, ArtStyle style, int stage, String anim, int n)
		throws IOException
	{
		int cellW = 16;
		int cellH = 24;
		BufferedImage sheet = new BufferedImage(cellW * n, cellH, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = sheet.createGraphics();
		for (int i = 0; i < n; i++)
		{
			// distinct-ish opaque block per cell so frames are non-empty
			g.setColor(new Color(60 + (i * 9) % 180, 120, 200, 255));
			g.fillRect(i * cellW + 2, 3, cellW - 4, cellH - 6);
		}
		g.dispose();
		Path target = cache.resolve(String.format(
			"com/runie/creatures/%s/art/%s/stage%d/%s/%s.%d.png",
			id, style.getFolderToken(), stage, anim, anim, n));
		Files.createDirectories(target.getParent());
		ImageIO.write(sheet, "png", target.toFile());
	}
}

package com.runie.support;

import com.runie.core.RunieClock;
import com.runie.state.RunieAccountState;
import com.runie.state.RunieStateStore;

/**
 * Settable clock with the SAME persisted monotonic-watermark guard as the
 * production {@code GuardedClock} ({@code System.currentTimeMillis()} replaced
 * by a settable base). Lets tests simulate a user rolling the system clock
 * back/forward and assert the watermark clamps it.
 */
public class GuardedFakeClock implements RunieClock
{
	private final RunieStateStore stateStore;
	private long systemMs;

	public GuardedFakeClock(RunieStateStore stateStore, long startMs)
	{
		this.stateStore = stateStore;
		this.systemMs = startMs;
	}

	/** Simulates setting the OS clock (backwards allowed — that's the point). */
	public void setSystemMs(long ms)
	{
		this.systemMs = ms;
	}

	public void advanceMs(long ms)
	{
		this.systemMs += ms;
	}

	@Override
	public long nowMs()
	{
		if (!stateStore.hasState())
		{
			return systemMs;
		}
		RunieAccountState state = stateStore.getState();
		long wm = state.clockWatermarkMs;
		long now = Math.max(systemMs, wm);
		if (now > wm)
		{
			state.clockWatermarkMs = now;
			stateStore.markDirtyLow();
		}
		return now;
	}

	@Override
	public long elapsedMs()
	{
		return systemMs;
	}
}

package com.runie.support;

import com.runie.core.RunieRandom;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Deterministic RNG test double with separate queues for {@code nextDouble}
 * (tier sampling) and {@code nextInt} (creature selection). When a queue is
 * empty, defaults are returned (0.0 / 0), which sample the FIRST option — a
 * rigged always-Common / always-first-creature stream.
 */
public class ScriptedRandom implements RunieRandom
{
	private final Deque<Double> doubles = new ArrayDeque<>();
	private final Deque<Integer> ints = new ArrayDeque<>();

	public ScriptedRandom queueDoubles(double... values)
	{
		for (double v : values)
		{
			doubles.add(v);
		}
		return this;
	}

	public ScriptedRandom queueInts(int... values)
	{
		for (int v : values)
		{
			ints.add(v);
		}
		return this;
	}

	@Override
	public double nextDouble()
	{
		Double v = doubles.poll();
		return v == null ? 0.0 : v;
	}

	@Override
	public int nextInt(int bound)
	{
		Integer v = ints.poll();
		return v == null ? 0 : Math.min(v, bound - 1);
	}
}

package com.runie.support;

import com.runie.core.RunieClock;

/** Settable clock for deterministic economy tests. */
public class FakeClock implements RunieClock
{
	private long nowMs;
	private long elapsedMs;

	public FakeClock(long startMs)
	{
		this.nowMs = startMs;
	}

	@Override
	public long nowMs()
	{
		return nowMs;
	}

	@Override
	public long elapsedMs()
	{
		return elapsedMs;
	}

	public void setNowMs(long nowMs)
	{
		this.nowMs = nowMs;
	}

	public void advanceMs(long ms)
	{
		nowMs += ms;
		elapsedMs += ms;
	}

	public void advanceDays(int days)
	{
		advanceMs(days * 86_400_000L);
	}
}

package com.runie.support;

import com.runie.RunieConfig;
import com.runie.assets.ArtStyle;
import com.runie.config.AnimationIntensity;
import com.runie.config.CompanionScale;

/** Mutable RunieConfig for animation/overlay tests and headless mockups. */
