			{"ratterbone", "79"}, {"wisplume", "40"}, {"glabbertongue", "18"},
			{"stingrilla", "62"}, {"grimshank", "83"}, {"howlrend", "36"},
			{"moankettle", "51"}, {"gillcrest", "78"}, {"knucklemaw", "22"},
			{"tidecoil", "44"},
