package com.runie.assets;

import com.google.gson.Gson;
import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import java.awt.image.BufferedImage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Full-roster rendering guarantee: every one of the 42 lines resolves art by
 * the §5.1 convention alone (no per-creature special cases) — real frames
 * where they've been dropped in (Grubnak), bundled placeholder tiles
 * everywhere else — and a missing frame set degrades to the fallback chain,
 * never an exception.
 */
public class RosterArtCoverageTest
{
	private CreatureRegistry registry;
	private AssetLoader loader;

	@Before
	public void setUp() throws Exception
	{
		registry = new CreatureRegistry(new Gson());
		registry.load();
		loader = new AssetLoader();
		// art streams into a cache at runtime rather than shipping in-jar
		loader.setAssetCacheDir(com.runie.support.TestArt.roster(registry));
	}

	@Test
	public void all42ResolveIdleArtInBothStylesAtEveryStage()
	{
		for (CreatureDefinition def : registry.all())
		{
			for (ArtStyle style : ArtStyle.values())
			{
				for (int stage = 1; stage <= 3; stage++)
				{
					AnimationClip clip = loader.getIdleClip(def.getId(), style, stage, 64);
					assertNotNull(def.getId() + '/' + style + "/stage" + stage
						+ ": no idle art (real or placeholder)", clip);
					BufferedImage thumb = loader.getThumbnail(def.getId(), style, stage, 52);
					assertNotNull(def.getId() + ": no grid thumbnail", thumb);
				}
			}
		}
	}

	@Test
	public void missingAnimationFallsBackWithoutThrowing()
	{
		// no roster creature bundles a "walk" clip yet: loader must return
		// null (callers keep the last good frame / silhouette), never throw
		for (CreatureDefinition def : registry.all())
		{
			assertNull(loader.getClip(def.getId(), ArtStyle.KAWAII, 1, "walk", 12, true, 64));
		}
	}

	@Test
	public void missingStyleServesThePlaceholderViaKawaiiFallback()
	{
		// fallbackling (test resource) has ONLY kawaii art: a pixel request
		// must still render — the §5.2 fallback chain is what guarantees a
		// placeholder-or-better for any style the user picks
		assertNotNull(loader.getIdleClip("fallbackling", ArtStyle.PIXEL, 1, 64));
	}
}

package com.runie.assets;

import java.awt.image.BufferedImage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * AssetLoader: §5.1 path convention, frame-count discovery by probing,
 * style fallback chain, pre-scaling, caching (Epic 6, §12.1).
 */
public class AssetLoaderTest
{
	private AssetLoader loader;

	@Before
	public void setUp() throws Exception
	{
		// Real art streams into a cache at runtime (not bundled in-jar), so point
		// the loader at a synthetic seeded cache; fallbackling stays on the classpath
		// to exercise the legacy frame_000 + style-fallback paths.
		com.runie.creatures.CreatureRegistry registry = new com.runie.creatures.CreatureRegistry(new com.google.gson.Gson());
		registry.load();
		loader = new AssetLoader();
		loader.setAssetCacheDir(com.runie.support.TestArt.roster(registry));
	}

	@Test
	public void framePathFollowsSection5Convention()
	{
		assertEquals("/com/runie/creatures/grubnak/art/kawaii/stage2/idle/frame_000.png",
			AssetLoader.framePath("grubnak", ArtStyle.KAWAII, 2, "idle", 0));
		assertEquals("/com/runie/creatures/grubnak/art/pixel/stage3/aura_gold/frame_011.png",
			AssetLoader.framePath("grubnak", ArtStyle.PIXEL, 3, "aura_gold", 11));
	}

	@Test
	public void idleDirWithFullSequenceDiscoversAllFrames()
	{
		// grubnak ships a real pre-rendered 16-frame idle loop (frame_000..015)
		AnimationClip clip = loader.getIdleClip("grubnak", ArtStyle.KAWAII, 1, 128);
		assertNotNull(clip);
		assertEquals(16, clip.frameCount());
		assertEquals(1000 / AssetLoader.IDLE_FPS, clip.getPerFrameMs());
		assertTrue(clip.isLoop());
	}

	@Test
	public void idleDirWithOnlyFrameZeroDiscoversOneFrame()
	{
		// every bundled creature ships a full loop now, so use the synthetic
		// test-resource creature (exactly one frame_000.png on the classpath)
		// to prove probing stops at the first miss: one frame ⇒ clip of size 1
		AnimationClip clip = loader.getIdleClip("fallbackling", ArtStyle.KAWAII, 1, 128);
		assertNotNull(clip);
		assertEquals(1, clip.frameCount());
		assertSame(clip.firstFrame(), clip.frameAt(1_234_567));
	}

	@Test
	public void goldenVariantExistsForStage3InBothStyles()
	{
		assertNotNull(loader.getGoldenClip("grubnak", ArtStyle.KAWAII, 3, 128));
		assertNotNull(loader.getGoldenClip("grubnak", ArtStyle.PIXEL, 3, 128));
	}

	@Test
	public void goldenVariantAbsentForStage1()
	{
		assertNull(loader.getGoldenClip("grubnak", ArtStyle.KAWAII, 1, 128));
	}

	@Test
	public void placeholderCreaturesResolveInBothStyles()
	{
		assertNotNull(loader.getIdleClip("malgrave", ArtStyle.KAWAII, 3, 64));
		assertNotNull(loader.getIdleClip("cindermaw", ArtStyle.PIXEL, 2, 64));
	}

	@Test
	public void unknownCreatureReturnsNullNotThrow()
	{
		assertNull(loader.getIdleClip("no_such_creature", ArtStyle.KAWAII, 1, 128));
		assertNull(loader.getThumbnail("no_such_creature", ArtStyle.PIXEL, 1, 64));
	}

	@Test
	public void missingStyleFallsBackToKawaii()
	{
		// test-resource creature bundled with KAWAII art only
		AnimationClip viaPixel = loader.getClip("fallbackling", ArtStyle.PIXEL, 1, "idle", 12, true, 64);
		assertNotNull("pixel request must fall back to kawaii", viaPixel);
	}

	@Test
	public void framesArePreScaledToTarget()
	{
		AnimationClip clip = loader.getIdleClip("grubnak", ArtStyle.KAWAII, 1, 96);
		assertNotNull(clip);
		int max = Math.max(clip.getWidth(), clip.getHeight());
		assertTrue("expected max edge <= 96, got " + max, max <= 96);
	}

	@Test
	public void clipsAreCachedPerKey()
	{
		AnimationClip a = loader.getIdleClip("grubnak", ArtStyle.KAWAII, 1, 128);
		AnimationClip b = loader.getIdleClip("grubnak", ArtStyle.KAWAII, 1, 128);
		assertSame(a, b);
	}

	@Test
	public void thumbnailIsFirstIdleFrame()
	{
		BufferedImage thumb = loader.getThumbnail("grubnak", ArtStyle.KAWAII, 1, 64);
		assertNotNull(thumb);
		assertTrue(Math.max(thumb.getWidth(), thumb.getHeight()) <= 64);
	}
}

package com.runie.assets;

import com.runie.support.TestRunieConfig;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Kawaii easter-egg epic: unlock detection ("uwu" in public chat, exact trimmed
 * case-insensitive match), machine-global flag persistence, effective-style
 * enforcement (locked Kawaii resolves to Pixel everywhere), and idempotency.
 */
public class ArtStyleServiceTest
{
	/** Stands in for the hidden machine-global ConfigManager key. */
	private final Map<String, String> configStore = new HashMap<>();
	private TestRunieConfig config;
	private ArtStyleService service;

	@Before
	public void setUp()
	{
		configStore.clear();
		config = new TestRunieConfig();
		service = newService();
	}

	/** New service instance over the SAME persisted store (fresh session). */
	private ArtStyleService newService()
	{
		return new ArtStyleService(config,
			() -> configStore.get("kawaiiUnlocked"),
			v -> configStore.put("kawaiiUnlocked", v));
	}

	private static ChatMessage chat(ChatMessageType type, String message)
	{
		return new ChatMessage(null, type, "Zezima", message, null, 0);
	}

	private boolean say(String message)
	{
		return service.handleChatMessage(chat(ChatMessageType.PUBLICCHAT, message));
	}

	// ------------------------------------------------------------------
	// Unlock detection
	// ------------------------------------------------------------------

	@Test
	public void uwuInPublicChatUnlocks()
	{
		assertFalse(service.isKawaiiUnlocked());
		assertTrue(say("uwu"));
		assertTrue(service.isKawaiiUnlocked());
		assertEquals("true", configStore.get("kawaiiUnlocked"));
	}

	@Test
	public void detectionIsCaseInsensitive()
	{
		for (String magic : new String[]{"UWU", "UwU", "uWu"})
		{
			setUp(); // fresh service + store per variant
			assertTrue(magic, say(magic));
			assertTrue(magic, service.isKawaiiUnlocked());
		}
	}

	@Test
	public void surroundingWhitespaceIsTrimmed()
	{
		assertTrue(say(" uwu "));
		assertTrue(service.isKawaiiUnlocked());
	}

	@Test
	public void nearMissesDoNotUnlock()
	{
		for (String miss : new String[]{"uwuu", "buwu", "owo", "uwu!", "u w u", "uwu uwu", "say uwu", ""})
		{
			assertFalse(miss, say(miss));
		}
		assertFalse(service.isKawaiiUnlocked());
		assertFalse(configStore.containsKey("kawaiiUnlocked"));
	}

	@Test
	public void nullMessageIsIgnored()
	{
		assertFalse(say(null));
		assertFalse(service.handleChatMessage(null));
		assertFalse(service.isKawaiiUnlocked());
	}

	@Test
	public void nonPublicChatTypesAreIgnored()
	{
		ChatMessageType[] ignored = {
			ChatMessageType.GAMEMESSAGE, ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT,
			ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_CHAT, ChatMessageType.SPAM,
			ChatMessageType.NPC_EXAMINE, ChatMessageType.CONSOLE,
		};
		for (ChatMessageType type : ignored)
		{
			assertFalse(type.name(), service.handleChatMessage(chat(type, "uwu")));
		}
		assertFalse(service.isKawaiiUnlocked());
	}

	@Test
	public void modPublicChatCountsAsPlayerChat()
	{
		assertTrue(service.handleChatMessage(chat(ChatMessageType.MODCHAT, "uwu")));
		assertTrue(service.isKawaiiUnlocked());
	}

	// ------------------------------------------------------------------
	// Idempotency + persistence
	// ------------------------------------------------------------------

	@Test
	public void reTriggerAfterUnlockIsNoOp()
	{
		assertTrue(say("uwu"));
		assertFalse(say("uwu"));   // no second celebration
		assertFalse(say("UWU"));
		assertTrue(service.isKawaiiUnlocked());
		assertEquals("true", configStore.get("kawaiiUnlocked"));
	}

	@Test
	public void unlockPersistsAcrossSessions()
	{
		assertTrue(say("uwu"));
		// fresh service over the same persisted store = client restart /
		// account switch (flag is machine-global, not per-account JSON)
		ArtStyleService next = newService();
		assertTrue(next.isKawaiiUnlocked());
		assertFalse(next.handleChatMessage(chat(ChatMessageType.PUBLICCHAT, "uwu"))); // still idempotent
	}

	@Test
	public void lockedByDefaultOnFreshStore()
	{
		assertFalse(service.isKawaiiUnlocked());
		assertFalse(Boolean.parseBoolean(configStore.get("kawaiiUnlocked")));
	}

	// ------------------------------------------------------------------
	// Effective-style enforcement
	// ------------------------------------------------------------------

	@Test
	public void kawaiiSelectedWhileLockedResolvesToPixel()
	{
		config.artStyle = ArtStyle.KAWAII;
		assertEquals(ArtStyle.PIXEL, service.effectiveStyle());
	}

	@Test
	public void pixelSelectionIsAlwaysAvailable()
	{
		config.artStyle = ArtStyle.PIXEL;
		assertEquals(ArtStyle.PIXEL, service.effectiveStyle());
		say("uwu");
		assertEquals(ArtStyle.PIXEL, service.effectiveStyle()); // unlock never forces a switch
	}

	@Test
	public void kawaiiWorksFullyOnceUnlocked()
	{
		config.artStyle = ArtStyle.KAWAII;
		assertEquals(ArtStyle.PIXEL, service.effectiveStyle());
		assertTrue(say("uwu"));
		assertEquals(ArtStyle.KAWAII, service.effectiveStyle()); // flips immediately, same session
	}

	@Test
	public void unlockPersistedFromPriorSessionEnablesKawaii()
	{
		configStore.put("kawaiiUnlocked", "true");
		config.artStyle = ArtStyle.KAWAII;
		assertEquals(ArtStyle.KAWAII, newService().effectiveStyle());
	}

	// ------------------------------------------------------------------
	// Selection gating — Kawaii is UNAVAILABLE until unlocked (Bug 3)
	// ------------------------------------------------------------------

	/** Service wired with a live artStyle writer, like production ConfigManager. */
	private ArtStyleService newGatingService()
	{
		return new ArtStyleService(config,
			() -> configStore.get("kawaiiUnlocked"),
			v -> configStore.put("kawaiiUnlocked", v),
			styleName -> config.artStyle = ArtStyle.valueOf(styleName));
	}

	@Test
	public void pickingKawaiiWhileLockedSnapsBackToPixel()
	{
		ArtStyleService gated = newGatingService();
		config.artStyle = ArtStyle.KAWAII;        // player picks the locked option
		assertTrue(gated.enforceKawaiiLock());    // plugin reacts to the config change
		assertEquals(ArtStyle.PIXEL, config.artStyle());
		assertEquals(ArtStyle.PIXEL, gated.effectiveStyle());
	}

	@Test
	public void legacyStoredKawaiiWhileLockedFallsBackToPixelAtLoad()
	{
		// old install persisted Kawaii before the lock existed; startUp() enforces
		config.artStyle = ArtStyle.KAWAII;
		ArtStyleService fresh = newGatingService();
		assertFalse(fresh.isKawaiiUnlocked());
		assertTrue(fresh.enforceKawaiiLock());
		assertEquals(ArtStyle.PIXEL, config.artStyle());
	}

	@Test
	public void enforceKeepsKawaiiOnceUnlocked()
	{
		ArtStyleService gated = newGatingService();
		config.artStyle = ArtStyle.KAWAII;
		assertTrue(gated.handleChatMessage(chat(ChatMessageType.PUBLICCHAT, "uwu")));
		assertFalse(gated.enforceKawaiiLock());   // unlocked: Kawaii is selectable
		assertEquals(ArtStyle.KAWAII, config.artStyle());
		assertEquals(ArtStyle.KAWAII, gated.effectiveStyle());
	}

	@Test
	public void enforceIsANoOpForPixelSelection()
	{
		ArtStyleService gated = newGatingService();
		config.artStyle = ArtStyle.PIXEL;
		assertFalse(gated.enforceKawaiiLock());
		assertEquals(ArtStyle.PIXEL, config.artStyle());
	}

	@Test
	public void unlockThenPickKawaiiStaysAcrossSessions()
	{
		ArtStyleService gated = newGatingService();
		assertTrue(gated.handleChatMessage(chat(ChatMessageType.PUBLICCHAT, "uwu")));
		config.artStyle = ArtStyle.KAWAII;
		// fresh session over the same persisted flag: still selectable
		assertFalse(newGatingService().enforceKawaiiLock());
		assertEquals(ArtStyle.KAWAII, config.artStyle());
	}
}

package com.runie.assets;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The bundled assets manifest ({@code com/runie/assets_manifest.json},
 * generated by tools/gen_manifest.py) is the contract between the approved
 * sprite set and the §5.1 resource tree that tools/fetch_assets.sh installs
 * into. This test locks: full 42 x 3 x 2 coverage, path-convention agreement
 * with AssetLoader, and that EVERY manifest target resolves on the classpath
 * right now (real art or marked placeholder — the build must never ship a
 * blank grid slot).
 */
public class AssetManifestTest
{
	private static final String MANIFEST_PATH = "/com/runie/assets_manifest.json";

	private CreatureRegistry registry;
	private JsonArray entries;

	@Before
	public void setUp() throws Exception
	{
		registry = new CreatureRegistry(new Gson());
		registry.load();
		try (InputStream in = AssetManifestTest.class.getResourceAsStream(MANIFEST_PATH))
		{
			assertNotNull("bundled assets manifest missing: " + MANIFEST_PATH, in);
			try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				JsonObject manifest = new Gson().fromJson(r, JsonObject.class);
				entries = manifest.getAsJsonArray("entries");
			}
		}
	}

	@Test
	public void coversFullRosterTimesStagesTimesStyles()
	{
		assertEquals(40 * 3 * 2, entries.size());
		Set<String> seen = new HashSet<>();
		Set<String> imageIds = new HashSet<>();
		Set<String> urls = new HashSet<>();
		for (int i = 0; i < entries.size(); i++)
		{
			JsonObject e = entries.get(i).getAsJsonObject();
			String cid = e.get("creatureId").getAsString();
			assertTrue("manifest creature not in registry: " + cid, registry.contains(cid));
			int stage = e.get("stage").getAsInt();
			assertTrue("bad stage " + stage, stage >= 1 && stage <= 3);
			String style = e.get("style").getAsString();
			assertTrue("bad style " + style,
				style.equals(ArtStyle.KAWAII.getFolderToken()) || style.equals(ArtStyle.PIXEL.getFolderToken()));
			assertTrue("duplicate cell", seen.add(cid + '|' + style + '|' + stage));
			assertTrue("duplicate imageId", imageIds.add(e.get("imageId").getAsString()));
			assertTrue("duplicate url", urls.add(e.get("url").getAsString()));
		}
		// every registry line appears with all 6 cells
		for (CreatureDefinition def : registry.all())
		{
			for (String style : new String[]{"kawaii", "pixel"})
			{
				for (int stage = 1; stage <= 3; stage++)
				{
					assertTrue("missing manifest cell: " + def.getId() + '/' + style + "/stage" + stage,
						seen.contains(def.getId() + '|' + style + '|' + stage));
				}
			}
		}
	}

	@Test
	public void resourcePathsFollowTheSection5Convention()
	{
		for (int i = 0; i < entries.size(); i++)
		{
			JsonObject e = entries.get(i).getAsJsonObject();
			ArtStyle style = "pixel".equals(e.get("style").getAsString()) ? ArtStyle.PIXEL : ArtStyle.KAWAII;
			String expected = AssetLoader.framePath(
				e.get("creatureId").getAsString(), style, e.get("stage").getAsInt(), "idle", 0);
			assertEquals(expected, "/" + e.get("resourcePath").getAsString());
		}
	}

	@Test
	public void downloadIndexCoversWholeRosterIdleArt()
	{
		// Art no longer ships in the jar (10 MB Plugin Hub limit) — it streams from
		// the repo's assets branch via RunieAssetService. Lock that the bundled
		// download index (art_index.json) covers an idle sheet for EVERY roster
		// line × style × stage, so nothing is left un-fetchable.
		JsonObject idx;
		try (InputStream in = AssetManifestTest.class.getResourceAsStream("/com/runie/art_index.json");
			Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			assertNotNull("art_index.json missing from resources", in);
			idx = new Gson().fromJson(r, JsonObject.class);
		}
		catch (Exception ex)
		{
			throw new AssertionError("failed reading art index", ex);
		}

		String base = idx.get("base").getAsString();
		assertTrue("index base must be an https github URL: " + base,
			base.startsWith("https://") && base.contains("github"));
		assertTrue("index needs a version", idx.get("version").getAsInt() >= 1);
		JsonArray files = idx.getAsJsonArray("files");
		assertTrue("index must list art files", files.size() > 0);

		Set<String> paths = new HashSet<>();
		for (int i = 0; i < files.size(); i++)
		{
			paths.add(files.get(i).getAsString());
		}

		for (CreatureDefinition def : registry.all())
		{
			for (String style : new String[]{"kawaii", "pixel"})
			{
				for (int stage = 1; stage <= 3; stage++)
				{
					String prefix = "com/runie/creatures/" + def.getId()
						+ "/art/" + style + "/stage" + stage + "/idle/idle.";
					boolean found = paths.stream().anyMatch(p -> p.startsWith(prefix));
					assertTrue("download index missing idle art: " + prefix, found);
				}
			}
		}
	}

	@Test
	public void urlsAreAbsoluteHttpsPngs()
	{
		for (int i = 0; i < entries.size(); i++)
		{
			JsonObject e = entries.get(i).getAsJsonObject();
			String url = e.get("url").getAsString();
			assertTrue(url, url.startsWith("https://") && url.endsWith(".png"));
			assertTrue(url, url.contains(e.get("imageId").getAsString()));
		}
	}
}

package com.runie.ui;

import com.google.gson.Gson;
import com.runie.assets.ArtStyleService;
import com.runie.assets.AssetLoader;
import com.runie.core.AccountContext;
import com.runie.core.EggService;
import com.runie.core.GachaService;
import com.runie.core.ProgressionService;
import com.runie.core.RunieRandom;
import com.runie.core.XpDeltaService;
import com.runie.creatures.CreatureRegistry;
import com.runie.overlay.RuniePullOverlay;
import com.runie.state.CreatureInstance;
import com.runie.state.RunieStateStore;
import com.runie.state.TestStateStores;
import com.runie.support.FakeClock;
import com.runie.support.TestRunieConfig;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.swing.SwingUtilities;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Timing/sync regression tests for the live-play bug: "+1 Egg floats over the
 * companion, but the panel egg balance / banked XP only caught up minutes
 * later." The toast polls the live {@link EggService} balance every frame; the
 * panel used to refresh only on rare events (level-ups, hatches, region
 * loads). The fix wires a third XpDelta listener — registered AFTER EggService
 * and ProgressionService, exactly like {@code RuniePlugin.startUp()} — that
 * refreshes the panel from the SAME validated delta, so toast, credited
 * balance, creature XP mirror, and panel all derive from one event.
 */
public class PanelDeltaSyncTest
{
	private static final long HASH = 7777L;

	private Path dir;
	private ScheduledExecutorService executor;
	private RunieStateStore store;
	private XpDeltaService xp;
	private EggService eggs;
	private ProgressionService progression;
	private RuniePanel panel;
	private long accountHash = AccountContext.NO_ACCOUNT;

	/** Balance sampled inside the panel-sync listener — the toast's poll value. */
	private final List<Integer> toastPollSamples = new ArrayList<>();
	/** Creature XP sampled inside the panel-sync listener — the mirror's value. */
	private final List<Long> creatureXpSamples = new ArrayList<>();
	private int refreshLaterCalls;

	@Before
	public void setUp() throws IOException
	{
		System.setProperty("java.awt.headless", "true");
		dir = Files.createTempDirectory("runie-panel-sync-test");
		executor = Executors.newSingleThreadScheduledExecutor();
		Gson gson = new Gson();
		CreatureRegistry registry = new CreatureRegistry(gson);
		registry.load();
		store = TestStateStores.create(gson, executor, registry, dir);
		FakeClock clock = new FakeClock(1_784_678_400_000L);
		eggs = new EggService(store, clock);
		progression = new ProgressionService(store, registry, eggs);
		GachaService gacha = new GachaService(eggs, registry, store, clock, RunieRandom.seeded(20260719L));
		AssetLoader assets = new AssetLoader();
		TestRunieConfig config = new TestRunieConfig();
		ArtStyleService styles = new ArtStyleService(config, () -> "true", v -> { });
		RuniePullOverlay pullOverlay = new RuniePullOverlay(registry, progression, assets, styles,
			config, clock, Runnable::run);
		UiContext ctx = new UiContext(eggs, gacha, progression, registry, assets, styles,
			store, config, pullOverlay, Runnable::run, () -> false);
		panel = new RuniePanel(ctx);

		// EXACT RuniePlugin.startUp() wiring order: economy + progression first,
		// then the same-delta panel sync. The sync listener therefore observes
		// the post-delta state — assert that by sampling what the toast polls.
		xp = new XpDeltaService(() -> accountHash, store);
		xp.addListener(eggs);
		xp.addListener(progression);
		xp.addListener((skill, delta, newTotalXp) ->
		{
			toastPollSamples.add(eggs.getEggBalance());
			creatureXpSamples.add(progression.getActiveCreature().map(c -> c.xp).orElse(-1L));
			refreshLaterCalls++;
			panel.refreshLater();
		});
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	// -- helpers ----------------------------------------------------------

	private void login()
	{
		accountHash = HASH;
		xp.handleGameStateChanged(GameState.LOGGING_IN);
		xp.handleGameStateChanged(GameState.LOGGED_IN);
	}

	private void warmUp()
	{
		xp.handleGameTick();
		xp.handleGameTick();
	}

	private void stat(Skill s, int newXp)
	{
		xp.handleStatChanged(new StatChanged(s, newXp, 1, 1));
	}

	private void flushEdt()
	{
		try
		{
			SwingUtilities.invokeAndWait(() -> { });
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	private void deployCreature(String id)
	{
		CreatureInstance c = CreatureInstance.fresh(0L);
		store.getState().creatures.owned.put(id, c);
		assertTrue(progression.setActiveCreature(id));
	}

	// -- tests ------------------------------------------------------------

	@Test
	public void deltaUpdatesToastBalanceCreatureXpAndPanelFromTheSameEvent()
	{
		login();
		stat(Skill.FLETCHING, 300_000);       // first sighting: snapshot only, loads state
		warmUp();
		deployCreature("grubnak");

		// +60k: one 50k accrual egg + 10k banked, mirrored 1:1 onto grubnak —
		// whose level jump past the ~L40 stage-2 threshold ALSO grants the +1
		// evolution-reward egg on this very delta (balance 2 total)
		stat(Skill.FLETCHING, 360_000);

		// the sync listener (= the toast's poll) saw the credited balance,
		// including the evolution reward, and the mirrored creature XP inside
		// the SAME event dispatch — nothing is deferred to a later tick/timer
		assertEquals(1, toastPollSamples.size());
		assertEquals(2, (int) toastPollSamples.get(0));
		assertEquals(60_000L, (long) creatureXpSamples.get(0));
		assertEquals(1, refreshLaterCalls);

		// and the panel, refreshed by that same delta, shows the same numbers
		flushEdt();
		assertEquals("2 Eggs", panel.headerEggsText());
		assertTrue("panel banked-XP line must show the post-delta bank: "
			+ panel.headerTodayText(),
			panel.headerTodayText().contains(String.format("%,d / %,d XP", 10_000L, 50_000L)));
	}

	@Test
	public void rapidBurstCoalescesButPanelEndsOnFinalValue()
	{
		login();
		stat(Skill.MINING, 0);
		warmUp();

		// 4 deltas inside one tick — every event credits immediately (ladder:
		// eggs 1-3 cost 50k each, the 4th costs 100k, so the last 50k banks)
		for (int i = 1; i <= 4; i++)
		{
			stat(Skill.MINING, i * 50_000);
			assertEquals("credit must land with delta " + i,
				Math.min(i, 3), (int) toastPollSamples.get(i - 1));
		}
		assertEquals(50_000L, eggs.getBankedXp());
		// ...and after one EDT hop the panel shows the final, fully-credited state
		flushEdt();
		flushEdt(); // second hop: a re-queue scheduled mid-refresh completes here
		assertEquals("3 Eggs", panel.headerEggsText());
	}

	@Test
	public void loginBurstGrantsNothingAndPanelShowsZero()
	{
		login();
		// a maxed account's lifetime XP streams in on login
		for (Skill s : Skill.values())
		{
			stat(s, 13_034_431);
		}
		warmUp();
		flushEdt();

		assertTrue("login burst must never reach the panel-sync listener", toastPollSamples.isEmpty());
		assertEquals(0, eggs.getEggBalance());
		assertEquals("0 Eggs", panel.headerEggsText());
	}

	@Test
	public void reRefreshingThePanelNeverDoubleCounts()
	{
		login();
		stat(Skill.SMITHING, 100_000);
		warmUp();
		stat(Skill.SMITHING, 150_000);        // exactly one 50k egg

		flushEdt();
		assertEquals("1 Egg", panel.headerEggsText());

		// refresh is a pure read: repeating it (EDT-queued or direct) must not
		// change the balance or the display
		panel.refreshLater();
		panel.refreshLater();
		flushEdt();
		SwingUtilities.invokeLater(panel::refresh);
		flushEdt();
		assertEquals(1, eggs.getEggBalance());
		assertEquals(0L, eggs.getBankedXp());
		assertEquals("1 Egg", panel.headerEggsText());
	}
}

package com.runie.core;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Duplicate-star tier math (rework part 3) and shiny rate selection (part 4):
 * count → (tier color, stars-in-tier 1–5), caps at 25, and the per-tier shiny
 * ladder incl. the post-Pink 1.0% rate.
 */
public class StarTierTest
{
	@Test
	public void zeroStarsHasNoTier()
	{
		assertNull(StarTier.tierFor(0));
		assertNull(StarTier.tierFor(-3));
		assertEquals(0, StarTier.starsInTier(0));
	}

	@Test
	public void tierBoundariesAreFivesBronzeToPink()
	{
		assertEquals(StarTier.BRONZE, StarTier.tierFor(1));
		assertEquals(StarTier.BRONZE, StarTier.tierFor(5));
		assertEquals(StarTier.SILVER, StarTier.tierFor(6));
		assertEquals(StarTier.SILVER, StarTier.tierFor(10));
		assertEquals(StarTier.GOLD, StarTier.tierFor(11));
		assertEquals(StarTier.GOLD, StarTier.tierFor(15));
		assertEquals(StarTier.RED, StarTier.tierFor(16));
		assertEquals(StarTier.RED, StarTier.tierFor(20));
		assertEquals(StarTier.PINK, StarTier.tierFor(21));
		assertEquals(StarTier.PINK, StarTier.tierFor(25));
