package com.runie.core;

import com.google.gson.Gson;
import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import com.runie.state.CreatureInstance;
import com.runie.state.RunieAccountState;
import com.runie.state.RunieStateStore;
import com.runie.state.TestStateStores;
import com.runie.support.FakeClock;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.Skill;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * ProgressionService: XP mirror, OSRS-table leveling, evolution thresholds,
 * prestige (irreversible, single tier, golden aura at 120) — Epic 4, §12.1.
 */
public class ProgressionServiceTest
{
	private static final long HASH = 333L;

	private Path dir;
	private ScheduledExecutorService executor;
	private CreatureRegistry registry;
	private RunieStateStore store;
	private EggService eggs;
	private ProgressionService progression;

	@Before
	public void setUp() throws IOException
	{
		dir = Files.createTempDirectory("runie-progression-test");
		executor = Executors.newSingleThreadScheduledExecutor();
		registry = new CreatureRegistry(new Gson());
		registry.load();
		store = TestStateStores.create(new Gson(), executor, registry, dir);
		store.switchAccount(HASH);
		eggs = new EggService(store, new FakeClock(1_784_721_600_000L));
		progression = new ProgressionService(store, registry, eggs);
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private RunieAccountState state()
	{
		return store.getState();
	}

	private CreatureInstance own(String id)
	{
		CreatureInstance c = CreatureInstance.fresh(0);
		state().creatures.owned.put(id, c);
		return c;
	}

	private CreatureInstance ownActive(String id)
	{
		CreatureInstance c = own(id);
		state().creatures.active = id;
		return c;
	}

	private void gain(int delta)
	{
		progression.onXpGained(Skill.WOODCUTTING, delta, 0);
	}

	// -- XP mirror ---------------------------------------------------------

	@Test
	public void xpMirrorsOneToOneToActiveCreature()
	{
		CreatureInstance c = ownActive("grubnak");
		gain(1_000);
		gain(234);
		assertEquals(1_234, c.xp);
		assertEquals(1_234, c.lifetimeXp);
	}

	@Test
	public void noActiveCreatureIsANoOp()
	{
		CreatureInstance c = own("grubnak"); // owned but NOT active
		gain(5_000);
		assertEquals(0, c.xp); // XP feeds no one — no accrual, no banking
		assertEquals(0, c.lifetimeXp);
	}

	@Test
	public void xpFeedsOnlyTheActiveCreature()
	{
		CreatureInstance a = ownActive("grubnak");
		CreatureInstance b = own("skitterscour");
		gain(100);
		assertTrue(progression.setActiveCreature("skitterscour"));
		gain(50);
		assertEquals(100, a.xp);
		assertEquals(50, b.xp);
	}

	// -- active-companion selection ------------------------------------------

	@Test
	public void setActiveCreatureRequiresOwnership()
	{
		own("grubnak");
		assertFalse(progression.setActiveCreature("malgrave")); // in registry, not owned
		assertFalse(progression.setActiveCreature("not-a-creature"));
		assertTrue(progression.setActiveCreature("grubnak"));
		assertEquals("grubnak", progression.getActiveCreatureId().get());
		assertTrue(progression.setActiveCreature(null)); // clear selection
		assertFalse(progression.getActiveCreatureId().isPresent());
		gain(100); // and mirroring stops
		assertEquals(0, state().creatures.owned.get("grubnak").xp);
	}

	@Test
	public void setActiveNotifiesListenersImmediately()
	{
		// Bug 2: making a creature active must signal observers right away —
		// the plugin wires this to AnimationService.refresh(), so the companion
		// deploys without waiting for an unrelated config change.
		own("grubnak");
		own("skitterscour");
		List<String> changes = new ArrayList<>();
		progression.addListener(new ProgressionService.ProgressionListener()
		{
			@Override
			public void onActiveChanged(String activeCreatureId)
			{
				changes.add(activeCreatureId);
			}
		});

		assertTrue(progression.setActiveCreature("grubnak"));
		assertEquals(1, changes.size());
		assertEquals("grubnak", changes.get(0));

		assertFalse(progression.setActiveCreature("malgrave")); // not owned: rejected, NO signal
		assertEquals(1, changes.size());

		assertTrue(progression.setActiveCreature("skitterscour"));
		assertTrue(progression.setActiveCreature(null)); // clearing also signals (undeploy)
		assertEquals(3, changes.size());
		assertEquals("skitterscour", changes.get(1));
		assertEquals(null, changes.get(2));
	}

	// -- leveling ---------------------------------------------------------------

	@Test
	public void levelFollowsOsrsTableWithCap99()
	{
		CreatureInstance c = ownActive("grubnak");
		assertEquals(1, progression.levelOf("grubnak"));
		gain(83);
		assertEquals(2, progression.levelOf("grubnak")); // L2 = 83 XP
		c.xp = XpTable.xpForLevel(99) - 1;
		assertEquals(98, progression.levelOf("grubnak"));
		gain(1);
		assertEquals(99, progression.levelOf("grubnak"));
		gain(50_000_000); // beyond 13,034,431 — un-prestiged cap binds
		assertEquals(99, progression.levelOf("grubnak"));
	}

	@Test
	public void levelUpEventFires()
	{
		ownActive("grubnak");
		List<int[]> ups = new ArrayList<>();
		progression.addListener(new ProgressionService.ProgressionListener()
		{
			@Override
			public void onLevelUp(String creatureId, int oldLevel, int newLevel)
			{
				assertEquals("grubnak", creatureId);
				ups.add(new int[]{oldLevel, newLevel});
			}
		});
		gain(82); // still level 1
		assertTrue(ups.isEmpty());
		gain(1);  // 83 → level 2
		assertEquals(1, ups.size());
		assertEquals(1, ups.get(0)[0]);
		assertEquals(2, ups.get(0)[1]);
	}

	// -- evolution ---------------------------------------------------------------

	@Test
	public void evolutionThresholdsFollowRoster()
	{
		// grubnak stages unlock at L1 / L40 / L75; ratterbone's stage 3 at L78
		CreatureDefinition grubnak = registry.byId("grubnak");
		assertEquals(1, progression.evolutionStageFor(grubnak, 39, false));
		assertEquals(2, progression.evolutionStageFor(grubnak, 40, false));
		assertEquals(2, progression.evolutionStageFor(grubnak, 74, false));
		assertEquals(3, progression.evolutionStageFor(grubnak, 75, false));

		CreatureDefinition ratterbone = registry.byId("ratterbone");
		assertEquals(2, progression.evolutionStageFor(ratterbone, 77, false));
		assertEquals(3, progression.evolutionStageFor(ratterbone, 78, false));
	}

	@Test
	public void stageChangeSignalFiresOnEvolution()
	{
		CreatureInstance c = ownActive("grubnak");
		List<int[]> evolutions = new ArrayList<>();
		progression.addListener(new ProgressionService.ProgressionListener()
		{
			@Override
			public void onStageChange(String creatureId, int oldStage, int newStage)
			{
				assertEquals("grubnak", creatureId);
				evolutions.add(new int[]{oldStage, newStage});
			}
		});

		c.xp = XpTable.xpForLevel(40) - 1;      // level 39, stage 1
		assertEquals(1, progression.currentStageOf("grubnak"));
		gain(1);                                 // → level 40: stage 1 → 2
		assertEquals(2, progression.currentStageOf("grubnak"));

		c.xp = XpTable.xpForLevel(75) - 1;      // level 74, stage 2
		gain(1);                                 // → level 75: stage 2 → 3
		assertEquals(3, progression.currentStageOf("grubnak"));

		assertEquals(2, evolutions.size());
		assertEquals(2, evolutions.get(0)[1]);
		assertEquals(3, evolutions.get(1)[1]);
	}

	// -- evolution egg reward (rework part 2) ----------------------------------

	@Test
	public void evolutionGrantsOneEggPerCrossing()
	{
		CreatureInstance c = ownActive("grubnak"); // stages at L1 / L40 / L75
		assertEquals(0, eggs.getEggBalance());

		c.xp = XpTable.xpForLevel(40) - 1;
		gain(1);                                   // stage 1 → 2
		assertEquals(1, eggs.getEggBalance());
		assertEquals(2, c.evolutionRewardedStage);

		c.xp = XpTable.xpForLevel(75) - 1;
		gain(1);                                   // stage 2 → 3
		assertEquals(2, eggs.getEggBalance());
		assertEquals(3, c.evolutionRewardedStage);
	}

	@Test
	public void evolutionCrossingTwoStagesInOneDeltaGrantsTwoEggs()
	{
		CreatureInstance c = ownActive("grubnak");
		gain((int) XpTable.xpForLevel(80));        // level 1 → 80: stage 1 → 3 in one delta
		assertEquals(3, progression.currentStageOf("grubnak"));
		assertEquals(2, eggs.getEggBalance());
		assertEquals(3, c.evolutionRewardedStage);
	}

	@Test
	public void evolutionRewardIsGrantedExactlyOncePerCrossing()
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(40) - 1;
		gain(1);                                   // stage 1 → 2: +1 egg
		assertEquals(1, eggs.getEggBalance());

		// simulate a re-check / replayed crossing: drop XP below the threshold
		// and cross again — the persisted watermark must block a second grant
		c.xp = XpTable.xpForLevel(40) - 1;
		gain(1);
		assertEquals(1, eggs.getEggBalance());     // still exactly one
		assertEquals(2, c.evolutionRewardedStage);
	}

	@Test
	public void evolutionRewardWatermarkSurvivesReload() throws IOException
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(40) - 1;
		gain(1);                                   // stage 1 → 2: +1 egg
		assertEquals(1, eggs.getEggBalance());
		store.flush();

		// relaunch: fresh store + services over the same file
		RunieStateStore store2 = TestStateStores.create(new Gson(), executor, registry, dir);
		store2.switchAccount(HASH);
		EggService eggs2 = new EggService(store2, new FakeClock(1_784_721_600_000L));
		ProgressionService progression2 = new ProgressionService(store2, registry, eggs2);
		CreatureInstance c2 = store2.getState().creatures.owned.get("grubnak");
		assertEquals(2, c2.evolutionRewardedStage); // watermark persisted
		assertEquals(1, store2.getState().eggs.balance);

		// replay the same crossing after reload — no double grant
		c2.xp = XpTable.xpForLevel(40) - 1;
		progression2.onXpGained(Skill.WOODCUTTING, 1, 0);
		assertEquals(1, eggs2.getEggBalance());

		// the NEXT crossing still grants normally
		c2.xp = XpTable.xpForLevel(75) - 1;
		progression2.onXpGained(Skill.WOODCUTTING, 1, 0);
		assertEquals(2, eggs2.getEggBalance());
	}

	@Test
	public void legacyCreatureMidStageGetsNoRetroactiveGrant()
	{
		// legacy documents pre-date evolutionRewardedStage (0): a creature already
		// at stage 2 crossing to 3 must earn ONE egg, not a retroactive two
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(60);             // stage 2 already
		c.evolutionRewardedStage = 0;              // as loaded from an old save
		gain((int) (XpTable.xpForLevel(75) - XpTable.xpForLevel(60))); // cross 2 → 3
		assertEquals(1, eggs.getEggBalance());
		assertEquals(3, c.evolutionRewardedStage);
	}

	// -- golden L120 milestone reward (owner request) ---------------------------

	@Test
	public void reachingLevel120GrantsFiveEggsExactlyOnce()
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(99);
		assertEquals(PrestigeResult.SUCCESS, progression.prestige("grubnak"));
		assertEquals(0, eggs.getEggBalance());
		assertFalse(c.goldenRewardGranted);

		c.xp = XpTable.xpForLevel(120) - 1;        // level 119
		gain(1);                                   // → level 120: golden milestone
		assertEquals(120, progression.levelOf("grubnak"));
		assertEquals(Economy.GOLDEN_MILESTONE_REWARD_EGGS, eggs.getEggBalance()); // +5
		assertTrue(c.goldenRewardGranted);

		// simulate a re-check / replayed crossing: drop XP below the cap and
		// cross again — the persisted grant-once flag must block a second grant
		c.xp = XpTable.xpForLevel(120) - 1;
		gain(1);
		assertEquals(Economy.GOLDEN_MILESTONE_REWARD_EGGS, eggs.getEggBalance()); // still exactly 5
	}

	@Test
	public void goldenMilestoneGrantSurvivesReload() throws IOException
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(99);
		assertEquals(PrestigeResult.SUCCESS, progression.prestige("grubnak"));
		c.xp = XpTable.xpForLevel(120) - 1;
		gain(1);                                   // milestone: +5 eggs
		assertEquals(5, eggs.getEggBalance());
		store.flush();

		// relaunch: fresh store + services over the same file
		RunieStateStore store2 = TestStateStores.create(new Gson(), executor, registry, dir);
		store2.switchAccount(HASH);
		EggService eggs2 = new EggService(store2, new FakeClock(1_784_721_600_000L));
		ProgressionService progression2 = new ProgressionService(store2, registry, eggs2);
		CreatureInstance c2 = store2.getState().creatures.owned.get("grubnak");
		assertTrue(c2.goldenRewardGranted);        // watermark persisted

		// replay the crossing after reload — no double grant
		c2.xp = XpTable.xpForLevel(120) - 1;
		progression2.onXpGained(Skill.WOODCUTTING, 1, 0);
		assertEquals(5, eggs2.getEggBalance());
	}

	@Test
	public void legacyCreatureAlreadyPast120GetsNoRetroactiveGrant()
	{
		// legacy documents pre-date goldenRewardGranted (false): a creature that
		// mastered L120 before the rework must NOT be granted retroactively —
		// its level is capped at 120 and can never cross the milestone again
		CreatureInstance c = ownActive("grubnak");
		c.prestigeCount = 1;
		c.xp = XpTable.xpForLevel(120) + 5_000_000; // already past 120 in the old save
		c.goldenRewardGranted = false;              // as loaded from a legacy document
		assertEquals(120, progression.levelOf("grubnak"));

		gain(1_000_000);                            // more XP at the cap — no crossing
		assertEquals(0, eggs.getEggBalance());      // no retroactive grant
		assertFalse(c.goldenRewardGranted);
	}

	@Test
	public void stageCrossingsStillGrantOneEggEachAlongsideTheMilestone()
	{
		// the two evolution crossings keep their +1 each; L120 adds +5 on top
		CreatureInstance c = ownActive("grubnak"); // stages at L1 / L40 / L75
		gain((int) XpTable.xpForLevel(99));        // crosses both stages → +2 eggs
		assertEquals(2, eggs.getEggBalance());
		assertEquals(PrestigeResult.SUCCESS, progression.prestige("grubnak"));

		c.xp = XpTable.xpForLevel(120) - 1;
		gain(1);                                   // golden milestone → +5 more
		assertEquals(7, eggs.getEggBalance());
	}

	// -- prestige -------------------------------------------------------------

	@Test
	public void prestigeRequiresLevel99()
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(99) - 1; // level 98
		assertEquals(PrestigeResult.NOT_LEVEL_99, progression.prestige("grubnak"));
		assertEquals(XpTable.xpForLevel(99) - 1, c.xp); // untouched
		assertEquals(0, c.prestigeCount);
		assertEquals(PrestigeResult.NOT_OWNED, progression.prestige("malgrave"));
	}

	@Test
	public void prestigeResetsXpRaisesCapKeepsLookAndLifetimeXp()
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(99);
		c.lifetimeXp = XpTable.xpForLevel(99);
		List<String> prestiged = new ArrayList<>();
		progression.addListener(new ProgressionService.ProgressionListener()
		{
			@Override
			public void onPrestige(String creatureId)
			{
				prestiged.add(creatureId);
			}
		});

		assertEquals(PrestigeResult.SUCCESS, progression.prestige("grubnak"));
		assertEquals(0, c.xp);                                   // reset to level 1
		assertEquals(1, progression.levelOf("grubnak"));
		assertEquals(1, c.prestigeCount);
		assertEquals(XpTable.xpForLevel(99), c.lifetimeXp);      // preserved
		assertEquals(3, progression.currentStageOf("grubnak"));  // keeps final evolved look
		assertEquals(AuraState.PRESTIGE, progression.auraOf("grubnak"));
		assertEquals(1, prestiged.size());

		gain((int) XpTable.xpForLevel(100));                     // cap is now 120
		assertEquals(100, progression.levelOf("grubnak"));
	}

	@Test
	public void prestigeIsIrreversibleAndSingleTier()
	{
		CreatureInstance c = ownActive("grubnak");
		c.xp = XpTable.xpForLevel(99);
		assertEquals(PrestigeResult.SUCCESS, progression.prestige("grubnak"));

		// back at L99 (and even L120): no second reset path, no un-prestige API
		c.xp = XpTable.xpForLevel(120);
		assertEquals(PrestigeResult.ALREADY_PRESTIGED, progression.prestige("grubnak"));
		assertEquals(XpTable.xpForLevel(120), c.xp); // nothing reset
		assertEquals(1, c.prestigeCount);
	}

	@Test
	public void goldenAuraAtLevel120()
	{
		CreatureInstance c = ownActive("grubnak");
		assertEquals(AuraState.NONE, progression.auraOf("grubnak")); // un-prestiged: no aura
		c.xp = XpTable.xpForLevel(99);
		assertEquals(PrestigeResult.SUCCESS, progression.prestige("grubnak"));

		c.xp = XpTable.xpForLevel(120) - 1;                      // level 119
		assertEquals(AuraState.PRESTIGE, progression.auraOf("grubnak"));
		gain(1);                                                 // → level 120: fully mastered
		assertEquals(120, progression.levelOf("grubnak"));
		assertEquals(AuraState.GOLDEN, progression.auraOf("grubnak"));

		gain(100_000_000);                                       // prestiged cap binds at 120
		assertEquals(120, progression.levelOf("grubnak"));
		assertEquals(AuraState.GOLDEN, progression.auraOf("grubnak"));
	}

	// -- collection accessors ------------------------------------------------

	@Test
	public void collectionAccessorsReflectOwnership()
	{
		assertEquals(0, progression.ownedCount());
		assertFalse(progression.isOwned("grubnak"));
		assertEquals(0, progression.levelOf("grubnak"));
		assertEquals(0, progression.currentStageOf("grubnak"));
		assertEquals(AuraState.NONE, progression.auraOf("grubnak"));

		own("grubnak");
		own("cindermaw");
		assertEquals(2, progression.ownedCount());
		assertTrue(progression.isOwned("cindermaw"));
		assertTrue(progression.ownedCreatureIds().contains("grubnak"));
		assertTrue(progression.getCreature("grubnak").isPresent());
		assertFalse(progression.getCreature("malgrave").isPresent());
	}
}

package com.runie.core;

import com.runie.assets.AnimationClip;
import com.runie.assets.ArtStyle;
import com.google.gson.Gson;
import com.runie.assets.AssetLoader;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * RunieAssetService: on first launch it streams the art bundle (listed in the
 * bundled art_index.json) from github.com into RUNELITE_DIR/runie/assets, only
 * writes files that validate as real PNGs, skips what it already has, and marks
 * the sync complete only when nothing failed. AssetLoader then resolves art from
 * that cache.
 */
public class RunieAssetServiceTest
{
	private ScheduledExecutorService executor;
	private AssetLoader loader;

	@Before
	public void setUp()
	{
		executor = Executors.newSingleThreadScheduledExecutor();
		loader = new AssetLoader();
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	/** A real, sliceable PNG (wide enough for a 16-cell idle sheet). */
	private static byte[] png()
	{
		try
		{
			BufferedImage img = new BufferedImage(320, 32, BufferedImage.TYPE_INT_ARGB);
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(img, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	@Test
	public void downloadsCachesAndIsIdempotent() throws IOException
	{
		byte[] png = png();
		RunieAssetService svc = new RunieAssetService(loader, executor, url -> png, new Gson());
		Path cache = Files.createTempDirectory("runie-dl-test");

		int downloaded = svc.syncNow(cache, null, null);
		assertTrue("should fetch the whole indexed roster", downloaded > 400);

		// a known idle sheet + a frame_000 landed and are valid images
		Path sheet = cache.resolve("com/runie/creatures/grubnak/art/kawaii/stage1/idle/idle.16.png");
		assertTrue(Files.isRegularFile(sheet));
		assertNotNull(ImageIO.read(sheet.toFile()));
		// completion marker written since nothing failed
		assertTrue(Files.isRegularFile(cache.resolve(".version")));

		// second run: everything cached → nothing re-downloaded
		assertEquals(0, svc.syncNow(cache, null, null));
	}

	@Test
	public void rejectsCorruptDownloadsAndRetriesNextLaunch() throws IOException
	{
		RunieAssetService svc = new RunieAssetService(loader, executor, url -> "definitely not a png".getBytes(), new Gson());
		Path cache = Files.createTempDirectory("runie-dl-bad");

		int downloaded = svc.syncNow(cache, null, null);
		assertEquals("corrupt payloads must never be written", 0, downloaded);
		assertFalse("no completion marker while downloads fail", Files.isRegularFile(cache.resolve(".version")));
	}

	@Test
	public void assetLoaderResolvesDownloadedArtFromCache() throws IOException
	{
		byte[] png = png();
		RunieAssetService svc = new RunieAssetService(loader, executor, url -> png, new Gson());
		Path cache = Files.createTempDirectory("runie-dl-load");
		svc.syncNow(cache, null, null);

		loader.setAssetCacheDir(cache);
		AnimationClip idle = loader.getIdleClip("grubnak", ArtStyle.KAWAII, 1, 128);
		assertNotNull("downloaded idle sheet must resolve", idle);
		assertEquals(16, idle.frameCount());
	}
}

package com.runie.core;

import com.google.gson.Gson;
import com.runie.state.RunieStateStore;
import com.runie.state.TestStateStores;
import com.runie.support.FakeClock;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.Skill;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Egg accrual (rework part 1): daily-reset tier costs, NO daily cap, raw 1:1
 * banked-XP carry across day rollover (only the daily egg ordinal resets),
 * spend/credit rules. Eggs are the single currency.
 */
public class EggServiceTest
{
	private static final long HASH = 4242L;
	// 2026-07-17T12:00:00Z
	private static final long NOON_UTC = 1_784_721_600_000L + 43_200_000L - 86_400_000L;

	private Path dir;
	private ScheduledExecutorService executor;
	private RunieStateStore store;
	private FakeClock clock;
	private EggService eggs;

	@Before
	public void setUp() throws IOException
	{
		dir = Files.createTempDirectory("runie-egg-test");
		executor = Executors.newSingleThreadScheduledExecutor();
		store = TestStateStores.create(new Gson(), executor, null, dir);
		store.switchAccount(HASH);
		clock = new FakeClock(NOON_UTC);
		eggs = new EggService(store, clock);
		eggs.rolloverDayIfNeeded(); // anchor the day
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private void gain(int xp)
	{
		eggs.onXpGained(Skill.ATTACK, xp, 0);
	}

	// -- the tier ladder ---------------------------------------------------

	@Test
	public void tierCostLadderMatchesSpec()
	{
		// k = 1,2,3 → 50k; 4,5 → 100k; 6,7,8 → 250k; ≥9 → 500k forever
		assertEquals(50_000L, Economy.eggCostXp(1));
		assertEquals(50_000L, Economy.eggCostXp(2));
		assertEquals(50_000L, Economy.eggCostXp(3));
		assertEquals(100_000L, Economy.eggCostXp(4));
		assertEquals(100_000L, Economy.eggCostXp(5));
		assertEquals(250_000L, Economy.eggCostXp(6));
		assertEquals(250_000L, Economy.eggCostXp(7));
		assertEquals(250_000L, Economy.eggCostXp(8));
		assertEquals(500_000L, Economy.eggCostXp(9));
		assertEquals(500_000L, Economy.eggCostXp(10));
		assertEquals(500_000L, Economy.eggCostXp(1_000)); // stays 500k — no cap tier
		assertEquals(50_000L, Economy.eggCostXp(0));      // defensive clamp
	}

	@Test
	public void accrualWalksTheLadderExactly()
	{
		gain(49_999);
		assertEquals(0, eggs.getEggBalance());
		assertEquals(49_999L, eggs.getBankedXp());
		gain(1);                        // 50,000 → egg 1
		assertEquals(1, eggs.getEggBalance());
		assertEquals(0L, eggs.getBankedXp());
		assertEquals(50_000L, eggs.getNextEggCostXp()); // egg 2 still 50k

		gain(100_000);                  // eggs 2 + 3
		assertEquals(3, eggs.getEggBalance());
		assertEquals(100_000L, eggs.getNextEggCostXp()); // egg 4 costs 100k

		gain(100_000);                  // egg 4
		gain(100_000);                  // egg 5
		assertEquals(5, eggs.getEggBalance());
		assertEquals(250_000L, eggs.getNextEggCostXp()); // egg 6 costs 250k

		gain(750_000);                  // eggs 6,7,8
		assertEquals(8, eggs.getEggBalance());
		assertEquals(500_000L, eggs.getNextEggCostXp()); // egg 9 costs 500k
	}

	@Test
	public void singleBigDeltaCrossesMultipleTiers()
	{
		// 50k*3 + 100k*2 + 250k*3 = 1.1M for eggs 1–8, +500k → egg 9
		gain(1_600_000);
		assertEquals(9, eggs.getEggBalance());
		assertEquals(9, eggs.getEggsEarnedToday());
		assertEquals(0L, eggs.getBankedXp());
	}

	@Test
	public void noDailyCap_ninthAndBeyondStayAt500k()
	{
		gain(1_100_000);                // eggs 1–8
		assertEquals(8, eggs.getEggBalance());
		for (int k = 9; k <= 30; k++)   // 22 more eggs, all at the flat 500k rate
		{
			gain(500_000);
			assertEquals(k, eggs.getEggBalance());
			assertEquals(500_000L, eggs.getNextEggCostXp());
		}
		assertEquals(30, eggs.getEggsEarnedToday()); // way past the old 25 cap
	}

	@Test
	public void fractionalProgressAccumulatesAcrossDeltas()
	{
		gain(20_000);
		gain(20_000);
		assertEquals(0, eggs.getEggBalance());
		assertEquals(40_000L, eggs.getBankedXp());
		gain(10_000);
		assertEquals(1, eggs.getEggBalance());
		assertEquals(0L, eggs.getBankedXp());
	}

	// -- daily reset ---------------------------------------------------------

	@Test
	public void dailyResetRestartsTheLadder()
	{
		gain(1_600_000);                // 9 eggs today; next would cost 500k
		assertEquals(500_000L, eggs.getNextEggCostXp());

		clock.advanceDays(1);
		eggs.rolloverDayIfNeeded();

		assertEquals(0, eggs.getEggsEarnedToday());
		assertEquals(50_000L, eggs.getNextEggCostXp()); // ladder restarts at 50k
		assertEquals(9, eggs.getEggBalance());          // balance untouched

		gain(50_000);                                   // first egg of the new day
		assertEquals(10, eggs.getEggBalance());
	}

	@Test
	public void rolloverCarriesBankedXpRawOneToOne()
	{
		gain(1_100_000 + 250_000);      // 8 eggs + half of the 500k ninth egg
		assertEquals(8, eggs.getEggBalance());
		assertEquals(250_000L, eggs.getBankedXp());

		clock.advanceDays(1);
		eggs.rolloverDayIfNeeded();

		// banked XP is a continuous running counter: carried RAW, untouched;
		// only the daily egg ordinal (tier position) resets
		assertEquals(250_000L, eggs.getBankedXp());
		assertEquals(0, eggs.getEggsEarnedToday());
		assertEquals(50_000L, eggs.getNextEggCostXp()); // ladder restarted at day-1 rate

		// the intended morning windfall: the raw carry settles against the
		// cheaper restarted ladder on the next gain (50k+50k+50k+100k = 250k)
		gain(1);
		assertEquals(12, eggs.getEggBalance());
		assertEquals(4, eggs.getEggsEarnedToday());
		assertEquals(1L, eggs.getBankedXp());
	}

	@Test
	public void multiDayOfflineRolloverJustReanchors()
	{
		gain(75_000);                   // 1 egg + 25k banked toward egg 2
		clock.advanceDays(4);
		eggs.rolloverDayIfNeeded();
		assertEquals(1, eggs.getEggBalance());
		assertEquals(0, eggs.getEggsEarnedToday());
		assertEquals(25_000L, eggs.getBankedXp()); // raw carry — untouched
	}

	@Test
	public void dayNeverRegresses()
	{
		gain(50_000);
		String day = store.getState().eggs.currentDayUtc;
		clock.advanceMs(-2 * 86_400_000L);  // clock rolled back (GuardedClock prevents in prod; defend anyway)
		eggs.rolloverDayIfNeeded();
		assertEquals(day, store.getState().eggs.currentDayUtc);
		assertEquals(1, eggs.getEggBalance());
	}

	// -- initial snapshot / safety --------------------------------------------

	@Test
	public void noDeltasMeansNoEggs_initialSnapshotGrantsNothing()
	{
		assertEquals(0, eggs.getEggBalance());
		assertEquals(0L, eggs.getBankedXp());
		assertEquals(0, eggs.getEggsEarnedToday());
	}

	@Test
	public void nonPositiveDeltaIsRejectedDefensively()
	{
		eggs.onXpGained(Skill.ATTACK, 0, 0);
		eggs.onXpGained(Skill.ATTACK, -5_000, 0);
		assertEquals(0, eggs.getEggBalance());
		assertEquals(0L, eggs.getBankedXp());
	}

	@Test
	public void xpAccruesEggsButTouchesNoCreatureWhenNoneActive()
	{
		assertTrue(store.getState().creatures.owned.isEmpty());
		assertEquals(null, store.getState().creatures.active);
		gain(100_000);
		assertEquals(2, eggs.getEggBalance());
		assertTrue(store.getState().creatures.owned.isEmpty());
	}

	// -- spending / crediting ----------------------------------------------

	@Test
	public void spendEggsRequiresSufficientBalance()
	{
		gain(150_000); // 3 eggs
		assertFalse(eggs.spendEggs(4, "hatch"));
		assertEquals(3, eggs.getEggBalance());
		assertTrue(eggs.spendEggs(3, "hatch"));
		assertEquals(0, eggs.getEggBalance());
	}

	@Test
	public void creditEggsIsOutsideTheAccrualLadder()
	{
		gain(50_000); // 1 accrued egg, ladder at k=1
		eggs.creditEggs(2, EggSource.EVOLUTION);
		assertEquals(3, eggs.getEggBalance());
		assertEquals(1, eggs.getEggsEarnedToday()); // ladder position untouched
		assertEquals(50_000L, eggs.getNextEggCostXp());
	}

	// -- persistence ------------------------------------------------------------

	@Test
	public void bankedProgressSurvivesSaveLoad() throws IOException
	{
		gain(1_100_000 + 123_456);      // 8 eggs + 123,456 banked toward the 500k ninth
		store.flush();

		RunieStateStore reloaded = TestStateStores.create(new Gson(), executor, null, dir);
		reloaded.switchAccount(HASH);
		EggService eggs2 = new EggService(reloaded, clock);
		assertEquals(8, eggs2.getEggBalance());
		assertEquals(8, eggs2.getEggsEarnedToday());
		assertEquals(123_456L, eggs2.getBankedXp());
		assertEquals(500_000L, eggs2.getNextEggCostXp());

		eggs2.onXpGained(Skill.ATTACK, 500_000 - 123_456, 0);
		assertEquals(9, eggs2.getEggBalance());
	}
}

package com.runie.core;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Seedable RNG: identical seeds → identical sequences (gacha fixtures depend on this). */
public class RunieRandomTest
{
	@Test
	public void sameSeedSameSequence()
	{
		RunieRandom a = RunieRandom.seeded(20260717L);
		RunieRandom b = RunieRandom.seeded(20260717L);
		for (int i = 0; i < 1000; i++)
		{
			assertEquals(a.nextDouble(), b.nextDouble(), 0.0);
			assertEquals(a.nextInt(17), b.nextInt(17));
		}
	}

	@Test
	public void boundsRespected()
	{
		RunieRandom r = RunieRandom.seeded(42L);
		for (int i = 0; i < 10_000; i++)
		{
			double d = r.nextDouble();
			assertTrue(d >= 0.0 && d < 1.0);
			int n = r.nextInt(6);
			assertTrue(n >= 0 && n < 6);
		}
	}

	@Test
	public void differentSeedsDiverge()
	{
		RunieRandom a = RunieRandom.seeded(1L);
		RunieRandom b = RunieRandom.seeded(2L);
		boolean diverged = false;
		for (int i = 0; i < 100 && !diverged; i++)
		{
			diverged = a.nextInt(1_000_000) != b.nextInt(1_000_000);
		}
		assertTrue(diverged);
	}
}

package com.runie.core;

import com.google.gson.Gson;
import com.runie.state.RunieStateStore;
import com.runie.state.TestStateStores;
import com.runie.support.FakeClock;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The #1-risk tests (architecture §12.1 row 1): the XP-snapshot-safe pipeline
 * must never turn a login burst, reconnect burst, account switch, negative
 * delta, or implausible spike into a grant.
 */
public class XpDeltaServiceTest
{
	private static final long HASH_A = 1111L;
	private static final long HASH_B = 2222L;

	private Path dir;
	private ScheduledExecutorService executor;
	private RunieStateStore store;
	private XpDeltaService xp;
	private EggService eggs;
	private FakeClock clock;
	private long accountHash = AccountContext.NO_ACCOUNT;

	private final List<int[]> received = new ArrayList<>(); // [skillOrdinal, delta, newXp]

	@Before
	public void setUp() throws IOException
	{
		dir = Files.createTempDirectory("runie-xp-test");
		executor = Executors.newSingleThreadScheduledExecutor();
		store = TestStateStores.create(new Gson(), executor, null, dir);
		clock = new FakeClock(1_784_678_400_000L); // 2026-07-17T00:00:00Z-ish
		xp = new XpDeltaService(() -> accountHash, store);
		eggs = new EggService(store, clock);
		xp.addListener(eggs);
		xp.addListener((skill, delta, newXp) -> received.add(new int[]{skill.ordinal(), delta, newXp}));
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	// -- helpers --------------------------------------------------------

	private void login(long hash)
	{
		accountHash = hash;
		xp.handleGameStateChanged(GameState.LOGGING_IN);
		xp.handleGameStateChanged(GameState.LOGGED_IN);
	}

	private void loginBurst(int xpPerSkill)
	{
		for (Skill s : Skill.values())
		{
			xp.handleStatChanged(new StatChanged(s, xpPerSkill, 99, 99));
		}
	}

	private void warmUp()
	{
		xp.handleGameTick();
		xp.handleGameTick();
	}

	private void stat(Skill s, int newXp)
	{
		xp.handleStatChanged(new StatChanged(s, newXp, 1, 1));
	}

	// -- the big one ----------------------------------------------------

	@Test
	public void freshLoginOfMaxedAccountGrantsNothing()
	{
		login(HASH_A);
		loginBurst(13_034_431);   // a maxed account's per-skill XP streams in
		warmUp();

		assertTrue(received.isEmpty());
		assertEquals(0, eggs.getEggBalance());
		assertEquals(0L, eggs.getBankedXp());

		// after warm-up, genuine XP flows normally
		stat(Skill.ATTACK, 13_034_431 + 60_000);
		assertEquals(1, received.size());
		assertEquals(60_000, received.get(0)[1]);
		assertEquals(1, eggs.getEggBalance()); // 60k xp = first 50k egg + 10k banked
		assertEquals(10_000L, eggs.getBankedXp());
	}

	@Test
	public void perSkillSentinel_firstEventIsSnapshotOnly()
	{
		login(HASH_A);
		stat(Skill.MINING, 500_000);   // first sighting of Mining: snapshot only (also binds the account + restarts grace)
		warmUp();
		assertTrue(received.isEmpty());
		stat(Skill.MINING, 500_100);   // now a trusted delta
		assertEquals(1, received.size());
		assertEquals(100, received.get(0)[1]);
	}

	@Test
	public void graceWindowDropsDeltas()
	{
		login(HASH_A);
		stat(Skill.FISHING, 1_000);    // snapshot (sentinel)
		stat(Skill.FISHING, 1_500);    // in grace: snapshot-only, delta dropped
		xp.handleGameTick();
		stat(Skill.FISHING, 1_800);    // still in grace (1 tick left)
		assertTrue(received.isEmpty());
		assertFalse(xp.isWarmedUp());

		xp.handleGameTick();
		assertTrue(xp.isWarmedUp());
		stat(Skill.FISHING, 2_000);    // grace over: trusted delta from latest snapshot
		assertEquals(1, received.size());
		assertEquals(200, received.get(0)[1]);
	}

	@Test
	public void hopReArmsSentinels()
	{
		login(HASH_A);
		stat(Skill.ATTACK, 10_000);    // binds account; grace restarts (normative §3.2)
		warmUp();
		stat(Skill.ATTACK, 10_050);
		assertEquals(1, received.size());

		xp.handleGameStateChanged(GameState.HOPPING);
		// re-delivered XP burst after the hop must be snapshot-only
		stat(Skill.ATTACK, 10_050);
		stat(Skill.ATTACK, 10_050);
		assertEquals(1, received.size());

		xp.handleGameStateChanged(GameState.LOGGED_IN);
		warmUp();
		stat(Skill.ATTACK, 10_150);
		assertEquals(2, received.size());
		assertEquals(100, received.get(1)[1]);
	}

	@Test
	public void connectionLostAndLoginScreenReArm()
	{
		for (GameState gs : new GameState[]{GameState.CONNECTION_LOST, GameState.LOGIN_SCREEN})
		{
			received.clear();
			login(HASH_A);
			warmUp();
			stat(Skill.HERBLORE, 5_000);
			xp.handleGameStateChanged(gs);
			xp.handleGameStateChanged(GameState.LOGGED_IN);
			warmUp();
			stat(Skill.HERBLORE, 9_000);  // would be +4000 if snapshots survived — must be snapshot-only
			assertTrue("no grant after " + gs, received.isEmpty());
		}
	}

	@Test
	public void negativeDeltaNeverGrantsAndReSnapshots()
	{
		login(HASH_A);
		stat(Skill.PRAYER, 50_000);
		warmUp();
		stat(Skill.PRAYER, 40_000);    // negative: re-snapshot, no grant, no clawback
		assertTrue(received.isEmpty());
		assertEquals(0, eggs.getEggBalance());

		stat(Skill.PRAYER, 40_500);    // trusted from the re-snapshot
		assertEquals(1, received.size());
		assertEquals(500, received.get(0)[1]);
	}

	@Test
	public void zeroDeltaGrantsNothing()
	{
		login(HASH_A);
		stat(Skill.COOKING, 1_000);
		warmUp();
		stat(Skill.COOKING, 1_000);
		assertTrue(received.isEmpty());
	}

	@Test
	public void implausibleSpikeReSnapshotsAndGrantsNothing()
	{
		login(HASH_A);
		stat(Skill.SLAYER, 100_000);
		warmUp();
		stat(Skill.SLAYER, 100_000 + XpDeltaService.MAX_PLAUSIBLE_EVENT_XP + 1); // > 5M: dropped
		assertTrue(received.isEmpty());
		assertEquals(0, eggs.getEggBalance());

		stat(Skill.SLAYER, 100_000 + XpDeltaService.MAX_PLAUSIBLE_EVENT_XP + 101);
		assertEquals(1, received.size());
		assertEquals(100, received.get(0)[1]);
	}

	@Test
	public void plausibleLargeGrantStillFlows()
	{
		login(HASH_A);
		stat(Skill.RUNECRAFT, 0);
		warmUp();
		stat(Skill.RUNECRAFT, XpDeltaService.MAX_PLAUSIBLE_EVENT_XP); // exactly at ceiling: allowed
		assertEquals(1, received.size());
		assertEquals(XpDeltaService.MAX_PLAUSIBLE_EVENT_XP, received.get(0)[1]);
	}

	@Test
	public void accountHashMinusOneIsIgnoredEntirely()
	{
		accountHash = AccountContext.NO_ACCOUNT;
		xp.handleGameStateChanged(GameState.LOGGING_IN);
		xp.handleGameStateChanged(GameState.LOGGED_IN);
		warmUp();
		stat(Skill.ATTACK, 1_000);
		stat(Skill.ATTACK, 2_000);
		assertTrue(received.isEmpty());
		assertFalse(store.hasState()); // no account was ever bound
	}

	// -- mid-session enable: collection must load without waiting for an XP tick --

	@Test
	public void ensureAccountBoundLoadsStateWhenLoggedInMidSession()
	{
		// plugin enabled while already logged in: no login events, no XP tick yet
		accountHash = HASH_A;
		assertFalse(store.hasState());
		xp.ensureAccountBound();
		assertTrue("state must load immediately on mid-session enable", store.hasState());
		assertEquals(HASH_A, store.getAccountHash());
	}

	@Test
	public void ensureAccountBoundNoOpsWhenLoggedOut()
	{
		accountHash = AccountContext.NO_ACCOUNT;
		xp.ensureAccountBound();
		assertFalse(store.hasState());
	}

	@Test
	public void ensureAccountBoundKeepsLoginBurstSnapshotSafe()
	{
		// binding early must NOT defeat the login-dump guard: it arms sentinels+grace
		accountHash = HASH_A;
		xp.ensureAccountBound();
		loginBurst(13_034_431);   // a maxed account's lifetime XP streams in
		warmUp();
		assertTrue("early bind must keep the login burst snapshot-only", received.isEmpty());
		assertEquals(0, eggs.getEggBalance());

		// genuine post-warmup gain still flows normally
		stat(Skill.ATTACK, 13_034_431 + 30_000);
		assertEquals(1, received.size());
		assertEquals(30_000, received.get(0)[1]);
	}

	// -- prompt in-session accrual (timing/sync bug regression tests) -----

	@Test
	public void rapidSameTickDeltasCreditEggsImmediately()
	{
		login(HASH_A);
		stat(Skill.WOODCUTTING, 100_000); // first sighting: snapshot only
		warmUp();

		// a rapid burst of real deltas within the SAME tick — no lull, no extra
		// ticks, no debounce: each event must credit as it arrives
		int xp = 100_000;
		for (int i = 1; i <= 5; i++)
		{
			xp += 25_000;
			stat(Skill.WOODCUTTING, xp);
			assertEquals("delta " + i + " must be delivered immediately", i, received.size());
			assertEquals(25_000, received.get(i - 1)[1]);
			// banked/credited state reflects THIS event already (50k per egg today)
			assertEquals((25_000L * i) / 50_000, eggs.getEggBalance());
			assertEquals((25_000L * i) % 50_000, eggs.getBankedXp());
		}
		assertEquals(2, eggs.getEggBalance());   // 125k = 2 eggs + 25k banked
		assertEquals(25_000L, eggs.getBankedXp());
	}

	@Test
	public void midSessionLoggedInAfterRegionLoadDoesNotSwallowOngoingGains()
	{
		login(HASH_A);
		stat(Skill.AGILITY, 200_000);
		warmUp();
		stat(Skill.AGILITY, 200_100);
		assertEquals(1, received.size());

		// Region crossing / teleport: RuneLite fires LOGGED_IN again after
		// LOADING with NO login-ish state in between. The settle window must not
		// re-arm — the very next real delta (same tick!) still credits.
		xp.handleGameStateChanged(GameState.LOGGED_IN);
		assertTrue("region-load LOGGED_IN must not restart grace", xp.isWarmedUp());
		stat(Skill.AGILITY, 200_250);
		assertEquals(2, received.size());
		assertEquals(150, received.get(1)[1]);

		// but a REAL reconnect (reset state first) still re-arms everything
		xp.handleGameStateChanged(GameState.HOPPING);
		xp.handleGameStateChanged(GameState.LOGGED_IN);
		stat(Skill.AGILITY, 200_400); // first post-hop reading: snapshot only
		warmUp();
		stat(Skill.AGILITY, 200_400);
		assertEquals("post-hop first reading must grant nothing", 2, received.size());
	}

	@Test
	public void accountSwitchSwapsStoreBeforeAttributionAndDropsSnapshots()
	{
		login(HASH_A);
		loginBurst(1_000_000);
		warmUp();
		stat(Skill.ATTACK, 1_050_000); // A earns 50k → the first egg of the day
		assertEquals(1, eggs.getEggBalance());
		assertEquals(HASH_A, store.getAccountHash());

		// switch account under us mid-session (no GameStateChanged seen)
		accountHash = HASH_B;
		stat(Skill.ATTACK, 90_000_000); // B's XP appears: MUST be snapshot-only, on B's file
		assertEquals(HASH_B, store.getAccountHash());
		assertEquals(0, eggs.getEggBalance());          // B starts clean
		assertEquals(1, received.size());               // only A's legitimate delta ever fired

		// B needs a fresh grace window too
		warmUp();
		stat(Skill.ATTACK, 90_000_500);
		assertEquals(2, received.size());
		assertEquals(500, received.get(1)[1]);
	}
}

package com.runie.core;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/** OSRS XP table anchors + levelForXp binary search (architecture Appendix A, §12.1). */
public class XpTableTest
{
	@Test
	public void canonicalAnchors()
	{
		assertEquals(0, XpTable.xpForLevel(1));
		assertEquals(83, XpTable.xpForLevel(2));
		assertEquals(6_517_253, XpTable.xpForLevel(92));       // half of 99
		assertEquals(13_034_431, XpTable.xpForLevel(99));
		assertEquals(104_273_167, XpTable.xpForLevel(120));
	}

	@Test
	public void levelForXpBoundaries()
	{
		assertEquals(1, XpTable.levelForXp(0, 99));
		assertEquals(1, XpTable.levelForXp(82, 99));
		assertEquals(2, XpTable.levelForXp(83, 99));
		assertEquals(98, XpTable.levelForXp(13_034_430, 99));
		assertEquals(99, XpTable.levelForXp(13_034_431, 99));
	}

	@Test
	public void capsAt99AndAt120ByPrestigeFlag()
	{
		// un-prestiged cap
		assertEquals(99, XpTable.levelForXp(200_000_000L, 99));
		// prestiged cap
		assertEquals(119, XpTable.levelForXp(104_273_166L, 120));
		assertEquals(120, XpTable.levelForXp(104_273_167L, 120));
		assertEquals(120, XpTable.levelForXp(2_000_000_000L, 120));
	}

	@Test
	public void tableIsStrictlyIncreasing()
	{
		for (int level = 2; level <= XpTable.MAX_VIRTUAL_LEVEL; level++)
		{
			if (XpTable.xpForLevel(level) <= XpTable.xpForLevel(level - 1))
			{
				throw new AssertionError("table not increasing at level " + level);
			}
		}
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsNegativeXp()
	{
		XpTable.levelForXp(-1, 99);
	}
}

package com.runie.core;

