	}

	private List<Path> corruptFiles() throws IOException
	{
		List<Path> out = new ArrayList<>();
		try (DirectoryStream<Path> s = Files.newDirectoryStream(dir, "*.corrupt-*"))
		{
			s.forEach(out::add);
		}
		return out;
	}

