		assertEquals(0, store.getState().eggs.balance);
		assertFalse(store.isWritesDisabled());
	}

	private int corruptFilesQuietly()
	{
		try
		{
			return corruptFiles().size();
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

