package com.runie.overlay;

import com.runie.RunieConfig;
import com.runie.anim.AnimationService;
import com.runie.core.AuraState;
import com.runie.core.EggService;
import com.runie.core.ProgressionService;
import com.runie.core.RunieClock;
import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The on-screen companion (architecture §7.1).
 *
 * <p><b>Click-through safe by construction</b>: this overlay installs NO mouse
 * listeners and adds no interactive menu entries — game-world clicks under the
 * sprite pass through untouched. RuneLite's built-in alt-drag (overlay edit
 * mode) is the only interaction, and OverlayManager persists the position.
 *
 * <p>Render path is arithmetic + {@code drawImage} only (§13): the idle frames
 * are pre-decoded by {@link AnimationService} and played back as a ping-pong
 * loop (the art IS the animation — no procedural warps); fonts/strokes are
 * cached; the egg toast polls two ints. The shiny shimmer and the one-shot
 * evolution burst are composited layers (ShinyRenderer / AuraRenderer) — no
 * per-creature art, zero steady-state allocation.
 */
@Singleton
public class RunieCompanionOverlay extends Overlay
{
	private static final long TOAST_DURATION_MS = 4000;
	private static final Color CHIP_BG = new Color(0, 0, 0, 140);
	private static final Color TOAST_BG = new Color(20, 60, 20, 190);
	private static final Color TOAST_FG = new Color(170, 255, 170);
	private static final Font CHIP_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);

	private final AnimationService animationService;
	private final AuraRenderer auraRenderer;
	private final ShinyRenderer shinyRenderer;
	private final ProgressionService progressionService;
	private final CreatureRegistry registry;
	private final EggService eggService;
	private final RunieConfig config;
	private final RunieClock clock;

	// egg toast state (poll-based: no listener seam needed on EggService)
	private int lastEggs = -1;
	private int toastAmount;
	private long toastUntilMs;

	// one-shot evolution burst (rework part 2): ms-anchored, self-expiring
	private volatile long burstStartMs = Long.MIN_VALUE;
	private volatile boolean burstGolden;

	@Inject
	public RunieCompanionOverlay(AnimationService animationService, AuraRenderer auraRenderer,
		ShinyRenderer shinyRenderer, ProgressionService progressionService, CreatureRegistry registry,
		EggService eggService, RunieConfig config, RunieClock clock)
	{
		this.animationService = animationService;
		this.auraRenderer = auraRenderer;
		this.shinyRenderer = shinyRenderer;
		this.progressionService = progressionService;
		this.registry = registry;
		this.eggService = eggService;
		this.config = config;
		this.clock = clock;
		setPosition(OverlayPosition.BOTTOM_RIGHT); // default; user drags freely
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
		setMovable(true);
		setResettable(true);
	}

	/**
	 * Trigger the one-shot evolution burst (stage crossings; {@code golden} for
	 * the p3→L120 mastery milestone). Safe from any thread — the render path
	 * reads the volatile anchor.
	 */
	public void playEvolutionBurst(boolean golden)
	{
		burstGolden = golden;
		burstStartMs = clock.elapsedMs();
	}

	/** True while an evolution burst is still playing (test seam). */
	public boolean isBurstActive()
	{
		return burstStartMs != Long.MIN_VALUE;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showCompanion())
		{
			return null;
		}
		long now = clock.elapsedMs();
		BufferedImage frame = animationService.currentCompanionFrame(now);
		AnimationService.CompanionClips clips = animationService.getActiveClips();
		if (frame == null || clips == null)
		{
			return null;
		}

		int chipH = config.showNameplate() ? 16 : 0;
		int toastH = 20;
		int fw = frame.getWidth();
		int fh = frame.getHeight();
		// reserve margin around the sprite so the composited aura layers
		// (golden glow extends ~0.35× beyond the sprite box) never clip
		int auraPadX = (int) Math.ceil(Math.max(fw, fh) * 0.35) + 4;
		int headroom = (int) Math.ceil(fh * 0.30);
		int w = Math.max(fw + 2 * auraPadX, 90);
		int h = toastH + headroom + fh + chipH;
		int baselineY = toastH + headroom + fh; // the ground line the feet stand on
		int spriteX = (w - fw) / 2;
		int spriteY = baselineY - fh;

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// glow layer UNDER the sprite (GOLDEN mastery radiance; no-op otherwise)
		auraRenderer.renderUnder(g, clips.aura, spriteX, spriteY, fw, fh, now, config);

		// the pre-rendered idle frame — ping-pong playback picked the frame
		g.drawImage(frame, spriteX, spriteY, null);

		// shiny shimmer (rework part 4): runtime hue-shift + glints, no new art
		boolean shiny = progressionService.getCreature(clips.creatureId)
			.map(c -> c.shiny).orElse(false);
		if (shiny)
		{
			shinyRenderer.renderShimmer(g, frame, spriteX, spriteY, now, config);
		}

		// ring/sparkle layer OVER the sprite (PRESTIGE ring / GOLDEN sparkles)
		auraRenderer.renderOver(g, clips.aura, spriteX, spriteY, fw, fh, now, config);

		// one-shot evolution burst (self-expires after its ms window)
		if (burstStartMs != Long.MIN_VALUE)
		{
			long total = burstGolden ? AuraRenderer.GOLDEN_BURST_MS : AuraRenderer.EVOLUTION_BURST_MS;
			double progress = (now - burstStartMs) / (double) total;
			if (progress >= 1.0)
			{
				burstStartMs = Long.MIN_VALUE;
			}
			else
			{
				auraRenderer.renderEvolutionBurst(g, spriteX, spriteY, fw, fh, progress, burstGolden, config);
			}
		}

		// nameplate chip (§7.1)
		if (config.showNameplate())
		{
			CreatureDefinition def = registry.byId(clips.creatureId);
			String name = def != null ? def.getName() : clips.creatureId;
			if (shiny)
			{
				name = "\u2726 " + name; // ✦ shiny tag
			}
			int level = progressionService.levelOf(clips.creatureId);
			String label = name + "  Lv " + level;
			g.setFont(CHIP_FONT);
			int cy = baselineY + 2;
			FontMetrics fm = g.getFontMetrics();
			int tw = fm.stringWidth(label);
			int cx = (w - tw) / 2;
			g.setColor(CHIP_BG);
			g.fillRoundRect(cx - 5, cy, tw + 10, 14, 8, 8);
			g.setColor(clips.aura == AuraState.GOLDEN ? new Color(255, 214, 84) : Color.WHITE);
			g.drawString(label, cx, cy + 11);
		}

		// egg-earned toast: poll the balance; a rise queues a 4s chip
		int eggBalance = eggService.getEggBalance();
		if (lastEggs >= 0 && eggBalance > lastEggs)
		{
			toastAmount = eggBalance - lastEggs;
			toastUntilMs = now + TOAST_DURATION_MS;
		}
		lastEggs = eggBalance;
		if (now < toastUntilMs && toastAmount > 0)
		{
			String toast = "+" + toastAmount + " Egg" + (toastAmount > 1 ? "s" : "");
			g.setFont(CHIP_FONT);
			FontMetrics fm = g.getFontMetrics();
			int tw = fm.stringWidth(toast);
			int tx = (w - tw) / 2;
			Composite old = g.getComposite();
			float fade = Math.min(1f, (toastUntilMs - now) / 600f);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, fade));
			g.setColor(TOAST_BG);
			g.fillRoundRect(tx - 6, 0, tw + 12, 16, 8, 8);
			g.setColor(TOAST_FG);
			g.drawString(toast, tx, 12);
			g.setComposite(old);
		}

		return new Dimension(w, h); // bounds = alt-drag handle size
	}
}

package com.runie.overlay;

import com.runie.RunieConfig;
import com.runie.assets.AnimationClip;
import com.runie.assets.AssetLoader;
import com.runie.core.GachaService;
import com.runie.core.ProgressionService;
import com.runie.core.PullResult;
import com.runie.core.RunieClock;
import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import com.runie.creatures.Rarity;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.concurrent.Executor;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Hatch → reveal cinematic (architecture §7.2). Registered always; renders only
 * while a presentation is active. Display-only: no listeners, cannot eat
 * clicks; dismissed by timeout or {@link #skip()} from the panel.
 *
 * <p>Phases (normal motion): a real hatching egg — the same bundled egg sprite
 * used on the Hatch button wobbles, cracks, and bursts open (0–1.5s) → creature
 * reveal card with name, rarity, NEW!/duplicate star gain + shiny tag (1.5–4.8s).
 * Reduced motion: a simple 0.8s fade-in card shown for 2.5s.
 *
 * <p><b>In-danger deferral (§7.3)</b>: while the danger supplier reports true,
 * the presentation clock is re-anchored each frame — the pull RESULT is already
 * committed and saved by GachaService; only the presentation waits, so the
 * cinematic never obscures combat.
 */
@Slf4j
@Singleton
public class RuniePullOverlay extends Overlay implements GachaService.PullListener
{
	static final long HATCH_MS = 1500;
	static final long REVEAL_MS = 3300;
	static final long REDUCED_FADE_MS = 800;
	static final long REDUCED_HOLD_MS = 2500;
	private static final int CARD_W = 280;
	private static final int CARD_H = 210;
	private static final int EGG_H = 120; // rendered height of the hatching egg sprite
	private static final Font TITLE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 16);
	private static final Font BODY_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
	private static final Font BADGE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);

	/** Rarity glow colors, C..GM. */
	private static final Color[] RARITY_COLORS = {
		new Color(157, 157, 157), new Color(30, 200, 60), new Color(0, 112, 221),
		new Color(163, 53, 238), new Color(255, 128, 0), new Color(230, 204, 128),
	};

	public static Color rarityColor(Rarity rarity)
	{
		return RARITY_COLORS[rarity.tierIndex()];
	}

	private static final class Presentation
	{
		final PullResult result;
		final BufferedImage art; // pre-decoded before presentation starts
		long startMs;
		boolean started;
		boolean skipped;

		Presentation(PullResult result, BufferedImage art)
		{
			this.result = result;
			this.art = art;
		}
	}

	private final CreatureRegistry registry;
	private final ProgressionService progressionService;
	private final AssetLoader assetLoader;
	private final com.runie.assets.ArtStyleService artStyleService;
	private final RunieConfig config;
	private final RunieClock clock;
	private final Executor executor;

	/** Danger sensor, injected by the plugin (reads client state on demand). */
	private volatile BooleanSupplier dangerSupplier = () -> false;

	private volatile Presentation presentation;
	/** Cached scaled egg sprite for the hatch cinematic (same source as the Hatch button). */
	private BufferedImage eggSprite;

	@Inject
	public RuniePullOverlay(CreatureRegistry registry, ProgressionService progressionService,
		AssetLoader assetLoader, com.runie.assets.ArtStyleService artStyleService, RunieConfig config,
		RunieClock clock, java.util.concurrent.ScheduledExecutorService executor)
	{
		this(registry, progressionService, assetLoader, artStyleService, config, clock, (Executor) executor);
	}

	/** Test / mockup seam: direct executor makes presentation prep synchronous. */
	public RuniePullOverlay(CreatureRegistry registry, ProgressionService progressionService,
		AssetLoader assetLoader, com.runie.assets.ArtStyleService artStyleService, RunieConfig config,
		RunieClock clock, Executor executor)
	{
		this.registry = registry;
		this.progressionService = progressionService;
		this.assetLoader = assetLoader;
		this.artStyleService = artStyleService;
		this.config = config;
		this.clock = clock;
		this.executor = executor;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	public void setDangerSupplier(BooleanSupplier dangerSupplier)
	{
		this.dangerSupplier = dangerSupplier != null ? dangerSupplier : () -> false;
	}

	/** True while a reveal is being presented (panel shows its Skip button). */
	public boolean isPresenting()
	{
		return presentation != null;
	}

	/** Skip the cinematic: jump straight to (or dismiss) the reveal card. */
	public void skip()
	{
		Presentation p = presentation;
		if (p == null)
		{
			return;
		}
		if (!p.skipped && !config.reducedMotion())
		{
			p.skipped = true;
			p.startMs = clock.elapsedMs() - HATCH_MS; // jump past the hatch into the reveal phase
		}
		else
		{
			presentation = null; // second skip (or reduced motion): dismiss
		}
	}

	/** GachaService callback (client thread) — decode reveal art off-thread. */
	@Override
	public void onPull(PullResult result)
	{
		executor.execute(() ->
		{
			try
			{
				int stage = Math.max(1, progressionService.currentStageOf(result.creatureId));
				AnimationClip clip = assetLoader.getIdleClip(result.creatureId, artStyleService.effectiveStyle(), stage, 128);
				presentation = new Presentation(result, clip != null ? clip.firstFrame() : null);
			}
			catch (Exception e)
			{
				log.warn("Runie: pull reveal prep failed", e);
			}
		});
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Presentation p = presentation;
		if (p == null)
		{
			return null;
		}
		long now = clock.elapsedMs();
		if (dangerSupplier.getAsBoolean())
		{
			// defer/suppress presentation while in danger (§7.3) — the pull
			// result is already committed & saved; only the cinematic waits
			p.startMs = now;
			p.started = true;
			return null;
		}
		if (!p.started)
		{
			p.startMs = now;
			p.started = true;
		}
		long t = now - p.startMs;
		boolean reduced = config.reducedMotion();
		long total = reduced ? REDUCED_FADE_MS + REDUCED_HOLD_MS : HATCH_MS + REVEAL_MS;
		if (t >= total)
		{
			presentation = null;
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		Color rc = rarityColor(p.result.rarity);

		if (!reduced && t < HATCH_MS)
		{
			renderHatch(g, t, rc);
		}
		else
		{
			long rt = reduced ? t : t - HATCH_MS;
			float alpha = reduced
				? Math.min(1f, rt / (float) REDUCED_FADE_MS)
				: Math.min(1f, rt / 250f);
			renderRevealCard(g, p, rc, alpha);
		}
		return new Dimension(CARD_W, CARD_H);
	}

	// ------------------------------------------------------------------

	/**
	 * The hatching-egg cinematic: the same bundled egg sprite used on the Hatch
	 * button pops in, rocks with growing intensity while cracks spread across its
	 * shell, then bursts open in a rarity-colored flash of flying shell shards —
	 * handing off to the creature reveal card. Purely presentational.
	 */
	private void renderHatch(Graphics2D g, long t, Color rc)
	{
		g.setColor(new Color(12, 12, 16, 200));
		g.fillRoundRect(0, 0, CARD_W, CARD_H, 16, 16);

		BufferedImage egg = eggSprite();
		int ew = egg.getWidth();
		int eh = egg.getHeight();
		int cx = CARD_W / 2;
		int baseY = 150; // the egg rests its base here; art column matches the reveal card
		double p = t / (double) HATCH_MS;
		boolean burst = p >= 0.72;

		// soft, pulsing rarity glow behind the egg
		float pulse = (float) (0.5 + 0.5 * Math.sin(t / 120.0));
		g.setColor(new Color(rc.getRed(), rc.getGreen(), rc.getBlue(), (int) (36 + 40 * pulse)));
		g.fillOval(cx - 72, baseY - eh - 6, 144, 144);

		if (!burst)
		{
			double scale = p < 0.12 ? 0.7 + 0.3 * (p / 0.12) : 1.0; // pop-in
			double wobAmp = Math.toRadians(3 + 15 * clamp01((p - 0.10) / 0.6)); // rocking grows
			double angle = Math.sin(t / 70.0) * wobAmp;
			int sw = (int) (ew * scale);
			int sh = (int) (eh * scale);
			int ox = cx - sw / 2;
			int oy = baseY - sh;

			Graphics2D gg = (Graphics2D) g.create();
			gg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			gg.rotate(angle, cx, baseY); // pivot on the base so it rocks like a real egg
			gg.drawImage(egg, ox, oy, sw, sh, null);
			drawCracks(gg, ox, oy, sw, sh, p);
			gg.dispose();

			drawHatchLabel(g, "Hatching...");
		}
		else
		{
			double bp = clamp01((p - 0.72) / 0.28);
			int fr = (int) (24 + 130 * bp);
			int fcx = cx;
			int fcy = baseY - eh / 2;
			g.setColor(new Color(255, 255, 255, (int) (150 * (1 - bp))));
			g.fillOval(fcx - fr / 2, fcy - fr / 2, fr, fr);
			g.setColor(new Color(rc.getRed(), rc.getGreen(), rc.getBlue(), (int) (210 * (1 - bp))));
			g.setStroke(new BasicStroke(3f));
			g.drawOval(fcx - fr / 2, fcy - fr / 2, fr, fr);

			// shell splits: top cap lifts and tips away, base settles; both fade
			float eggAlpha = (float) Math.max(0, 1 - bp * 1.15);
			int topH = (int) (eh * 0.46);
			BufferedImage top = egg.getSubimage(0, 0, ew, topH);
			BufferedImage bot = egg.getSubimage(0, topH, ew, eh - topH);
			drawPiece(g, top, cx, baseY - eh - (int) (bp * 44), Math.toRadians(-20 * bp), eggAlpha);
			drawPiece(g, bot, cx, baseY - eh + topH + (int) (bp * 10), Math.toRadians(9 * bp), eggAlpha);

			drawShards(g, cx, fcy, bp);
			drawHatchLabel(g, "Hatched!");
		}
	}

	/** Progressive shell cracks in egg-local space (drawn inside the egg's rotated context). */
	private void drawCracks(Graphics2D g, int ox, int oy, int w, int h, double p)
	{
		g.setStroke(new BasicStroke(2f));
		// each crack: normalized zig-zag points + the progress at which it starts
		drawCrack(g, ox, oy, w, h, p, 0.30,
			new double[]{0.50, 0.44, 0.55, 0.46, 0.40}, new double[]{0.16, 0.28, 0.38, 0.50, 0.60});
		drawCrack(g, ox, oy, w, h, p, 0.48,
			new double[]{0.50, 0.58, 0.52, 0.66}, new double[]{0.20, 0.33, 0.46, 0.56});
		drawCrack(g, ox, oy, w, h, p, 0.60,
			new double[]{0.30, 0.42, 0.50, 0.60, 0.72}, new double[]{0.46, 0.42, 0.48, 0.43, 0.47});
	}

	private void drawCrack(Graphics2D g, int ox, int oy, int w, int h, double p, double start,
		double[] nx, double[] ny)
	{
		if (p < start)
		{
			return;
		}
		double reveal = clamp01((p - start) / 0.14); // grows to full length
		int segs = nx.length - 1;
		double shown = reveal * segs;
		int prevX = ox + (int) (nx[0] * w);
		int prevY = oy + (int) (ny[0] * h);
		for (int i = 1; i < nx.length; i++)
		{
			double frac = Math.min(1.0, shown - (i - 1));
			if (frac <= 0)
			{
				break;
			}
			int tx = ox + (int) ((nx[i - 1] + (nx[i] - nx[i - 1]) * frac) * w);
			int ty = oy + (int) ((ny[i - 1] + (ny[i] - ny[i - 1]) * frac) * h);
			g.setColor(new Color(60, 44, 30, 230)); // dark fissure
			g.drawLine(prevX, prevY, tx, ty);
			g.setColor(new Color(255, 250, 235, 150)); // thin highlight
			g.drawLine(prevX, prevY - 1, tx, ty - 1);
			prevX = tx;
			prevY = ty;
		}
	}

	/** Draw a shell piece centered horizontally at cx with its top at topY, rotated about its own centre. */
	private void drawPiece(Graphics2D g, BufferedImage img, int cx, int topY, double angle, float alpha)
	{
		if (alpha <= 0f)
		{
			return;
		}
		Graphics2D gg = (Graphics2D) g.create();
		gg.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, Math.min(1f, alpha)));
		gg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		int w = img.getWidth();
		int h = img.getHeight();
		gg.rotate(angle, cx, topY + h / 2.0);
		gg.drawImage(img, cx - w / 2, topY, null);
		gg.dispose();
	}

	private void drawShards(Graphics2D g, int cx, int cy, double bp)
	{
		int alpha = (int) (220 * (1 - bp));
		if (alpha <= 0)
		{
			return;
		}
		int n = 7;
		int dist = (int) (bp * 96);
		g.setColor(new Color(238, 226, 196, alpha));
		for (int i = 0; i < n; i++)
		{
			double ang = i * (2 * Math.PI / n) + 0.35;
			int sx = cx + (int) (Math.cos(ang) * dist);
			int sy = cy + (int) (Math.sin(ang) * dist) - (int) (bp * 12); // slight upward bias
			int s = Math.max(2, 6 - (int) (3 * bp));
			g.fillPolygon(new int[]{sx, sx + s, sx - s / 2}, new int[]{sy - s, sy + s, sy + s}, 3);
		}
	}

	private void drawHatchLabel(Graphics2D g, String s)
	{
		g.setFont(BODY_FONT);
		g.setColor(new Color(230, 230, 230, 220));
		FontMetrics fm = g.getFontMetrics();
		g.drawString(s, (CARD_W - fm.stringWidth(s)) / 2, CARD_H - 14);
	}

	private static double clamp01(double v)
	{
		return v < 0 ? 0 : (v > 1 ? 1 : v);
	}

	/** Lazily scaled copy of the shared Hatch-button egg sprite, reused for the hatch cinematic. */
	private BufferedImage eggSprite()
	{
		BufferedImage e = eggSprite;
		if (e == null)
		{
			e = com.runie.ui.EggIcon.scaled(EGG_H);
			eggSprite = e;
		}
		return e;
	}

	private void renderRevealCard(Graphics2D g, Presentation p, Color rc, float alpha)
	{
		int a = (int) (alpha * 255);
		g.setColor(new Color(12, 12, 16, Math.min(210, a)));
		g.fillRoundRect(0, 0, CARD_W, CARD_H, 16, 16);
		g.setColor(new Color(rc.getRed(), rc.getGreen(), rc.getBlue(), a));
		g.setStroke(new BasicStroke(3f));
		g.drawRoundRect(1, 1, CARD_W - 3, CARD_H - 3, 16, 16);

		CreatureDefinition def = registry.byId(p.result.creatureId);
		String name = def != null ? def.getName() : p.result.creatureId;

		// creature art, centered; rarity glow disc behind it
		int cx = CARD_W / 2;
		g.setColor(new Color(rc.getRed(), rc.getGreen(), rc.getBlue(), (int) (alpha * 60)));
		g.fillOval(cx - 58, 26, 116, 116);
		if (p.art != null)
		{
			int aw = p.art.getWidth();
			int ah = p.art.getHeight();
			java.awt.Composite old = g.getComposite();
			g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, alpha));
			g.drawImage(p.art, cx - aw / 2, 84 - ah / 2 + 10, null);
			g.setComposite(old);
		}

		g.setFont(TITLE_FONT);
		g.setColor(new Color(255, 255, 255, a));
		FontMetrics fm = g.getFontMetrics();
		g.drawString(name, cx - fm.stringWidth(name) / 2, 158);

		g.setFont(BADGE_FONT);
		fm = g.getFontMetrics();
		String rarity = p.result.rarity.getDisplayName().toUpperCase();
		g.setColor(new Color(rc.getRed(), rc.getGreen(), rc.getBlue(), a));
		g.drawString(rarity, cx - fm.stringWidth(rarity) / 2, 175);

		String badge;
		Color badgeColor;
		if (p.result.isNew)
		{
			badge = "NEW!";
			badgeColor = new Color(120, 255, 120, a);
		}
		else
		{
			com.runie.core.StarTier tier = com.runie.core.StarTier.tierFor(p.result.starsAfter);
			badge = "Duplicate  +1 \u2605  (" + p.result.starsAfter
				+ (tier != null ? " - " + tier.getDisplayName() : "") + ")";
			Color tc = tier != null ? tier.getColor() : new Color(200, 200, 255);
			badgeColor = new Color(tc.getRed(), tc.getGreen(), tc.getBlue(), a);
		}
		g.setColor(badgeColor);
		g.drawString(badge, cx - fm.stringWidth(badge) / 2, 190);
		if (p.result.becameShiny)
		{
			String shiny = "\u2726 SHINY! \u2726";
			g.setColor(new Color(160, 235, 255, a));
			g.drawString(shiny, cx - fm.stringWidth(shiny) / 2, 204);
		}
	}
}

package com.runie.overlay;

import com.runie.RunieConfig;
import com.runie.config.AnimationIntensity;
import com.runie.core.AuraState;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.MultipleGradientPaint;
import java.awt.RadialGradientPaint;
import java.awt.Stroke;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Reusable composited aura effects (architecture Appendix B decision: auras are
 * COMPOSITED over the base creature look, never baked per-creature). Any of the
 * 42 lines gets the same PRESTIGE ring / GOLDEN radiance the moment its
 * {@link AuraState} says so — no art dependency.
 *
 * <p>Render-thread rules (§13): the golden glow is pre-rendered ONCE (in the
 * constructor, at plugin startup) into a single canonical raster and blitted
 * scaled per frame; everything else is pure arithmetic + a handful of oval
 * draws. Zero decode, zero image allocation in {@code render()}.
 *
 * <p>All motion is ms-driven off the caller-supplied {@code nowMs}
 * ({@link com.runie.core.RunieClock#elapsedMs()}), and reduced-motion /
 * intensity gating (§6.4) is applied here so every caller composites auras
 * consistently: reduced motion = a static ring + static glow, no shimmer, no
 * orbiting sparkles.
 */
@Singleton
public class AuraRenderer
{
	/** Which visual effect an {@link AuraState} maps to. */
	public enum Effect
	{
		/** No aura layer. */
		NONE,
		/** Faint warm ring (prestiged, below the level-120 cap). */
		PRESTIGE_RING,
		/** Radiant golden glow + ring + sparkles (prestiged AND level 120). */
		GOLDEN_RADIANCE
	}

	/** Shimmer period for the golden glow pulse (ms-driven, §6.2). */
	static final long SHIMMER_PERIOD_MS = 2400;
	/** Orbit period for the golden sparkles (ms). */
	static final long ORBIT_PERIOD_MS = 5200;
	/** Canonical pre-rendered glow raster edge (blitted scaled). */
	static final int GLOW_RASTER_PX = 384;

	private static final Color GOLD = new Color(255, 214, 84);
	private static final Color GOLD_CORE = new Color(255, 232, 150);
	private static final Color PRESTIGE_RING_COLOR = new Color(235, 220, 160);
	private static final BasicStroke RING_STROKE = new BasicStroke(3f);
	private static final BasicStroke GOLD_RING_STROKE = new BasicStroke(3.5f);

	private final BufferedImage glowRaster;

	@Inject
	public AuraRenderer()
	{
		// one-time pre-render at construction (plugin startup, NOT render())
		this.glowRaster = renderGlowRaster(GLOW_RASTER_PX);
	}

	/** Pure aura-state → effect mapping (unit-tested; the overlay just obeys). */
	public static Effect effectFor(AuraState aura)
	{
		if (aura == null)
		{
			return Effect.NONE;
		}
		switch (aura)
		{
			case PRESTIGE:
				return Effect.PRESTIGE_RING;
			case GOLDEN:
				return Effect.GOLDEN_RADIANCE;
			case NONE:
			default:
				return Effect.NONE;
		}
	}

	/**
	 * Golden glow alpha for {@code nowMs} — constant under reduced motion
	 * (static glow, §6.4), otherwise a gentle sine pulse whose amplitude scales
	 * with {@link AnimationIntensity}.
	 */
	static float glowAlpha(long nowMs, boolean reducedMotion, AnimationIntensity intensity)
	{
		final float base = 0.55f;
		if (reducedMotion)
		{
			return base;
		}
		float amp;
		switch (intensity)
		{
			case FULL:
				amp = 0.25f;
				break;
			case SUBTLE:
				amp = 0.10f;
				break;
			case NORMAL:
			default:
				amp = 0.20f;
		}
		double phase = 2 * Math.PI * (nowMs % SHIMMER_PERIOD_MS) / (double) SHIMMER_PERIOD_MS;
		float a = base + amp * (float) Math.sin(phase);
		return Math.max(0f, Math.min(1f, a));
	}

	/** Ring alpha (shared by prestige + golden rings); static under reduced motion. */
	static float ringAlpha(long nowMs, boolean reducedMotion, AnimationIntensity intensity, float base)
	{
		if (reducedMotion)
		{
			return base;
		}
		float amp = intensity == AnimationIntensity.SUBTLE ? 0.06f : 0.14f;
		// quarter-period offset from the glow so ring and glow breathe out of step
		double phase = 2 * Math.PI * ((nowMs + SHIMMER_PERIOD_MS / 4) % SHIMMER_PERIOD_MS)
			/ (double) SHIMMER_PERIOD_MS;
		float a = base + amp * (float) Math.sin(phase);
		return Math.max(0f, Math.min(1f, a));
	}

	/**
	 * Orbiting sparkle count — 0 under reduced motion (static ring only, §6.4)
	 * and under SUBTLE intensity; 5 at NORMAL, 7 at FULL.
	 */
	static int sparkleCount(boolean reducedMotion, AnimationIntensity intensity)
	{
		if (reducedMotion || intensity == AnimationIntensity.SUBTLE)
		{
			return 0;
		}
		return intensity == AnimationIntensity.FULL ? 7 : 5;
	}

	/** The cached canonical glow raster (test seam: must be built once, reused). */
	BufferedImage getGlowRaster()
	{
		return glowRaster;
	}

	/**
	 * Layer drawn UNDER the sprite (the golden radiance halo). Coordinates are
	 * the UNSCALED sprite box so the aura stays stable while the sprite bobs /
	 * squashes.
	 */
	public void renderUnder(Graphics2D g, AuraState aura, int spriteX, int spriteY,
		int spriteW, int spriteH, long nowMs, RunieConfig config)
	{
		if (effectFor(aura) != Effect.GOLDEN_RADIANCE)
		{
			return;
		}
		boolean rm = config.reducedMotion();
		int d = (int) (Math.max(spriteW, spriteH) * 1.7);
		int gx = spriteX + (spriteW - d) / 2;
		int gy = spriteY + (spriteH - d) / 2 + spriteH / 10; // sit slightly low: grounded halo
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
			glowAlpha(nowMs, rm, config.animationIntensity())));
		g.drawImage(glowRaster, gx, gy, d, d, null); // scale-blit of the pre-rendered raster
		g.setComposite(old);
	}

	/**
	 * Layer drawn OVER the sprite: PRESTIGE = faint warm ring; GOLDEN = bright
	 * golden ring + orbiting sparkles (sparkles gated by reduced-motion /
	 * intensity). Pure arithmetic + oval draws — render-thread safe.
	 */
	public void renderOver(Graphics2D g, AuraState aura, int spriteX, int spriteY,
		int spriteW, int spriteH, long nowMs, RunieConfig config)
	{
		Effect effect = effectFor(aura);
		if (effect == Effect.NONE)
		{
			return;
		}
		boolean rm = config.reducedMotion();
		AnimationIntensity intensity = config.animationIntensity();
		Stroke oldStroke = g.getStroke();

		int d = Math.min(spriteW, spriteH) + (effect == Effect.GOLDEN_RADIANCE ? 12 : 8);
		int cx = spriteX + spriteW / 2;
		int cy = spriteY + spriteH / 2 + spriteH / 12;

		if (effect == Effect.PRESTIGE_RING)
		{
			float a = ringAlpha(nowMs, rm, intensity, 0.36f);
			g.setColor(withAlpha(PRESTIGE_RING_COLOR, a));
			g.setStroke(RING_STROKE);
			g.drawOval(cx - d / 2, cy - d / 2, d, d);
			g.setStroke(oldStroke);
			return;
		}

		// GOLDEN_RADIANCE ring
		float a = ringAlpha(nowMs, rm, intensity, 0.66f);
		g.setColor(withAlpha(GOLD, a));
		g.setStroke(GOLD_RING_STROKE);
		g.drawOval(cx - d / 2, cy - d / 2, d, d);
		g.setStroke(oldStroke);

		// orbiting sparkles on a flattened ellipse around the sprite
		int n = sparkleCount(rm, intensity);
		if (n > 0)
		{
			double orbit = 2 * Math.PI * (nowMs % ORBIT_PERIOD_MS) / (double) ORBIT_PERIOD_MS;
			double rx = d / 2.0 + 4;
			double ry = rx * 0.42;
			for (int k = 0; k < n; k++)
			{
				double ang = orbit + k * 2 * Math.PI / n;
				int px = cx + (int) Math.round(rx * Math.cos(ang));
				int py = cy + (int) Math.round(ry * Math.sin(ang));
				int s = (k % 2 == 0) ? 3 : 2;
				// sparkles behind the sprite's top half read as "passing behind";
				// keep it simple: draw all, tiny enough not to occlude
				g.setColor(withAlpha(GOLD_CORE, 0.55f + 0.35f * (float) Math.max(0, Math.sin(ang))));
				g.fillOval(px - s / 2, py - s / 2, s, s);
			}
		}
	}

	// ------------------------------------------------------------------
	// Evolution burst (rework part 2): one-shot flash + sparkle over the sprite
	// ------------------------------------------------------------------

	/** One-shot evolution burst length (ms-driven, §6.2). */
	public static final long EVOLUTION_BURST_MS = 1_000;
	/** Grander golden burst (p3 → L120 mastery milestone). */
	public static final long GOLDEN_BURST_MS = 1_400;

	private static final Color EVO_FLASH = new Color(210, 240, 255);
	private static final Color EVO_SPARK = new Color(255, 255, 255);

	/**
	 * One-shot evolution burst over the sprite box. {@code progress} is 0..1
	 * through the burst; callers clamp/stop past 1. Normal motion: an expanding
	 * flash ring + radial sparkles; the GOLDEN variant reuses the pre-rendered
	 * radiance raster for a grander bloom. Reduced motion (§6.4): a single
	 * static glow that fades out — no ring expansion, no sparkles. Pure
	 * arithmetic + blits; zero allocation.
	 */
	public void renderEvolutionBurst(Graphics2D g, int spriteX, int spriteY,
		int spriteW, int spriteH, double progress, boolean golden, RunieConfig config)
	{
		if (progress < 0 || progress >= 1)
		{
			return;
		}
		int cx = spriteX + spriteW / 2;
		int cy = spriteY + spriteH / 2;
		Color base = golden ? GOLD : EVO_FLASH;
		float fade = (float) (1.0 - progress);
		Composite oldComposite = g.getComposite();
		Stroke oldStroke = g.getStroke();

		// bloom: the cached radiance raster, scaled up through the burst
		int d = (int) (Math.max(spriteW, spriteH) * (golden ? 1.2 + 1.3 * progress : 0.9 + 0.9 * progress));
		float bloomAlpha = (golden ? 0.85f : 0.6f) * fade;
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1f, bloomAlpha)));
		g.drawImage(glowRaster, cx - d / 2, cy - d / 2, d, d, null);
		g.setComposite(oldComposite);

		if (config.reducedMotion())
		{
			return; // static fading glow only — no ring, no particles (§6.4)
		}

		// expanding flash ring
		int r = (int) (Math.min(spriteW, spriteH) * (0.35 + 0.85 * progress));
		g.setColor(withAlpha(base, 0.8f * fade));
		g.setStroke(golden ? GOLD_RING_STROKE : RING_STROKE);
		g.drawOval(cx - r, cy - r, 2 * r, 2 * r);
		g.setStroke(oldStroke);

		// radial sparkles flying outward (deterministic angles; golden = more)
		int n = golden ? 12 : 8;
		double reach = r + 6 + 10 * progress;
		for (int k = 0; k < n; k++)
		{
			double ang = k * 2 * Math.PI / n + (golden ? 0.26 : 0.4);
			int px = cx + (int) Math.round(reach * Math.cos(ang));
			int py = cy + (int) Math.round(reach * 0.8 * Math.sin(ang));
			int s = (k % 3 == 0) ? 4 : 3;
			g.setColor(withAlpha(k % 2 == 0 ? EVO_SPARK : base, 0.9f * fade));
			g.fillOval(px - s / 2, py - s / 2, s, s);
		}
	}

	// ------------------------------------------------------------------

	private static Color withAlpha(Color c, float alpha)
	{
		int a = Math.max(0, Math.min(255, Math.round(alpha * 255)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}

	/** One-time radial golden glow raster (soft core → transparent edge). */
	private static BufferedImage renderGlowRaster(int px)
	{
		BufferedImage img = new BufferedImage(px, px, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		float r = px / 2f;
		RadialGradientPaint paint = new RadialGradientPaint(
			new Point2D.Float(r, r), r,
			new float[]{0f, 0.35f, 0.7f, 1f},
			new Color[]{
				new Color(255, 236, 160, 200),
				new Color(255, 214, 84, 140),
				new Color(255, 196, 40, 55),
				new Color(255, 196, 40, 0)
			},
			MultipleGradientPaint.CycleMethod.NO_CYCLE);
		g.setPaint(paint);
		g.fillOval(0, 0, px, px);
		g.dispose();
		return img;
	}
}

package com.runie.overlay;

import com.runie.RunieConfig;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Runtime Shiny effect (rework part 4) — NO per-creature shiny art files.
 *
 * <p>The effect is a composited iridescent hue-shift over the creature's
 * already-decoded frames plus a light sparkle overlay:
 * <ul>
 *   <li>Per source frame, {@link #HUE_STEPS} tinted silhouettes are built ONCE
 *       (the frame's alpha, filled with a rotating spectrum hue via SrcIn) and
 *       cached in a small identity-keyed LRU. Rendering then only blits the
 *       silhouette for the current time step at low alpha over the sprite —
 *       zero per-frame decode/allocation in steady state (§13).</li>
 *   <li>Reduced motion (§6.4): a single fixed-hue tint, no sparkle motion.</li>
 * </ul>
 *
 * <p>{@link #applyStaticShiny} produces a one-off tinted copy for Swing
 * thumbnails (collection tile / detail card) — a static diagonal iridescent
 * wash inside the sprite's alpha. Callers cache the result.
 */
@Singleton
public class ShinyRenderer
{
	/** Hue steps in the animated shimmer cycle. */
	static final int HUE_STEPS = 8;
	/** Ms per hue step (full cycle = HUE_STEPS * this). */
	static final long HUE_STEP_MS = 260;
	/** Overlay strength of the hue tint over the sprite. */
	static final float TINT_ALPHA = 0.32f;
	/** Sparkle orbit period (ms). */
	static final long SPARKLE_PERIOD_MS = 3_400;
	/** Cache cap: frames from at most a few clips stay resident. */
	static final int CACHE_MAX_FRAMES = 64;

	/** Identity-keyed LRU of per-frame tinted silhouettes. */
	private final Map<BufferedImage, BufferedImage[]> tintCache =
		new LinkedHashMap<BufferedImage, BufferedImage[]>(32, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<BufferedImage, BufferedImage[]> eldest)
			{
				return size() > CACHE_MAX_FRAMES;
			}
		};

	@Inject
	public ShinyRenderer()
	{
	}

	/**
	 * Composite the animated shiny shimmer over an already-drawn sprite frame.
	 * Call AFTER {@code g.drawImage(frame, x, y, null)}.
	 */
	public synchronized void renderShimmer(Graphics2D g, BufferedImage frame, int x, int y,
		long nowMs, RunieConfig config)
	{
		if (frame == null)
		{
			return;
		}
		boolean rm = config.reducedMotion();
		BufferedImage[] tints = tintCache.computeIfAbsent(frame, ShinyRenderer::buildTints);
		int idx = rm ? 0 : (int) ((nowMs / HUE_STEP_MS) % HUE_STEPS);
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, rm ? 0.22f : TINT_ALPHA));
		g.drawImage(tints[idx], x, y, null);
		g.setComposite(old);

		if (rm)
		{
			return; // static tint only — no sparkle motion (§6.4)
		}
		// two small orbiting glints over the sprite's upper half
		int w = frame.getWidth();
		int h = frame.getHeight();
		double phase = 2 * Math.PI * (nowMs % SPARKLE_PERIOD_MS) / (double) SPARKLE_PERIOD_MS;
		for (int k = 0; k < 2; k++)
		{
			double ang = phase + k * Math.PI;
			int px = x + w / 2 + (int) Math.round(w * 0.32 * Math.cos(ang));
			int py = y + h / 3 + (int) Math.round(h * 0.18 * Math.sin(2 * ang));
			float a = 0.45f + 0.4f * (float) Math.max(0, Math.sin(ang + k));
			g.setColor(new Color(1f, 1f, 1f, Math.min(1f, a)));
			g.fillOval(px - 1, py - 1, 3, 3);
			g.drawLine(px - 3, py, px + 3, py);
			g.drawLine(px, py - 3, px, py + 3);
		}
	}

	/**
	 * Static shiny variant for Swing thumbnails: a NEW image with a diagonal
	 * iridescent wash confined to the sprite's alpha. Callers cache the result.
	 */
	public static BufferedImage applyStaticShiny(BufferedImage src)
	{
		if (src == null)
		{
			return null;
		}
		int w = src.getWidth();
		int h = src.getHeight();
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(src, 0, 0, null);
		// iridescent wash clipped to the sprite alpha
		BufferedImage wash = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D wg = wash.createGraphics();
		wg.drawImage(src, 0, 0, null);
		wg.setComposite(AlphaComposite.SrcIn.derive(0.30f));
		wg.setPaint(new GradientPaint(0, 0, new Color(120, 220, 255), w, h, new Color(255, 140, 235)));
		wg.fillRect(0, 0, w, h);
		wg.dispose();
		g.drawImage(wash, 0, 0, null);
		g.dispose();
		return out;
	}

	/** Test/inspection seam. */
	synchronized int cachedFrameCount()
	{
		return tintCache.size();
	}

	/** Silhouette of {@code frame}'s alpha, filled with each spectrum hue. */
	private static BufferedImage[] buildTints(BufferedImage frame)
	{
		BufferedImage[] out = new BufferedImage[HUE_STEPS];
		for (int i = 0; i < HUE_STEPS; i++)
		{
			BufferedImage img = new BufferedImage(frame.getWidth(), frame.getHeight(), BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = img.createGraphics();
			g.drawImage(frame, 0, 0, null);
			g.setComposite(AlphaComposite.SrcIn);
			g.setColor(Color.getHSBColor(i / (float) HUE_STEPS, 0.55f, 1f));
			g.fillRect(0, 0, img.getWidth(), img.getHeight());
			g.dispose();
			out[i] = img;
		}
		return out;
	}
}

package com.runie.anim;

import com.runie.RunieConfig;
import com.runie.assets.AnimationClip;
import com.runie.assets.ArtStyle;
import com.runie.assets.AssetLoader;
import com.runie.config.AnimationIntensity;
import com.runie.core.AuraState;
import com.runie.core.ProgressionService;
import com.runie.core.RunieClock;
import java.awt.image.BufferedImage;
import java.util.Optional;
import java.util.concurrent.Executor;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Millisecond-driven companion animation (architecture §6). The current frame
 * is a pure function of {@link RunieClock#elapsedMs()} — repaint-driven, no
 * timer thread, correct at any client framerate.
 *
 * <p><b>Idle = pre-rendered frames, played ping-pong.</b> Each creature /
 * style / stage ships its idle as a real PNG sequence
 * ({@code idle/frame_000..frame_0NN}); {@link AssetLoader} discovers and
 * decodes the full sequence and this service plays it back and forth
 * (0,1,…,N-1,N-2,…,1) at {@link AssetLoader#IDLE_FPS} via
 * {@link IdleFramePlayer}. Variants that currently bundle only
 * {@code frame_000} render as a static sprite — when their loops drop into the
 * resource folder later they animate with no code change. A small
 * deterministic per-creature phase offset ({@link IdleFramePlayer#phaseOffsetMs})
 * keeps different companions from playing in perfect sync.
 *
 * <p>The earlier procedural mesh-deformation rig (band mesh, breathing warp,
 * behavior clips) was rejected and removed — no warps are applied to the
 * sprite; the art IS the animation.
 *
 * <p>Decode policy (§6.3): {@link #refresh()} snapshots the active creature /
 * stage / style / aura on the calling thread, then pre-decodes the clip set on
 * the injected executor and swaps it in via a volatile reference. The render
 * path only ever reads {@link CompanionClips} — zero decode, zero I/O.
 *
 * <p><b>Golden aura (Appendix B):</b> the L120 golden look is COMPOSITED over
 * the base idle by {@link com.runie.overlay.AuraRenderer} — never baked. A
 * bundled {@code aura_gold/} variant (Grubnak) is retained only as a fallback
 * frame source when no idle art exists at all.
 *
 * <p>Settings (§6.4): reduced motion pins {@code frame_000} (fully static);
 * SUBTLE intensity halves the effective idle fps.
 */
@Slf4j
@Singleton
public class AnimationService
{
	/** Immutable, atomically-swapped clip set for the active companion. */
	public static final class CompanionClips
	{
		public final String creatureId;
		public final int stage;
		public final ArtStyle style;
		public final AuraState aura;
		public final AnimationClip idle;
		/**
		 * Baked golden variant (legacy Grubnak art) — OPTIONAL FALLBACK only:
		 * used as the frame source when no idle art exists. The golden look
		 * itself is composited by AuraRenderer (Appendix B).
		 */
		public final AnimationClip golden;

		CompanionClips(String creatureId, int stage, ArtStyle style, AuraState aura,
			AnimationClip idle, AnimationClip golden)
		{
			this.creatureId = creatureId;
			this.stage = stage;
			this.style = style;
			this.aura = aura;
			this.idle = idle;
			this.golden = golden;
		}

		/** The base frame source: idle art, else the baked-golden fallback. */
		AnimationClip baseClip()
		{
			return idle != null ? idle : golden;
		}
	}

	private final AssetLoader assetLoader;
	private final com.runie.assets.ArtStyleService artStyleService;
	private final ProgressionService progressionService;
	private final RunieConfig config;
	private final RunieClock clock;
	private final Executor executor;

	private volatile CompanionClips active;

	@Inject
	public AnimationService(AssetLoader assetLoader, com.runie.assets.ArtStyleService artStyleService,
		ProgressionService progressionService, RunieConfig config, RunieClock clock,
		java.util.concurrent.ScheduledExecutorService executor)
	{
		this(assetLoader, artStyleService, progressionService, config, clock, (Executor) executor);
	}

	/** Test seam: a direct executor + fake clock make refresh() synchronous. */
	public AnimationService(AssetLoader assetLoader, com.runie.assets.ArtStyleService artStyleService,
		ProgressionService progressionService, RunieConfig config, RunieClock clock, Executor executor)
	{
		this.assetLoader = assetLoader;
		this.artStyleService = artStyleService;
		this.progressionService = progressionService;
		this.config = config;
		this.clock = clock;
		this.executor = executor;
	}

	/**
	 * Re-resolve the active companion's clip set (active creature / stage /
	 * style / aura changed). Cheap snapshot here; decode + swap on the executor.
	 */
	public void refresh()
	{
		Optional<String> activeId = progressionService.getActiveCreatureId();
		if (!activeId.isPresent())
		{
			active = null;
			return;
		}
		String id = activeId.get();
		int stage = Math.max(1, progressionService.currentStageOf(id));
		AuraState aura = progressionService.auraOf(id);
		ArtStyle style = artStyleService.effectiveStyle(); // locked Kawaii resolves to Pixel
		int targetPx = config.companionScale().getPixels();

		executor.execute(() ->
		{
			try
			{
				AnimationClip idle = assetLoader.getIdleClip(id, style, stage, targetPx);
				// baked golden variant: FALLBACK frame source only (Appendix B —
				// the golden look is composited by AuraRenderer over any creature)
				AnimationClip golden = aura == AuraState.GOLDEN
					? assetLoader.getGoldenClip(id, style, stage, targetPx) : null;
				if (idle == null && golden == null)
				{
					active = null;
					return;
				}
				active = new CompanionClips(id, stage, style, aura, idle, golden);
			}
			catch (Exception e)
			{
				log.warn("Runie: companion clip refresh failed", e);
			}
		});
	}

	/** Drop everything (shutdown / style-pack invalidation). */
	public void reset()
	{
		active = null;
	}

	public CompanionClips getActiveClips()
	{
		return active;
	}

	/**
	 * The companion frame for {@code nowElapsedMs} — pure arithmetic + array
	 * lookup (render-thread safe). Null when no companion art is resident.
	 *
	 * <ul>
	 *   <li>Reduced motion pins {@code frame_000} — fully static (§6.4).</li>
	 *   <li>Otherwise the idle sequence plays as a seamless ping-pong loop at
	 *       {@link AssetLoader#IDLE_FPS}; SUBTLE intensity halves the effective
	 *       fps by halving elapsed time.</li>
	 *   <li>Single-frame sequences are inherently static (index is always 0).</li>
	 *   <li>A deterministic per-creature phase offset de-syncs companions.</li>
	 * </ul>
	 */
	public BufferedImage currentCompanionFrame(long nowElapsedMs)
	{
		CompanionClips c = active;
		if (c == null)
		{
			return null;
		}
		AnimationClip base = c.baseClip();
		if (base == null)
		{
			return null;
		}
		if (config.reducedMotion())
		{
			return base.firstFrame(); // hold frame_000, zero motion (§6.4)
		}
		long elapsed = nowElapsedMs + IdleFramePlayer.phaseOffsetMs(c.creatureId);
		if (config.animationIntensity() == AnimationIntensity.SUBTLE)
		{
			elapsed = elapsed / 2; // half-speed playback = half the effective fps
		}
		return base.frame(IdleFramePlayer.frameIndex(base.frameCount(), elapsed, base.getPerFrameMs()));
	}
}

package com.runie.anim;

/**
 * Pure ping-pong playback math for pre-rendered idle frame sequences
 * (architecture §6). The idle art is a real animation now — each creature /
 * style / stage ships {@code idle/frame_000..frame_0NN.png} — so the companion
 * simply plays those frames back and forth:
 *
 * <pre>0, 1, …, N-1, N-2, …, 1, 0, 1, …</pre>
 *
 * <p>Everything here is a pure function of elapsed MILLISECONDS — never client
 * ticks — so playback speed is independent of client framerate (§6.2), and the
 * render thread does arithmetic only. The frame rate is
 * {@link com.runie.assets.AssetLoader#IDLE_FPS} (via each clip's
 * {@code perFrameMs}); change that one constant to retime every idle.
 *
 * <p>Single-frame sequences (most of the roster until their loops are
 * generated) resolve to index 0 — a static sprite. When multi-frame art drops
 * into a creature's {@code idle/} folder later, it starts animating with no
 * code change.
 */
public final class IdleFramePlayer
{
	/**
	 * Window for the per-creature phase offset (ms). Offsets are spread across
	 * this window so different companions never play in lockstep; it comfortably
	 * exceeds any idle loop period (16 frames @ 12fps ping-pong ≈ 2.5s).
	 */
	static final int PHASE_WINDOW_MS = 10_000;

	private IdleFramePlayer()
	{
	}

	/**
	 * Ping-pong frame index for {@code elapsedMs} into a {@code frameCount}
	 * sequence at {@code perFrameMs} per frame.
	 *
	 * <p>The loop period is {@code 2 * (frameCount - 1)} steps, so the two end
	 * frames are held exactly one step each — no double-frame stutter at the
	 * turnarounds and no wrap-jump from the last frame back to the first.
	 * {@code frameCount <= 1} is always index 0 (static sprite).
	 */
	public static int frameIndex(int frameCount, long elapsedMs, int perFrameMs)
	{
		if (frameCount <= 1)
		{
			return 0;
		}
		if (elapsedMs < 0)
		{
			elapsedMs = 0;
		}
		long step = elapsedMs / perFrameMs;
		int period = 2 * (frameCount - 1);
		int p = (int) (step % period);
		return p < frameCount ? p : period - p;
	}

	/**
	 * Deterministic per-creature phase offset (ms), seeded from the creature id
	 * hash. Added to elapsed time before indexing so companions of different
	 * creatures aren't perfectly synced; the same creature always gets the same
	 * offset (stable across sessions and refreshes).
	 */
	public static long phaseOffsetMs(String creatureId)
	{
		if (creatureId == null)
		{
			return 0;
		}
		return Math.floorMod(creatureId.hashCode(), PHASE_WINDOW_MS);
	}
}

package com.runie.assets;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Resolves creature x stage x style x animation to cached, pre-decoded
 * {@link AnimationClip}s (architecture §5.1). Primary art is a single packed
 * sprite sheet ({@code <anim>.<n>.png}, n equal-width cells) sliced at load;
 * a legacy {@code frame_000..frame_N} sequence (probed until the first miss)
 * remains a supported fallback for single-frame art and test fixtures.
 *
 * <p><b>Never call from {@code render()}</b> — decode happens when
 * {@link com.runie.anim.AnimationService} refreshes (off the client thread) or
 * when the Swing panel builds thumbnails (EDT, once, then cached). The overlay
 * render path only ever touches already-decoded frames.
 *
 * <p>Fallback chain (§5.2): requested style → {@link ArtStyle#KAWAII} → null
 * (callers render a silhouette / skip). A missing frame set can never NPE the
 * render loop; it logs once per key.
 */
@Slf4j
@Singleton
public class AssetLoader
{
	static final String CREATURES_ROOT = "/com/runie/creatures/";
	static final int MAX_PROBE_FRAMES = 64;

	/**
	 * Standard idle framerate (architecture §6.1: idle 10–15fps). The single
	 * knob for companion idle playback speed — ping-pong playback derives its
	 * per-frame duration from this.
	 */
	public static final int IDLE_FPS = 12;

	private final Map<String, AnimationClip> clipCache = new ConcurrentHashMap<>();
	private final Map<String, BufferedImage> thumbCache = new ConcurrentHashMap<>();

	/**
	 * Root of the downloaded-art cache (RUNELITE_DIR/runie/assets), populated by
	 * {@link com.runie.core.RunieAssetService} on first launch. When set, it is
	 * the PRIMARY art source; the bundled classpath is only a fallback (kept tiny
	 * so the jar stays under the Plugin Hub 10 MB limit — the full animation art
	 * lives outside the jar and streams into this cache).
	 */
	private volatile Path assetCacheDir;

	/** Point the loader at the downloaded-art cache root (see RunieAssetService). */
	public void setAssetCacheDir(Path dir)
	{
		this.assetCacheDir = dir;
		invalidate(); // any clips decoded before the cache was ready must be re-resolved
	}

	/**
	 * Resource path for one frame — the single place the §5.1 convention lives.
	 * {@code /com/runie/creatures/<id>/art/<style>/stage<N>/<anim>/frame_###.png}
	 */
	static String framePath(String creatureId, ArtStyle style, int stage, String animation, int frame)
	{
		return String.format("%s%s/art/%s/stage%d/%s/frame_%03d.png",
			CREATURES_ROOT, creatureId, style.getFolderToken(), stage, animation, frame);
	}

	/**
	 * Resource path for a packed sprite <b>sheet</b>: a single horizontal strip of
	 * {@code frames} equal-width cells at
	 * {@code /com/runie/creatures/<id>/art/<style>/stage<N>/<anim>/<anim>.<frames>.png}.
	 * Sheets are the primary art form (one file per loop); the legacy
	 * {@code frame_###.png} sequence remains a supported fallback.
	 */
	static String sheetPath(String creatureId, ArtStyle style, int stage, String animation, int frames)
	{
		return String.format("%s%s/art/%s/stage%d/%s/%s.%d.png",
			CREATURES_ROOT, creatureId, style.getFolderToken(), stage, animation, animation, frames);
	}

	/**
	 * Load (or return cached) a clip, pre-scaled so its largest edge is
	 * {@code targetPx}. Applies the style fallback chain; returns null when no
	 * art exists in any style (caller silhouettes).
	 */
	public AnimationClip getClip(String creatureId, ArtStyle style, int stage, String animation,
		int fps, boolean loop, int targetPx)
	{
		String key = creatureId + '|' + style.getFolderToken() + '|' + stage + '|' + animation
			+ '|' + fps + '|' + targetPx;
		AnimationClip cached = clipCache.get(key);
		if (cached != null)
		{
			return cached;
		}
		AnimationClip clip = decodeClip(creatureId, style, stage, animation, fps, loop, targetPx);
		if (clip == null && style != ArtStyle.KAWAII)
		{
			clip = decodeClip(creatureId, ArtStyle.KAWAII, stage, animation, fps, loop, targetPx); // fallback
		}
		if (clip != null)
		{
			clipCache.put(key, clip);
		}
		else
		{
			log.debug("Runie: no art for {} (style={}, stage={}, anim={})", creatureId, style, stage, animation);
		}
		return clip;
	}

	/** Idle clip at the standard idle fps. */
	public AnimationClip getIdleClip(String creatureId, ArtStyle style, int stage, int targetPx)
	{
		return getClip(creatureId, style, stage, "idle", IDLE_FPS, true, targetPx);
	}

	/**
	 * Baked golden L120 variant (bundled under {@code aura_gold}) — retained as
	 * an OPTIONAL FALLBACK frame source only. The golden look itself is
	 * composited over the base idle by {@code AuraRenderer} (Appendix B), so it
	 * applies to any creature without per-creature baked art.
	 */
	public AnimationClip getGoldenClip(String creatureId, ArtStyle style, int stage, int targetPx)
	{
		return getClip(creatureId, style, stage, "aura_gold", IDLE_FPS, true, targetPx);
	}

	/**
	 * Collection-grid thumbnail: stage-appropriate idle frame 0, scaled to
	 * {@code px}, cached (§6.3). Null when the creature has no art at all.
	 */
	public BufferedImage getThumbnail(String creatureId, ArtStyle style, int stage, int px)
	{
		String key = creatureId + '|' + style.getFolderToken() + '|' + stage + '|' + px;
		BufferedImage cached = thumbCache.get(key);
		if (cached != null)
		{
			return cached;
		}
		AnimationClip clip = getIdleClip(creatureId, style, stage, px);
		if (clip == null)
		{
			return null;
		}
		BufferedImage thumb = clip.firstFrame();
		thumbCache.put(key, thumb);
		return thumb;
	}

	/** Drop all decoded frames (style-pack swap / shutdown). */
	public void invalidate()
	{
		clipCache.clear();
		thumbCache.clear();
	}

	// ------------------------------------------------------------------

	private AnimationClip decodeClip(String creatureId, ArtStyle style, int stage, String animation,
		int fps, boolean loop, int targetPx)
	{
		// Primary: a single packed sprite sheet <anim>.<n>.png (n equal-width cells).
		for (int n = 1; n <= MAX_PROBE_FRAMES; n++)
		{
			BufferedImage sheet = decode(sheetPath(creatureId, style, stage, animation, n));
			if (sheet != null)
			{
				AnimationClip clip = sliceSheet(sheet, n, fps, loop, targetPx);
				if (clip != null)
				{
					return clip;
				}
			}
		}
		// Fallback: legacy per-frame sequence frame_000..N, probed until first miss (§5.1).
		List<BufferedImage> frames = new ArrayList<>();
		for (int i = 0; i < MAX_PROBE_FRAMES; i++)
		{
			BufferedImage img = decode(framePath(creatureId, style, stage, animation, i));
			if (img == null)
			{
				break;
			}
			frames.add(scaleToFit(img, targetPx));
		}
		if (frames.isEmpty())
		{
			return null;
		}
		return new AnimationClip(frames.toArray(new BufferedImage[0]), fps, loop);
	}

	/** Slice a horizontal strip of {@code n} equal-width cells into pre-scaled frames. */
	private static AnimationClip sliceSheet(BufferedImage sheet, int n, int fps, boolean loop, int targetPx)
	{
		int fw = sheet.getWidth() / n;
		int fh = sheet.getHeight();
		if (fw < 1 || fh < 1)
		{
			return null;
		}
		BufferedImage[] frames = new BufferedImage[n];
		for (int i = 0; i < n; i++)
		{
			// detach each cell from the shared sheet raster into its own ARGB image
			BufferedImage cell = new BufferedImage(fw, fh, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = cell.createGraphics();
			g.drawImage(sheet.getSubimage(i * fw, 0, fw, fh), 0, 0, null);
			g.dispose();
			frames[i] = scaleToFit(cell, targetPx);
		}
		return new AnimationClip(frames, fps, loop);
	}

	private BufferedImage decode(String resourcePath)
	{
		// 1) downloaded-art cache (primary source once RunieAssetService has synced)
		Path dir = assetCacheDir;
		if (dir != null)
		{
			String rel = resourcePath.startsWith("/") ? resourcePath.substring(1) : resourcePath;
			Path f = dir.resolve(rel);
			if (Files.isRegularFile(f))
			{
				try (InputStream in = Files.newInputStream(f))
				{
					BufferedImage img = ImageIO.read(in);
					if (img != null)
					{
						return img;
					}
				}
				catch (IOException e)
				{
					log.warn("Runie: failed to read cached {}", f, e);
				}
			}
		}
		// 2) bundled classpath (kept minimal: test fixtures / any small bundled fallback)
		try (InputStream in = AssetLoader.class.getResourceAsStream(resourcePath))
		{
			if (in == null)
			{
				return null;
			}
			return ImageIO.read(in);
		}
		catch (IOException e)
		{
			log.warn("Runie: failed to decode {}", resourcePath, e);
			return null;
		}
	}

	/** Pre-scale at decode time so render() is a plain blit (§6.3, §13). */
	static BufferedImage scaleToFit(BufferedImage src, int targetPx)
	{
		int max = Math.max(src.getWidth(), src.getHeight());
		if (max <= targetPx)
		{
			return toArgb(src);
		}
		double s = targetPx / (double) max;
		int w = Math.max(1, (int) Math.round(src.getWidth() * s));
		int h = Math.max(1, (int) Math.round(src.getHeight() * s));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(src, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	private static BufferedImage toArgb(BufferedImage src)
	{
		if (src.getType() == BufferedImage.TYPE_INT_ARGB)
		{
			return src;
		}
		BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(src, 0, 0, null);
		g.dispose();
		return out;
	}
}

package com.runie.assets;

import com.runie.RunieConfig;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;

/**
 * THE single place the art-style rules live (easter-egg epic).
 *
 * <p>{@link ArtStyle#PIXEL} is the always-available default. {@link ArtStyle#KAWAII}
 * is a hidden easter-egg unlock: it stays LOCKED until the player says
 * {@code "uwu"} in public chat (case-insensitive, exact trimmed match — "uwuu"
 * does not count). Every art consumer (AnimationService, RuniePullOverlay, the
 * panel, the nav icon) resolves its style through {@link #effectiveStyle()}, so
 * selecting Kawaii while locked silently renders Pixel and nothing else in the
 * art pipeline needs to know about locks.
 *
 * <p><b>Persistence:</b> the unlock is a hidden, machine-global
 * {@link ConfigManager} key ({@code runie.kawaiiUnlocked} — no {@code @ConfigItem},
 * so it never appears in the config panel). It deliberately does NOT live in the
 * per-account JSON state: once earned, Kawaii stays unlocked across sessions and
 * account switches on this machine.
 *
 * <p><b>Threading:</b> {@link #handleChatMessage(ChatMessage)} runs on the client
 * thread (event handler) and is a couple of string compares in the common case;
 * the one-time ConfigManager write happens only at the unlock moment. The cached
 * flag is volatile so render/EDT readers see the unlock immediately.
 */
@Slf4j
@Singleton
public class ArtStyleService
{
	/** Hidden ConfigManager key (group {@link RunieConfig#GROUP}) — no @ConfigItem, never shown. */
	static final String UNLOCK_KEY = "kawaiiUnlocked";

	/** The visible art-style @ConfigItem key ({@link RunieConfig#artStyle()}). */
	static final String ART_STYLE_KEY = "artStyle";

	/** The magic word. Exact trimmed match, case-insensitive (§spec: no "uwuu" false positives). */
	static final String MAGIC_WORD = "uwu";

	/** One-time unlock celebration (game chat + RuneLite notification). */
	public static final String UNLOCK_MESSAGE =
		"(◕‿◕) Kawaii style unlocked — pick it in Runie ▸ Art style!";

	/** Subtle nudge shown if Kawaii is selected while still locked. */
	public static final String LOCKED_HINT =
		"Runie: that art style is still a secret... they say the cutest word in chat reveals it.";

	private final RunieConfig config;
	private final Supplier<String> unlockReader;
	private final Consumer<String> unlockWriter;
	/** Writes the visible artStyle config selection (enum name) — lock enforcement. */
	private final Consumer<String> styleWriter;

	/** Lazily-loaded cache of the persisted flag; volatile for render/EDT readers. */
	private volatile Boolean unlockedCache;

	@Inject
	public ArtStyleService(RunieConfig config, ConfigManager configManager)
	{
		this(config,
			() -> configManager.getConfiguration(RunieConfig.GROUP, UNLOCK_KEY),
			value -> configManager.setConfiguration(RunieConfig.GROUP, UNLOCK_KEY, value),
			styleName -> configManager.setConfiguration(RunieConfig.GROUP, ART_STYLE_KEY, styleName));
	}

	/** Test seam: the persisted flag behind plain reader/writer functions (no style writeback). */
	public ArtStyleService(RunieConfig config, Supplier<String> unlockReader, Consumer<String> unlockWriter)
	{
		this(config, unlockReader, unlockWriter, styleName -> { });
	}

	/** Test seam incl. the artStyle-selection writer used by {@link #enforceKawaiiLock()}. */
	public ArtStyleService(RunieConfig config, Supplier<String> unlockReader, Consumer<String> unlockWriter,
		Consumer<String> styleWriter)
	{
		this.config = config;
		this.unlockReader = unlockReader;
		this.unlockWriter = unlockWriter;
		this.styleWriter = styleWriter;
	}

	/** True once the Kawaii easter egg has been earned (persisted, machine-global). */
	public boolean isKawaiiUnlocked()
	{
		Boolean cached = unlockedCache;
		if (cached == null)
		{
			cached = Boolean.parseBoolean(unlockReader.get());
			unlockedCache = cached;
		}
		return cached;
	}

	/**
	 * The style every art consumer must render: the config selection, EXCEPT
	 * Kawaii-while-locked resolves to the always-available Pixel default.
	 */
	public ArtStyle effectiveStyle()
	{
		ArtStyle selected = config.artStyle();
		if (selected == ArtStyle.KAWAII && !isKawaiiUnlocked())
		{
			return ArtStyle.PIXEL;
		}
		return selected;
	}

	/**
	 * Kawaii is UNAVAILABLE until the easter egg is earned: if the stored
	 * artStyle selection is Kawaii while still locked (a locked pick in the
	 * settings dropdown, or a legacy selection from before the lock existed),
	 * snap the config selection back to the always-available Pixel default. The
	 * plugin calls this at startup (a locked player never keeps a Kawaii
	 * selection) and on every artStyle config change (picking Kawaii while
	 * locked immediately reverts in the settings UI). Once unlocked this is a
	 * permanent no-op.
	 *
	 * @return true when a locked Kawaii selection was reverted to Pixel (the
	 * plugin shows the {@link #LOCKED_HINT})
	 */
	public boolean enforceKawaiiLock()
	{
		if (config.artStyle() != ArtStyle.KAWAII || isKawaiiUnlocked())
		{
			return false;
		}
		styleWriter.accept(ArtStyle.PIXEL.name());
		log.debug("Runie: kawaii art style is locked — selection reverted to Pixel");
		return true;
	}

	/**
	 * Easter-egg detector, fed every {@link ChatMessage} by the plugin.
	 * Unlocks on a public/player chat line whose trimmed text is exactly
	 * {@code "uwu"} (case-insensitive).
	 *
	 * @return true only when THIS message caused a brand-new unlock (the plugin
	 * fires the one-time celebration); false for non-matches and for re-triggers
	 * once already unlocked (idempotent).
	 */
	public boolean handleChatMessage(ChatMessage event)
	{
		if (event == null || !isPlayerChat(event.getType()))
		{
			return false;
		}
		String text = event.getMessage();
		if (text == null || !text.trim().equalsIgnoreCase(MAGIC_WORD))
		{
			return false;
		}
		if (isKawaiiUnlocked())
		{
			return false; // idempotent: typing it again is a no-op
		}
		unlockWriter.accept("true");
		unlockedCache = true;
		log.debug("Runie: kawaii art style unlocked");
		return true;
	}

	/** Public/player chat lines only — system, private, friends/clan chat never trigger. */
	private static boolean isPlayerChat(ChatMessageType type)
	{
		return type == ChatMessageType.PUBLICCHAT || type == ChatMessageType.MODCHAT;
	}
}

package com.runie.assets;

import java.awt.image.BufferedImage;

/**
 * A pre-decoded, pre-scaled frame sequence (architecture §6.1). The frame index
 * is a pure function of elapsed milliseconds — never of client ticks — so
 * animation speed is independent of client framerate (§6.2).
 */
public final class AnimationClip
{
	private final BufferedImage[] frames;
	private final int perFrameMs;
	private final boolean loop;

	public AnimationClip(BufferedImage[] frames, int fps, boolean loop)
	{
		if (frames == null || frames.length == 0)
		{
			throw new IllegalArgumentException("clip needs at least one frame");
		}
		if (fps <= 0)
		{
			throw new IllegalArgumentException("fps must be positive: " + fps);
		}
		this.frames = frames;
		this.perFrameMs = 1000 / fps;
		this.loop = loop;
	}

	/** Frame index for {@code elapsedMs} since clip start (pure arithmetic). */
	public int frameIndexAt(long elapsedMs)
	{
		if (elapsedMs < 0)
		{
			elapsedMs = 0;
		}
		int i = (int) (elapsedMs / perFrameMs);
		return loop ? i % frames.length : Math.min(i, frames.length - 1);
	}

	public BufferedImage frameAt(long elapsedMs)
	{
		return frames[frameIndexAt(elapsedMs)];
	}

	/** Direct frame access by index (clamped) — used by ping-pong playback. */
	public BufferedImage frame(int index)
	{
		return frames[Math.max(0, Math.min(index, frames.length - 1))];
	}

	public boolean isFinished(long elapsedMs)
	{
		return !loop && elapsedMs >= (long) perFrameMs * frames.length;
	}

	public int frameCount()
	{
		return frames.length;
	}

	public int getPerFrameMs()
	{
		return perFrameMs;
	}

	public boolean isLoop()
	{
		return loop;
	}

	public BufferedImage firstFrame()
	{
		return frames[0];
	}

	public int getWidth()
	{
		return frames[0].getWidth();
	}

	public int getHeight()
	{
		return frames[0].getHeight();
	}
}

package com.runie.assets;

/**
 * Art style packs. N-ary by construction (architecture §5.3): adding a new pack
 * (e.g. {@code KAWAII_PIXEL("kawaii_pixel", "Kawaii-Pixel")}) requires only a new
 * enum constant plus the matching {@code art/<folderToken>/...} resource trees —
 * asset paths are derived from {@link #getFolderToken()}, the config dropdown
 * auto-lists new values, and state stores no style info (presentation-only).
 */
public enum ArtStyle
{
	KAWAII("kawaii", "Kawaii"),
	PIXEL("pixel", "Pixel");

	private final String folderToken;
	private final String displayName;

	ArtStyle(String folderToken, String displayName)
	{
		this.folderToken = folderToken;
		this.displayName = displayName;
	}

	/** Lowercase resource-folder token used in asset paths (architecture §5.1). */
	public String getFolderToken()
	{
		return folderToken;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

