/**
 * Hatch tab (architecture §8 tab 3): the Hatch Egg button (1 egg / starter,
 * danger confirm §7.3) with the egg balance and a progress bar toward the next
 * egg (banked XP / current tier cost), published odds table (the six base
 * percentages, verbatim), pity meters (Rare 10 / Elite 30 / GM 300 with the
 * soft-pity marker), and the recent-hatches list.
 */
class PullPanel extends JPanel
{
	private final UiContext ctx;
	private final JLabel starterBanner = new JLabel("", SwingConstants.CENTER);
	private final JButton pullButton = new JButton();
	private final JLabel eggBalanceLabel = new JLabel("", SwingConstants.CENTER);
	private final JProgressBar eggProgressBar = pityBar();
	private final JButton skipButton = new JButton("Skip reveal");
	private final JLabel lastResult = new JLabel(" ", SwingConstants.CENTER);
	private final JProgressBar rareBar = pityBar();
	private final JProgressBar eliteBar = pityBar();
	private final JProgressBar gmBar = pityBar();
	private final JPanel recentList = new JPanel();

	PullPanel(UiContext ctx)
	{
		this.ctx = ctx;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		starterBanner.setAlignmentX(CENTER_ALIGNMENT);
		starterBanner.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
		starterBanner.setForeground(ColorScheme.BRAND_ORANGE);
		add(starterBanner);
		add(gap(4));

		eggBalanceLabel.setAlignmentX(CENTER_ALIGNMENT);
		eggBalanceLabel.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
		eggBalanceLabel.setForeground(new Color(120, 220, 120));
		add(eggBalanceLabel);
		add(gap(3));

		pullButton.setAlignmentX(CENTER_ALIGNMENT);
		pullButton.setFocusable(false);
		pullButton.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
		pullButton.setIcon(new javax.swing.ImageIcon(EggIcon.scaled(16)));
		pullButton.addActionListener(e -> doPull());
		add(pullButton);
		add(gap(3));

		JLabel nextEgg = new JLabel("Next egg", SwingConstants.CENTER);
		nextEgg.setAlignmentX(CENTER_ALIGNMENT);
		nextEgg.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
		nextEgg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		add(nextEgg);
		eggProgressBar.setAlignmentX(CENTER_ALIGNMENT);
		add(eggProgressBar);
		add(gap(2));

		skipButton.setAlignmentX(CENTER_ALIGNMENT);
		skipButton.setFocusable(false);
		skipButton.setVisible(false);
		skipButton.addActionListener(e -> ctx.pullOverlay.skip());
		add(skipButton);

		lastResult.setAlignmentX(CENTER_ALIGNMENT);
		lastResult.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		lastResult.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		add(lastResult);
		add(gap(8));

		// published odds — the six base percentages, verbatim (§8)
		add(sectionLabel("Odds per Hatch"));
		for (Rarity r : Rarity.values())
		{
			JLabel row = new JLabel(String.format("%s  %.1f%%", r.getDisplayName(), r.baseOdds() * 100),
				SwingConstants.LEFT);
			row.setAlignmentX(CENTER_ALIGNMENT);
			row.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
			row.setForeground(RuniePullOverlay.rarityColor(r));
			add(row);
		}
		add(gap(8));

		add(sectionLabel("Pity"));
		add(pityRow("Rare+", rareBar));
		add(pityRow("Elite+", eliteBar));
		add(pityRow("GM (soft @150)", gmBar));
		add(gap(8));

		add(sectionLabel("Recent Hatches"));
		recentList.setLayout(new BoxLayout(recentList, BoxLayout.Y_AXIS));
		recentList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		recentList.setAlignmentX(CENTER_ALIGNMENT);
		add(recentList);

		refresh();
	}

	void refresh()
	{
		int starters = ctx.gachaService.getStarterPullsRemaining();
		starterBanner.setText(starters > 0 ? starters + " welcome Hatch" + (starters > 1 ? "es" : "") + "!" : "");
		starterBanner.setVisible(starters > 0);
		pullButton.setText(starters > 0
			? "Hatch Egg (free starter)"
			: "Hatch Egg  (" + Economy.HATCH_COST_EGGS + " Egg)");
		int eggs = ctx.eggService.getEggBalance();
		eggBalanceLabel.setText(eggs + (eggs == 1 ? " Egg" : " Eggs"));
		long banked = ctx.eggService.getBankedXp();
		long cost = ctx.eggService.getNextEggCostXp();
		eggProgressBar.setMaximum(1000);
		eggProgressBar.setValue((int) (1000L * banked / Math.max(1L, cost)));
		eggProgressBar.setString(String.format("%,d / %,d XP", banked, cost));
		eggProgressBar.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		pullButton.setEnabled(ctx.gachaService.canPull());
		skipButton.setVisible(ctx.pullOverlay.isPresenting());

		if (ctx.stateStore.hasState())
		{
			PullResult.PitySnapshot pity = ctx.gachaService.pitySnapshot();
			setPity(rareBar, pity.rarePity, Economy.RARE_PITY_N);
			setPity(eliteBar, pity.elitePity, Economy.ELITE_PITY_N);
			setPity(gmBar, pity.gmPity, Economy.GM_HARD_AT);

			recentList.removeAll();
			List<RunieAccountState.PullRecord> tail = ctx.stateStore.getState().gacha.pullHistoryTail;
			int shown = 0;
			for (int i = tail.size() - 1; i >= 0 && shown < 6; i--, shown++)
			{
				RunieAccountState.PullRecord rec = tail.get(i);
				CreatureDefinition def = ctx.registry.byId(rec.creatureId);
				Rarity rarity = Rarity.valueOf(rec.rarity);
				JLabel row = new JLabel("#" + rec.n + "  " + (def != null ? def.getName() : rec.creatureId)
					+ (rec.dup ? "  (dup)" : "  NEW"), SwingConstants.LEFT);
				row.setAlignmentX(CENTER_ALIGNMENT);
				row.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
				row.setForeground(RuniePullOverlay.rarityColor(rarity));
				recentList.add(row);
			}
			if (!tail.isEmpty())
			{
				RunieAccountState.PullRecord last = tail.get(tail.size() - 1);
				CreatureDefinition def = ctx.registry.byId(last.creatureId);
				lastResult.setText("Last: " + (def != null ? def.getName() : last.creatureId)
					+ (last.dup ? " (duplicate)" : " - NEW!"));
			}
		}
		revalidate();
		repaint();
	}

	private void doPull()
	{
		if (!ctx.gachaService.canPull())
		{
			return;
		}
		// §7.3 in-combat / wilderness confirmation, initiated only from Swing
		if (ctx.dangerSupplier.getAsBoolean() && ctx.config.confirmDangerPulls())
		{
			int choice = JOptionPane.showConfirmDialog(this,
				"You look busy or in danger - Hatch anyway?", "Runie",
				JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (choice != JOptionPane.YES_OPTION)
			{
				return;
			}
		}
		pullButton.setEnabled(false);
		ctx.commandRunner.accept(() ->
		{
			try
			{
				ctx.gachaService.pull(); // listeners drive overlay + panel refresh
			}
			catch (IllegalStateException ex)
			{
				// balance raced away between the check and the command — refresh only
			}
			SwingUtilities.invokeLater(this::refresh);
		});
	}

	private static JProgressBar pityBar()
	{
		JProgressBar bar = new JProgressBar();
		bar.setStringPainted(true);
		bar.setMaximumSize(new Dimension(210, 15));
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		return bar;
	}

	private static void setPity(JProgressBar bar, int value, int max)
	{
		bar.setMaximum(max);
		bar.setValue(Math.min(value, max));
		bar.setString(value + " / " + max);
		bar.setForeground(value >= max * 3 / 4 ? ColorScheme.BRAND_ORANGE : ColorScheme.PROGRESS_COMPLETE_COLOR);
	}

	private JPanel pityRow(String label, JProgressBar bar)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(CENTER_ALIGNMENT);
		JLabel l = new JLabel(label);
		l.setAlignmentX(CENTER_ALIGNMENT);
		l.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		bar.setAlignmentX(CENTER_ALIGNMENT);
		row.add(l);
		row.add(bar);
		row.add(Box.createRigidArea(new Dimension(0, 3)));
		return row;
	}

	private JLabel sectionLabel(String text)
	{
		JLabel l = new JLabel(text, SwingConstants.CENTER);
		l.setAlignmentX(CENTER_ALIGNMENT);
		l.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
		l.setForeground(Color.WHITE);
		return l;
	}

	private java.awt.Component gap(int h)
	{
		return Box.createRigidArea(new Dimension(0, h));
	}
}

package com.runie.ui;

import com.runie.core.AuraState;
import com.runie.core.Economy;
import com.runie.core.PrestigeResult;
import com.runie.core.ProgressionService;
import com.runie.core.StarTier;
import com.runie.core.XpTable;
import com.runie.creatures.CreatureDefinition;
import com.runie.overlay.RuniePullOverlay;
import com.runie.overlay.ShinyRenderer;
import com.runie.state.CreatureInstance;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.util.Optional;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;

/**
 * Creature detail card (architecture §8): art (with runtime shiny tint), name
 * (+ ✦ shiny tag)/stage title, rarity, duplicate stars in their tier color,
 * level + XP bar to next level, evolution status, aura state (incl. golden at
 * 120), duplicate count, Set Active, and the confirm-gated Prestige button.
 */
class CreatureDetailPanel extends JPanel
{
	private static final int ART_PX = 128;

	private final UiContext ctx;
	private final Runnable onBack;
	private final Runnable onChanged;
	private String creatureId;
	/** Selected codex entry: 0 = auto (follow current stage), 1..3 = stage, 4 = golden (Lv 120). */
	private int codexSel;

	CreatureDetailPanel(UiContext ctx, Runnable onBack, Runnable onChanged)
	{
		this.ctx = ctx;
		this.onBack = onBack;
		this.onChanged = onChanged;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
	}

	void showCreature(String creatureId)
	{
		this.creatureId = creatureId;
		this.codexSel = 0; // reset to auto-follow the current stage each time a creature is opened
		rebuild();
	}

	void refresh()
	{
		if (creatureId != null)
		{
			rebuild();
		}
	}

	private void rebuild()
	{
		removeAll();
		CreatureDefinition def = ctx.registry.byId(creatureId);
		if (def == null)
		{
			revalidate();
			repaint();
			return;
		}
		Optional<CreatureInstance> instOpt = ctx.progressionService.getCreature(creatureId);
		boolean owned = instOpt.isPresent();
		Color rc = RuniePullOverlay.rarityColor(def.getRarity());

		JButton back = new JButton("< Collection");
		back.setFocusable(false);
		back.setAlignmentX(CENTER_ALIGNMENT);
		back.addActionListener(e -> onBack.run());
		add(back);
		add(gap(6));

		// art
		int stage = owned ? Math.max(1, ctx.progressionService.currentStageOf(creatureId)) : 1;
		AuraState aura = owned ? ctx.progressionService.auraOf(creatureId) : AuraState.NONE;
		BufferedImage art = null;
		if (aura == AuraState.GOLDEN)
		{
			com.runie.assets.AnimationClip golden =
				ctx.assetLoader.getGoldenClip(creatureId, ctx.artStyleService.effectiveStyle(), stage, ART_PX);
			if (golden != null)
			{
				art = golden.firstFrame();
			}
		}
		if (art == null)
		{
			art = ctx.assetLoader.getThumbnail(creatureId, ctx.artStyleService.effectiveStyle(), stage, ART_PX);
		}
		boolean shiny = owned && instOpt.get().shiny;
		if (shiny && art != null)
		{
			art = ShinyRenderer.applyStaticShiny(art); // runtime effect, no shiny art files
		}
		if (art != null)
		{
			JLabel pic = new JLabel(new ImageIcon(art));
			pic.setAlignmentX(CENTER_ALIGNMENT);
			pic.setBorder(BorderFactory.createLineBorder(rc, 2));
			add(pic);
			add(gap(6));
		}

		// name + stage title + rarity
		String title = shiny ? "\u2726 " + def.getName() : def.getName();
		String stageTitle = "";
		if (owned)
		{
			CreatureInstance inst = instOpt.get();
			stageTitle = inst.isPrestiged() && def.getPrestigeTitle() != null
				? def.getPrestigeTitle()
				: def.getStages().get(stage - 1).getTitle();
		}
		add(centeredLabel(title, 15, shiny ? new Color(160, 235, 255) : Color.WHITE, true));
		if (!stageTitle.isEmpty() && !stageTitle.equals(title))
		{
			add(centeredLabel(stageTitle, 11, ColorScheme.LIGHT_GRAY_COLOR, false));
		}
		add(centeredLabel(def.getRarity().getDisplayName().toUpperCase(), 11, rc, true));
		if (owned)
		{
			int starCount = instOpt.get().stars;
			StarTier starTier = StarTier.tierFor(starCount);
			if (starTier != null)
			{
				StringBuilder starsText = new StringBuilder();
				for (int i = 0; i < StarTier.starsInTier(starCount); i++)
				{
					starsText.append('\u2605');
				}
				starsText.append("  ").append(starTier.getDisplayName())
					.append(" (").append(starCount).append('/').append(Economy.MAX_STARS).append(')');
				add(centeredLabel(starsText.toString(), 11, starTier.getColor(), true));
			}
		}
		if (def.getArchetype() != null && !def.getArchetype().isEmpty())
		{
			add(centeredLabel(def.getArchetype() + " family", 10, ColorScheme.LIGHT_GRAY_COLOR, false));
		}
		add(gap(6));

		if (!owned)
		{
			add(centeredLabel("Not yet collected", 12, ColorScheme.LIGHT_GRAY_COLOR, false));
			revalidate();
			repaint();
			return;
		}

		CreatureInstance inst = instOpt.get();
		int cap = inst.isPrestiged() ? ProgressionService.PRESTIGE_LEVEL_CAP : ProgressionService.BASE_LEVEL_CAP;
		int level = ctx.progressionService.levelOf(creatureId);

		// level + XP bar to next level
		add(centeredLabel("Level " + level + " / " + cap, 13, Color.WHITE, true));
		JProgressBar xpBar = new JProgressBar(0, 1000);
		xpBar.setStringPainted(true);
		xpBar.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		xpBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		xpBar.setMaximumSize(new Dimension(200, 18));
		xpBar.setAlignmentX(CENTER_ALIGNMENT);
		if (level >= cap)
		{
			xpBar.setValue(1000);
			xpBar.setString("MAX");
		}
		else
		{
			long base = XpTable.xpForLevel(level);
			long next = XpTable.xpForLevel(level + 1);
			long into = inst.xp - base;
			long span = next - base;
			xpBar.setValue((int) (1000 * into / Math.max(1, span)));
			xpBar.setString(String.format("%,d / %,d XP", into, span));
		}
		add(xpBar);
		add(gap(6));

		// stage / evolution status
		String evo;
		if (stage < def.getStages().size() && !inst.isPrestiged())
		{
			evo = "Stage " + stage + "/3 - evolves at Lv " + def.getStages().get(stage).getMinLevel();
		}
		else
		{
			evo = "Stage 3/3 - fully evolved";
		}
		add(centeredLabel(evo, 11, ColorScheme.LIGHT_GRAY_COLOR, false));
		add(gap(8));

		// ---- Evolution Codex: per-stage lore, unlocked stages readable, future stages gated ----
		buildCodex(def, stage, aura == AuraState.GOLDEN);
		add(gap(8));

		// aura + prestige status
		String auraText;
		Color auraColor = ColorScheme.LIGHT_GRAY_COLOR;
		switch (aura)
		{
			case GOLDEN:
				auraText = "GOLDEN aura - fully mastered (Lv 120)";
				auraColor = new Color(255, 214, 84);
				break;
			case PRESTIGE:
				auraText = "Prestige aura (prestiged x" + inst.prestigeCount + ")";
				auraColor = new Color(235, 220, 160);
				break;
			default:
				auraText = inst.isPrestiged() ? "Prestiged" : "No aura";
		}
		add(centeredLabel(auraText, 11, auraColor, aura != AuraState.NONE));
		add(centeredLabel("Copies Hatched: " + inst.copiesPulled
			+ "   Lifetime XP: " + String.format("%,d", inst.lifetimeXp), 10,
			ColorScheme.LIGHT_GRAY_COLOR, false));
		add(gap(8));

		// actions
		boolean isActive = ctx.progressionService.getActiveCreatureId()
			.map(a -> a.equals(creatureId)).orElse(false);
		JButton activeBtn = new JButton(isActive ? "Active companion ★" : "Set active");
		activeBtn.setFocusable(false);
		activeBtn.setEnabled(!isActive);
		activeBtn.setAlignmentX(CENTER_ALIGNMENT);
		activeBtn.addActionListener(e -> ctx.commandRunner.accept(() ->
		{
			ctx.progressionService.setActiveCreature(creatureId);
			onChanged.run();
		}));
		add(activeBtn);
		add(gap(4));

		boolean eligible = !inst.isPrestiged() && level >= ProgressionService.BASE_LEVEL_CAP;
		JButton prestigeBtn = new JButton(inst.isPrestiged()
			? "Prestiged (cap 120)"
			: eligible ? "Prestige to 120..." : "Prestige at Lv 99");
		prestigeBtn.setFocusable(false);
		prestigeBtn.setEnabled(eligible);
		prestigeBtn.setAlignmentX(CENTER_ALIGNMENT);
		prestigeBtn.addActionListener(e -> confirmPrestige(def));
		add(prestigeBtn);

		revalidate();
		repaint();
	}

	/** Two-step typed confirm — prestige is IRREVERSIBLE (§8 tab 1). */
	private void confirmPrestige(CreatureDefinition def)
	{
		String typed = (String) JOptionPane.showInputDialog(this,
			"Prestige " + def.getName() + "?\n\nThis is IRREVERSIBLE: level resets to 1,\n"
				+ "the cap rises to 120, the stage-3 look is kept.\n\nType PRESTIGE to confirm:",
			"Prestige " + def.getName(), JOptionPane.WARNING_MESSAGE, null, null, "");
		if (!"PRESTIGE".equals(typed))
		{
			return;
		}
		ctx.commandRunner.accept(() ->
		{
			PrestigeResult r = ctx.progressionService.prestige(creatureId);
			if (r != PrestigeResult.SUCCESS)
			{
				javax.swing.SwingUtilities.invokeLater(() ->
					JOptionPane.showMessageDialog(this, "Prestige failed: " + r));
			}
			onChanged.run();
		});
	}

	/**
	 * Evolution codex: a selectable list of this line's lore entries — one per
	 * evolution stage plus the golden (Lv 120) mastery form. Entries the player
	 * has reached are readable; entries not yet unlocked are shown locked.
	 * Defaults to the current stage; the selection persists across refreshes
	 * until the creature is reopened.
	 */
	private void buildCodex(CreatureDefinition def, int maxStage, boolean goldenUnlocked)
	{
		int entries = def.getStages().size(); // 3
		int sel = codexSel == 0 ? maxStage : codexSel; // 0 => auto-follow current stage
		if (sel >= 1 && sel <= entries && sel > maxStage)
		{
			sel = maxStage;
		}
		if (sel == 4 && !goldenUnlocked)
		{
			sel = maxStage;
		}
		if (sel < 1)
		{
			sel = 1;
		}

		add(centeredLabel("EVOLUTION CODEX", 10, new Color(150, 160, 175), true));
		add(gap(4));

		// selector row: I / II / III / golden-star
		JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(CENTER_ALIGNMENT);
		row.setMaximumSize(new Dimension(240, 30));
		String[] roman = {"I", "II", "III"};
		for (int n = 1; n <= entries; n++)
		{
			row.add(codexTab(roman[n - 1], n == sel, n <= maxStage, n));
		}
		row.add(codexTab("✦", sel == 4, goldenUnlocked, 4));
		add(row);
		add(gap(4));

		// selected entry: title + wrapped lore
		String title;
		String desc;
		Color titleColor;
		if (sel == 4)
		{
			title = def.getPrestigeTitle();
			desc = def.getGoldenLore();
			titleColor = new Color(255, 214, 84);
		}
		else
		{
			CreatureDefinition.Stage s = def.getStages().get(sel - 1);
			title = s.getTitle();
			desc = s.getDescription();
			titleColor = Color.WHITE;
		}
		add(centeredLabel(title, 12, titleColor, true));
		add(gap(2));
		add(wrappedLabel(desc));

		// gentle hint about what remains locked
		if (maxStage < entries)
		{
			add(gap(3));
			int nextLvl = def.getStages().get(maxStage).getMinLevel();
			add(centeredLabel("Evolve to Lv " + nextLvl + " to unlock the next entry", 9,
				ColorScheme.LIGHT_GRAY_COLOR, false));
		}
		else if (!goldenUnlocked)
		{
			add(gap(3));
			add(centeredLabel("Reach the golden aura (Lv 120) to unlock the final entry", 9,
				ColorScheme.LIGHT_GRAY_COLOR, false));
		}
	}

	private JButton codexTab(String label, boolean selected, boolean unlocked, int target)
	{
		JButton b = new JButton(unlocked ? label : "🔒"); // lock glyph when not yet unlocked
		b.setFocusable(false);
		b.setMargin(new java.awt.Insets(2, 6, 2, 6));
		b.setFont(new Font(Font.SANS_SERIF, selected ? Font.BOLD : Font.PLAIN, 12));
		b.setEnabled(unlocked);
		b.setForeground(selected ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		if (selected)
		{
			b.setBorder(BorderFactory.createLineBorder(new Color(255, 214, 84), 1));
		}
		b.addActionListener(e ->
		{
			codexSel = target;
			rebuild();
		});
		return b;
	}

	/** Word-wrapped, centered lore paragraph sized to the plugin panel width. */
	private JLabel wrappedLabel(String text)
	{
		String safe = text == null ? "" : text
			.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		// Wrap width sits comfortably inside the usable area (PluginPanel 225px −
		// panel/tab/scroll insets − the as-needed vertical scrollbar) so the
		// paragraph never runs past the right edge.
		JLabel l = new JLabel("<html><div style='width:176px; text-align:center;'>" + safe + "</div></html>");
		l.setAlignmentX(CENTER_ALIGNMENT);
		l.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		l.setForeground(new Color(200, 205, 212));
		// Cap the max to the wrapped preferred size — otherwise BoxLayout stretches
		// the label into a tall block and the short paragraph floats with big gaps.
		l.setMaximumSize(l.getPreferredSize());
		return l;
	}

	private JLabel centeredLabel(String text, int size, Color color, boolean bold)
	{
		JLabel l = new JLabel(text, SwingConstants.CENTER);
		l.setAlignmentX(CENTER_ALIGNMENT);
		l.setFont(new Font(Font.SANS_SERIF, bold ? Font.BOLD : Font.PLAIN, size));
		l.setForeground(color);
		return l;
	}

	private java.awt.Component gap(int h)
	{
		return javax.swing.Box.createRigidArea(new Dimension(0, h));
	}
}

package com.runie.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;

/**
 * The egg glyph used across the UI (Hatch button etc.), backed by the bundled
 * sprite at classpath resource {@code com/runie/ui/egg.png} (~79x96,
 * transparent). The source image is loaded ONCE and cached; per-size scaled
 * copies (smooth, aspect-preserving) are derived on demand. If the resource is
 * missing or unreadable the old programmatically-painted glyph is used instead
 * — the icon path never throws.
 */
@Slf4j
public final class EggIcon
{
	/** Cached full-size sprite; null when the bundled resource failed to load. */
	private static final BufferedImage SOURCE = loadSource();

	private EggIcon()
	{
	}

	/**
	 * Egg glyph scaled to the given height in px (width follows the sprite's
	 * aspect ratio). Falls back to the painted glyph when the bundled sprite is
	 * unavailable.
	 */
	public static BufferedImage scaled(int heightPx)
	{
		if (SOURCE == null)
		{
			return paintedFallback(heightPx);
		}
		int h = Math.max(1, heightPx);
		int w = Math.max(1, (int) Math.round(h * (double) SOURCE.getWidth() / SOURCE.getHeight()));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.drawImage(SOURCE, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	private static BufferedImage loadSource()
	{
		try (InputStream in = EggIcon.class.getResourceAsStream("egg.png"))
		{
			if (in == null)
			{
				log.warn("Runie: bundled egg sprite missing (com/runie/ui/egg.png); using painted glyph");
				return null;
			}
			BufferedImage img = ImageIO.read(in);
			if (img == null)
			{
				log.warn("Runie: bundled egg sprite unreadable; using painted glyph");
			}
			return img;
		}
		catch (Exception ex)
		{
			log.warn("Runie: failed to load bundled egg sprite; using painted glyph", ex);
			return null;
		}
	}

	/** Legacy tiny painted egg (pre-sprite fallback — keeps the UI crash-free). */
	private static BufferedImage paintedFallback(int sz)
	{
		sz = Math.max(6, sz);
		BufferedImage img = new BufferedImage(sz, sz, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(247, 238, 214));
		g.fillOval(2, 1, sz - 4, sz - 2);
		g.setColor(new Color(226, 210, 168));
		g.drawOval(2, 1, sz - 5, sz - 3);
		g.setColor(new Color(255, 252, 240));
		g.fillOval(5, 3, 3, 4); // highlight
		g.dispose();
		return img;
	}
}

package com.runie.ui;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Rectangle;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Runie side panel (architecture §8): header with the Egg balance + today's
 * accrual, tabs for Collection (grid ↔ detail card) and Hatch (Hatch Egg).
 *
 * <p><b>Scrolling:</b> the RuneLite side panel is a fixed ~225px-wide, height-
 * constrained strip. Every tab's body is therefore wrapped in a vertical
 * {@link JScrollPane} (horizontal scrolling off) whose view tracks the viewport
 * width — content reflows to the panel width and takes its natural height, so
 * the full 42-creature grid is reachable by scrolling instead of being
 * squeezed/clipped to the visible area.
 *
 * <p>All data access is read-only service views; commands go through
 * {@link UiContext#commandRunner} (client thread in production). External
 * events (pulls, level-ups, config changes) call {@link #refreshLater()},
 * which marshals onto the EDT.
 */
public class RuniePanel extends PluginPanel
{
	/** Scroll step for one mouse-wheel/arrow unit, in px. */
	private static final int SCROLL_UNIT_PX = 16;

	private final UiContext ctx;
	private final java.util.concurrent.atomic.AtomicBoolean refreshQueued =
		new java.util.concurrent.atomic.AtomicBoolean();
	private final JLabel eggsLabel = balanceLabel(new Color(120, 220, 120));
	private final JLabel todayLabel = balanceLabel(ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel warnLabel = new JLabel("", SwingConstants.CENTER);

	private final CollectionGridPanel collectionGrid;
	private final CreatureDetailPanel detailPanel;
	private final PullPanel pullPanel;
	private final CardLayout collectionCards = new CardLayout();
	private final JPanel collectionHolder = new JPanel(collectionCards);

	public RuniePanel(UiContext ctx)
	{
		super(false);
		this.ctx = ctx;
		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		// header: title + balance + no-active-companion warning (fixed, never scrolls)
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel title = new JLabel("Runie", SwingConstants.CENTER);
		title.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));
		title.setForeground(Color.WHITE);
		header.add(title, BorderLayout.NORTH);

		JPanel balances = new JPanel(new java.awt.GridLayout(2, 1, 0, 2));
		balances.setBackground(ColorScheme.DARK_GRAY_COLOR);
		balances.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		balances.add(eggsLabel);
		balances.add(todayLabel);
		header.add(balances, BorderLayout.CENTER);

		warnLabel.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		warnLabel.setForeground(new Color(255, 170, 80));
		header.add(warnLabel, BorderLayout.SOUTH);
		add(header, BorderLayout.NORTH);

		// tabs — each tab body scrolls vertically
		collectionGrid = new CollectionGridPanel(ctx, this::showDetail);
		detailPanel = new CreatureDetailPanel(ctx, this::showCollection, this::refreshLater);
		pullPanel = new PullPanel(ctx);

		collectionHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		collectionHolder.add(collectionGrid, "grid");
		collectionHolder.add(detailPanel, "detail");

		JTabbedPane tabs = new JTabbedPane();
		tabs.setTabLayoutPolicy(JTabbedPane.SCROLL_TAB_LAYOUT); // single row at 242px
		tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tabs.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		tabs.addTab("Collection", vScroll(collectionHolder, 2));
		tabs.addTab("Hatch", vScroll(pullPanel, 2));
		add(tabs, BorderLayout.CENTER);

		refresh();
	}

	/** Full refresh — must run on the EDT. */
	public void refresh()
	{
		int eggs = ctx.eggService.getEggBalance();
		eggsLabel.setText(eggs + (eggs == 1 ? " Egg" : " Eggs"));
		todayLabel.setText(String.format("%d egg%s today - next: %,d / %,d XP",
			ctx.eggService.getEggsEarnedToday(), ctx.eggService.getEggsEarnedToday() == 1 ? "" : "s",
			ctx.eggService.getBankedXp(), ctx.eggService.getNextEggCostXp()));
		boolean noActive = ctx.stateStore.hasState()
			&& !ctx.progressionService.getActiveCreatureId().isPresent()
			&& ctx.progressionService.ownedCount() > 0
			&& ctx.config.warnNoActiveCreature();
		warnLabel.setText(noActive ? "No active companion - XP feeds no one!" : " ");
		collectionGrid.refresh();
		detailPanel.refresh();
		pullPanel.refresh();
	}

	/**
	 * Thread-safe refresh entry point for service listeners (client thread).
	 *
	 * <p>Coalescing: this is now also called for every validated XP delta (the
	 * same-delta panel sync — see {@code RuniePlugin.startUp}), which can burst
	 * many times per client tick. A pending flag collapses any burst into one
	 * queued EDT refresh; the flag clears BEFORE {@link #refresh()} reads state,
	 * so a delta landing mid-refresh always queues one more pass — the panel can
	 * lag by at most one EDT hop, never miss the final value.
	 */
	public void refreshLater()
	{
		if (refreshQueued.compareAndSet(false, true))
		{
			SwingUtilities.invokeLater(() ->
			{
				refreshQueued.set(false);
				refresh();
			});
		}
	}

	/** Header egg-balance text (test seam — headless sync tests read this). */
	String headerEggsText()
	{
		return eggsLabel.getText();
	}

	/** Header today/banked-XP text (test seam — headless sync tests read this). */
	String headerTodayText()
	{
		return todayLabel.getText();
	}

	public void showDetail(String creatureId)
	{
		detailPanel.showCreature(creatureId);
		collectionCards.show(collectionHolder, "detail");
		scrollToTop(collectionHolder);
	}

	public void showCollection()
	{
		collectionCards.show(collectionHolder, "grid");
		scrollToTop(collectionHolder);
	}

	/** Test/mockup access to the detail card. */
	public CreatureDetailPanel detailPanel()
	{
		return detailPanel;
	}

	/**
	 * Wrap tab content in a vertical-only scroll pane: vertical bar as needed,
	 * horizontal bar never; the {@link ScrollBody} view tracks the viewport
	 * width so the content reflows to the panel width and keeps its natural
	 * height (no forced aspect ratio, no clipping).
	 */
	private static JScrollPane vScroll(JComponent content, int hPad)
	{
		ScrollBody body = new ScrollBody(content, hPad);
		JScrollPane scroll = new JScrollPane(body,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getVerticalScrollBar().setUnitIncrement(SCROLL_UNIT_PX);
		scroll.getVerticalScrollBar().setPreferredSize(
			new Dimension(7, 0)); // slim, RuneLite-like scrollbar in the narrow panel
		return scroll;
	}

	/** Jump the enclosing viewport back to the top (grid ↔ detail swaps). */
	private static void scrollToTop(JComponent inner)
	{
		JScrollPane scroll = (JScrollPane) SwingUtilities.getAncestorOfClass(JScrollPane.class, inner);
		if (scroll != null)
		{
			scroll.getVerticalScrollBar().setValue(0);
		}
	}

	/**
	 * Scroll-pane view that tracks the viewport WIDTH (never scrolls
	 * horizontally) while exposing the content's natural preferred HEIGHT
	 * (scrolls vertically when taller than the viewport). Content is anchored
	 * NORTH so short tabs don't get stretched vertically.
	 */
	private static final class ScrollBody extends JPanel implements Scrollable
	{
		ScrollBody(JComponent content, int hPad)
		{
			super(new BorderLayout());
			setBackground(ColorScheme.DARK_GRAY_COLOR);
			setBorder(BorderFactory.createEmptyBorder(6, hPad, 6, hPad));
			add(content, BorderLayout.NORTH);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return SCROLL_UNIT_PX;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(visibleRect.height - SCROLL_UNIT_PX, SCROLL_UNIT_PX);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true; // reflow to the panel width — horizontal scroll never appears
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false; // natural height — vertical scrollbar appears as needed
		}
	}

	private static JLabel balanceLabel(Color color)
	{
		JLabel l = new JLabel("", SwingConstants.CENTER);
		l.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
		l.setForeground(color);
		return l;
	}
}

