/**
 * Rich result of a single Hatch (architecture §9.2). Immutable; consumed
 * by the hatch-reveal overlay (Epic 6) and the panel hatch tab (Epic 7).
 */
public final class PullResult
{
	/** Pity counters AFTER the pull — the panel's pity meters read this. */
	public static final class PitySnapshot
	{
		public final int rarePity;
		public final int elitePity;
		public final int gmPity;
		public final int totalPulls;
		public final int starterPullsRemaining;

		public PitySnapshot(int rarePity, int elitePity, int gmPity, int totalPulls, int starterPullsRemaining)
		{
			this.rarePity = rarePity;
			this.elitePity = elitePity;
			this.gmPity = gmPity;
			this.totalPulls = totalPulls;
			this.starterPullsRemaining = starterPullsRemaining;
		}
	}

	public final String creatureId;
	public final Rarity rarity;
	/** True = first copy (creature added to collection); false = duplicate. */
	public final boolean isNew;
	/** True when first-copy protection rerolled a duplicate to this creature. */
	public final boolean rerolled;
	/** Star count AFTER this hatch (0 for a first copy; capped at 25). */
	public final int starsAfter;
	/** True when THIS duplicate's shiny roll succeeded (the shiny moment). */
	public final boolean becameShiny;
	/** True when the creature is shiny after this hatch (new or pre-existing). */
	public final boolean shiny;
	/** True when this pull consumed a starter (welcome) hatch. */
	public final boolean starterPull;
	public final PitySnapshot pity;

	public PullResult(String creatureId, Rarity rarity, boolean isNew, boolean rerolled,
		int starsAfter, boolean becameShiny, boolean shiny, boolean starterPull, PitySnapshot pity)
	{
		this.creatureId = creatureId;
		this.rarity = rarity;
		this.isNew = isNew;
		this.rerolled = rerolled;
		this.starsAfter = starsAfter;
		this.becameShiny = becameShiny;
		this.shiny = shiny;
		this.starterPull = starterPull;
		this.pity = pity;
	}
}

package com.runie.core;

import com.runie.state.RunieStateStore;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

/**
 * The ONLY producer of trusted XP deltas (architecture §3 — THE critical
 * algorithm, implemented exactly per §3.2).
 *
 * <p>Why: there is no ExperienceChanged event; XP arrives via StatChanged, and on
 * login the client fires a burst of StatChanged carrying the account's entire
 * lifetime XP. A naive {@code delta = newXp - lastKnownXp} against a zeroed (or
 * stale, cross-account) baseline would grant a lifetime of XP as one delta —
 * economy-fatal (§16.1). Three layers prevent that:
 *
 * <ol>
 *   <li><b>Per-skill −1 sentinels</b>: the first StatChanged per skill after any
 *       (re)login is snapshot-only. Sentinels re-arm on LOGGING_IN / HOPPING /
 *       CONNECTION_LOST / LOGIN_SCREEN.</li>
 *   <li><b>2-tick post-LOGGED_IN grace window</b>: ALL StatChanged during grace
 *       are snapshot-only (covers late login bursts). We always prefer losing a
 *       crumb to granting a windfall.</li>
 *   <li><b>Plausibility ceiling + negative-delta re-snapshot</b>: implausible
 *       spikes (&gt;5M) and non-positive deltas refresh the snapshot and grant
 *       nothing — never a grant, never a "refund".</li>
 * </ol>
 *
 * <p>Account binding: every StatChanged re-verifies {@code getAccountHash()}.
 * Hash −1 → ignored entirely. A hash change swaps the state file BEFORE any
 * delta can be attributed and drops all snapshots — snapshots are never carried
 * across accounts (§16.2).
 */
@Slf4j
@Singleton
public class XpDeltaService
{
	static final int GRACE_TICKS = 2;                        // ~1.2s after LOGGED_IN
	static final int MAX_PLAUSIBLE_EVENT_XP = 5_000_000;     // > any legit single grant (lamps/quests)

	public interface XpDeltaListener
	{
		void onXpGained(Skill skill, int delta, int newTotalXp);
	}

	private final AccountContext accountContext;
	private final RunieStateStore stateStore;
	private final List<XpDeltaListener> listeners = new CopyOnWriteArrayList<>();

	/** Per-skill last-seen XP; -1 = sentinel: "no snapshot, nothing is trusted". */
	private final int[] cachedXp = new int[Skill.values().length];
	/** -1 = not logged in / grace not started; 0 = warmed up; >0 = counting down. */
	private int graceTicksRemaining = -1;
	/**
	 * True while the sentinels are armed by a (re)login-ish state, i.e. the NEXT
	 * LOGGED_IN is a genuine (re)connect and must start the grace window.
	 *
	 * <p>Why this exists: RuneLite fires {@code GameStateChanged(LOGGED_IN)}
	 * again after every {@code LOADING} (region crossing / teleport), not just
	 * after logins. Unconditionally re-arming the grace window there swallowed
	 * genuine in-session deltas for {@value #GRACE_TICKS} ticks on EVERY region
	 * load — real ongoing gains got dropped even though the sentinels were still
	 * warm. The settle window may only guard the initial post-login snapshot,
	 * never ongoing accrual, so grace re-arms ONLY when a reset state
	 * (LOGGING_IN / HOPPING / CONNECTION_LOST / LOGIN_SCREEN) preceded this
	 * LOGGED_IN. Every real (re)connect passes through one of those states
	 * first, so the login-dump guarantee is unchanged.
	 */
	private boolean awaitingLoginGrace = true;
	private long trackedAccountHash = AccountContext.NO_ACCOUNT;

	@Inject
	public XpDeltaService(AccountContext accountContext, RunieStateStore stateStore)
	{
		this.accountContext = accountContext;
		this.stateStore = stateStore;
		Arrays.fill(cachedXp, -1);
	}

	public void addListener(XpDeltaListener l)
	{
		listeners.add(l);
	}

	public void removeListener(XpDeltaListener l)
	{
		listeners.remove(l);
	}

	/** UI hint ("syncing…"): true once the post-login grace window has elapsed. */
	public boolean isWarmedUp()
	{
		return graceTicksRemaining == 0;
	}

	public void handleGameStateChanged(GameState gs)
	{
		switch (gs)
		{
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
			case LOGIN_SCREEN:
				Arrays.fill(cachedXp, -1);                   // ARM SENTINELS — nothing is trusted
				graceTicksRemaining = -1;
				awaitingLoginGrace = true;
				break;
			case LOGGED_IN:
				// Start the post-login grace window ONLY on a genuine (re)connect.
				// LOGGED_IN also fires after every region LOADING mid-session; the
				// settle window must never swallow ongoing in-session gains there.
				if (awaitingLoginGrace)
				{
					graceTicksRemaining = GRACE_TICKS;
					awaitingLoginGrace = false;
				}
				break;
			default:
				break;
		}
	}

	public void handleGameTick()
	{
		if (graceTicksRemaining > 0)
		{
			graceTicksRemaining--;
		}
	}

	public void handleStatChanged(StatChanged e)
	{
		long hash = accountContext.accountHash();
		if (hash == AccountContext.NO_ACCOUNT)
		{
			return;                                          // no account context: ignore entirely
		}
		if (hash != trackedAccountHash)
		{
			// Account switched under us: swap the state file BEFORE any attribution,
			// and NEVER carry snapshots across accounts.
			bindAccount(hash);
		}

		int idx = e.getSkill().ordinal();
		int newXp = e.getXp();
		int oldXp = cachedXp[idx];
		cachedXp[idx] = newXp;                               // ALWAYS refresh the snapshot first

		if (oldXp == -1)
		{
			return;                                          // Layer 1: first event per skill post-(re)login = snapshot-only
		}
		if (graceTicksRemaining != 0)
		{
			return;                                          // Layer 2: whole grace window = snapshot-only
		}
		int delta = newXp - oldXp;
		if (delta <= 0)
		{
			return;                                          // Layer 3a: negative/zero → re-snapshot; never grant, never refund
		}
		if (delta > MAX_PLAUSIBLE_EVENT_XP)
		{
			// Layer 3b: implausible spike → re-snapshot + log, grant nothing
			log.warn("Runie: implausible xp delta {} in {}; re-snapshotting", delta, e.getSkill());
			return;
		}
		for (XpDeltaListener l : listeners)
		{
			l.onXpGained(e.getSkill(), delta, newXp);
		}
	}

	/**
	 * Bind the account state file for {@code hash} and arm the login guards.
	 * Loading state is always safe; XP attribution stays gated by the freshly
	 * armed per-skill sentinels + grace window set here — so a bind never risks
	 * the login-snapshot windfall, no matter when it happens.
	 */
	private void bindAccount(long hash)
	{
		trackedAccountHash = hash;
		stateStore.switchAccount(hash);                      // loads state-<hash>.json (fires StateLoadListener)
		Arrays.fill(cachedXp, -1);                           // nothing trusted until re-snapshotted
		graceTicksRemaining = GRACE_TICKS;
		awaitingLoginGrace = false;                          // this IS the (re)bind; grace just started
	}

	/**
	 * Bind + load the current account's state immediately when we're logged in
	 * with a real account but haven't bound yet — e.g. the plugin was enabled
	 * mid-session (no fresh login, no XP tick yet) or right after LOGGED_IN
	 * before the first StatChanged. Without this, the collection/panel showed
	 * empty until the next XP gain reloaded the file. No-ops when logged out or
	 * already bound; the StatChanged path remains the backstop.
	 */
	public void ensureAccountBound()
	{
		long hash = accountContext.accountHash();
		if (hash != AccountContext.NO_ACCOUNT && hash != trackedAccountHash)
		{
			bindAccount(hash);
		}
	}

	/** Plugin shutDown(): drop all snapshots and listeners for a clean re-enable. */
	public void reset()
	{
		Arrays.fill(cachedXp, -1);
		graceTicksRemaining = -1;
		awaitingLoginGrace = true;
		trackedAccountHash = AccountContext.NO_ACCOUNT;
		listeners.clear();
	}
}

package com.runie.core;

import com.runie.creatures.CreatureDefinition;
import com.runie.creatures.CreatureRegistry;
import com.runie.state.CreatureInstance;
import com.runie.state.RunieAccountState;
import com.runie.state.RunieStateStore;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Creature XP mirror, leveling, evolution, prestige + collection accessors
 * (Epic 4; architecture §2 signatures).
 *
 * <p>Registered as a second {@link XpDeltaService.XpDeltaListener} in
 * {@code RuniePlugin.startUp()} — it only ever sees positive, validated player
 * XP deltas, which it mirrors <b>1:1</b> onto the ACTIVE creature. With no
 * active creature the delta is a no-op (no accrual, no banking — the panel
 * warns in Epic 7).
 *
 * <p>Levels come from the OSRS table: {@code XpTable.levelForXp(xp, prestiged ?
 * 120 : 99)}. Evolution stage is {@link CreatureDefinition#stageForLevel}
 * (thresholds ~L40 / ~L70–80 per roster). Prestige (eligible at L99, one tier
 * only, IRREVERSIBLE): resets {@code xp} to 0 (level 1), raises the cap to 120,
 * keeps the final evolved look (stage 3), increments {@code prestigeCount},
 * preserves {@code lifetimeXp}, and layers the prestige aura —
 * {@link AuraState#GOLDEN} at level 120.
 *
 * <p>All mutations go through {@link RunieAccountState} and persist via the
 * debounced {@link RunieStateStore} (prestige flushes immediately, §4.4).
 */
@Slf4j
@Singleton
public class ProgressionService implements XpDeltaService.XpDeltaListener
{
	/** Un-prestiged creature level cap. */
	public static final int BASE_LEVEL_CAP = 99;
	/** Prestiged creature level cap (single prestige tier — §16 risk 10). */
	public static final int PRESTIGE_LEVEL_CAP = 120;

	/** UI seam (Epic 6/7): overlay/panel subscribe for level/stage/prestige signals. */
	public interface ProgressionListener
	{
		default void onLevelUp(String creatureId, int oldLevel, int newLevel)
		{
		}

		/** Stage-change signal (evolution). Fired only on upward crossings. */
		default void onStageChange(String creatureId, int oldStage, int newStage)
		{
		}

		default void onPrestige(String creatureId)
		{
		}

		/**
		 * Active-companion selection changed ({@code activeCreatureId} may be
		 * null = cleared). The plugin uses this to refresh the companion overlay
		 * IMMEDIATELY — deploying a creature must never wait for an unrelated
		 * config change.
		 */
		default void onActiveChanged(String activeCreatureId)
		{
		}
	}

	private final RunieStateStore stateStore;
	private final CreatureRegistry registry;
	private final EggService eggService;
	private final List<ProgressionListener> listeners = new CopyOnWriteArrayList<>();

	@Inject
	public ProgressionService(RunieStateStore stateStore, CreatureRegistry registry, EggService eggService)
	{
		this.stateStore = stateStore;
		this.registry = registry;
		this.eggService = eggService;
	}

	public void addListener(ProgressionListener l)
	{
		listeners.add(l);
	}

	public void removeListener(ProgressionListener l)
	{
		listeners.remove(l);
	}

	// ------------------------------------------------------------------
	// XP mirror (the Epic 4 accrual path)
	// ------------------------------------------------------------------

	@Override
	public void onXpGained(Skill skill, int delta, int newTotalXp)
	{
		if (delta <= 0 || !readyWritable())
		{
			return;
		}
		RunieAccountState s = stateStore.getState();
		String activeId = s.creatures.active;
		if (activeId == null)
		{
			return; // no active creature: XP feeds no one — no accrual, no banking
		}
		CreatureInstance c = s.creatures.owned.get(activeId);
		if (c == null)
		{
			return; // defensive: load-time normalization guarantees active ∈ owned
		}

		int cap = c.isPrestiged() ? PRESTIGE_LEVEL_CAP : BASE_LEVEL_CAP;
		int oldLevel = XpTable.levelForXp(c.xp, cap);
		c.xp += delta;               // 1:1 mirror of the validated player delta
		c.lifetimeXp += delta;
		int newLevel = XpTable.levelForXp(c.xp, cap);
		stateStore.markDirty();

		if (newLevel > oldLevel)
		{
			// golden L120 mastery milestone (same crossing that fires the golden
			// burst VFX in the plugin's onLevelUp listener): +5 eggs, once ever
			if (newLevel >= PRESTIGE_LEVEL_CAP && oldLevel < PRESTIGE_LEVEL_CAP)
			{
				grantGoldenMilestoneReward(activeId, c);
			}
			for (ProgressionListener l : listeners)
			{
				l.onLevelUp(activeId, oldLevel, newLevel);
			}
			CreatureDefinition def = registry.byId(activeId);
			if (def != null)
			{
				int oldStage = def.stageForLevel(oldLevel, c.isPrestiged());
				int newStage = def.stageForLevel(newLevel, c.isPrestiged());
				if (newStage > oldStage)
				{
					grantEvolutionReward(activeId, c, oldStage, newStage);
					for (ProgressionListener l : listeners)
					{
						l.onStageChange(activeId, oldStage, newStage);
					}
				}
			}
		}
	}

	/**
	 * Evolution reward (rework part 2): +1 egg per evolution crossing
	 * (stage 1→2 and 2→3), granted exactly ONCE per crossing ever. The highest
	 * stage already rewarded persists on the creature
	 * ({@code evolutionRewardedStage}), so reloads / replayed events never
	 * double-grant; legacy creatures that pre-date the rework anchor at their
	 * current stage (no retroactive grants for crossings that happened before).
	 */
	private void grantEvolutionReward(String creatureId, CreatureInstance c, int oldStage, int newStage)
	{
		int rewarded = Math.max(c.evolutionRewardedStage, oldStage);
		int crossings = newStage - rewarded;
		if (crossings <= 0)
		{
			return;
		}
		c.evolutionRewardedStage = newStage;
		eggService.creditEggs(crossings * Economy.EVOLUTION_REWARD_EGGS, EggSource.EVOLUTION);
		stateStore.markDirty();
		log.debug("Runie: evolution reward — {} egg(s) for {} reaching stage {}", crossings, creatureId, newStage);
	}

	/**
	 * Golden L120 mastery reward: +{@link Economy#GOLDEN_MILESTONE_REWARD_EGGS}
	 * eggs when a (prestiged) creature reaches level
	 * {@value #PRESTIGE_LEVEL_CAP}, granted exactly ONCE per creature ever. The
	 * persisted {@code goldenRewardGranted} flag is the grant-once watermark:
	 * reloads / replayed crossings never double-grant. Called only on an actual
	 * upward L120 crossing, so a legacy creature already at 120 (whose level can
	 * never cross the cap again) is never retroactively granted.
	 */
	private void grantGoldenMilestoneReward(String creatureId, CreatureInstance c)
	{
		if (c.goldenRewardGranted)
		{
			return; // watermark: already rewarded — re-checks are no-ops
		}
		c.goldenRewardGranted = true;
		eggService.creditEggs(Economy.GOLDEN_MILESTONE_REWARD_EGGS, EggSource.GOLDEN_MILESTONE);
		stateStore.markDirty();
		log.debug("Runie: golden L120 milestone — {} egg(s) for {}", Economy.GOLDEN_MILESTONE_REWARD_EGGS, creatureId);
	}

	// ------------------------------------------------------------------
	// Active companion selection
	// ------------------------------------------------------------------

	public Optional<String> getActiveCreatureId()
	{
		if (!stateStore.hasState())
		{
			return Optional.empty();
		}
		return Optional.ofNullable(stateStore.getState().creatures.active);
	}

	public Optional<CreatureInstance> getActiveCreature()
	{
		return getActiveCreatureId().map(id -> stateStore.getState().creatures.owned.get(id));
	}

	/**
	 * Set the active companion. {@code null} clears the selection (XP then feeds
	 * no one — the panel warns).
	 *
	 * @return true if applied; false when the creature is not owned or state is
	 *         not writable
	 */
	public boolean setActiveCreature(String creatureId)
	{
		if (!readyWritable())
		{
			return false;
		}
		RunieAccountState s = stateStore.getState();
		if (creatureId != null && !s.creatures.owned.containsKey(creatureId))
		{
			return false;
		}
		s.creatures.active = creatureId;
		stateStore.markDirty();
		for (ProgressionListener l : listeners)
		{
			l.onActiveChanged(creatureId);
		}
		return true;
	}

	// ------------------------------------------------------------------
	// Levels / evolution / aura (read views)
	// ------------------------------------------------------------------

	/** OSRS-table level for creature XP, capped 99 / 120 by prestige flag. */
	public int levelForXp(long xp, boolean prestiged)
	{
		return XpTable.levelForXp(xp, prestiged ? PRESTIGE_LEVEL_CAP : BASE_LEVEL_CAP);
	}

	/** Current level of an owned creature (0 if not owned / no state). */
	public int levelOf(String creatureId)
	{
		return getCreature(creatureId).map(c -> levelForXp(c.xp, c.isPrestiged())).orElse(0);
	}

	/** Evolution stage (1..3) for a level; prestiged creatures keep stage 3. */
	public int evolutionStageFor(CreatureDefinition def, int level, boolean prestiged)
	{
		return def.stageForLevel(level, prestiged);
	}

	/** Current evolution stage of an owned creature (0 if not owned). */
	public int currentStageOf(String creatureId)
	{
		Optional<CreatureInstance> inst = getCreature(creatureId);
		if (!inst.isPresent())
		{
			return 0;
		}
		CreatureDefinition def = registry.byId(creatureId);
		if (def == null)
		{
			return 0;
		}
		CreatureInstance c = inst.get();
		return def.stageForLevel(levelForXp(c.xp, c.isPrestiged()), c.isPrestiged());
	}

	/**
	 * Aura layer for an owned creature: NONE until prestiged, PRESTIGE after,
	 * GOLDEN at level {@value #PRESTIGE_LEVEL_CAP} (fully mastered). Derived —
	 * never persisted, cannot desync.
	 */
	public AuraState auraOf(String creatureId)
	{
		Optional<CreatureInstance> inst = getCreature(creatureId);
		if (!inst.isPresent() || !inst.get().isPrestiged())
		{
			return AuraState.NONE;
		}
		CreatureInstance c = inst.get();
		return levelForXp(c.xp, true) >= PRESTIGE_LEVEL_CAP ? AuraState.GOLDEN : AuraState.PRESTIGE;
	}

	// ------------------------------------------------------------------
	// Prestige (confirm-gated by UI; IRREVERSIBLE — no undo API exists)
	// ------------------------------------------------------------------

	/**
	 * Prestige an owned creature at level 99. On success: XP resets to 0
	 * (level 1), the cap rises to 120, the final evolved (stage-3) look is kept,
	 * {@code prestigeCount} increments, {@code lifetimeXp} is preserved, and the
	 * prestige aura activates. One prestige tier only; irreversible.
	 */
	public PrestigeResult prestige(String creatureId)
	{
		if (!readyWritable())
		{
			return PrestigeResult.NOT_READY;
		}
		CreatureInstance c = stateStore.getState().creatures.owned.get(creatureId);
		if (c == null)
		{
			return PrestigeResult.NOT_OWNED;
		}
		if (c.isPrestiged())
		{
			return PrestigeResult.ALREADY_PRESTIGED; // single tier — no second reset path
		}
		if (XpTable.levelForXp(c.xp, BASE_LEVEL_CAP) < BASE_LEVEL_CAP)
		{
			return PrestigeResult.NOT_LEVEL_99;
		}

		c.xp = 0;              // level 1, cap now 120; lifetimeXp untouched
		c.prestigeCount++;
		stateStore.markDirty();
		stateStore.flushAsync(); // immediate flush on prestige (§4.4)
		log.debug("Runie: prestiged {}", creatureId);
		for (ProgressionListener l : listeners)
		{
			l.onPrestige(creatureId);
		}
		return PrestigeResult.SUCCESS;
	}

	// ------------------------------------------------------------------
	// Collection accessors (panel/collection grid read these in Epic 7)
	// ------------------------------------------------------------------

	public boolean isOwned(String creatureId)
	{
		return stateStore.hasState() && stateStore.getState().creatures.owned.containsKey(creatureId);
	}

	public Optional<CreatureInstance> getCreature(String creatureId)
	{
		if (!stateStore.hasState() || creatureId == null)
		{
			return Optional.empty();
		}
		return Optional.ofNullable(stateStore.getState().creatures.owned.get(creatureId));
	}

	/** Owned creature ids, acquisition order (read-only view). */
	public Set<String> ownedCreatureIds()
	{
		if (!stateStore.hasState())
		{
			return Collections.emptySet();
		}
		return Collections.unmodifiableSet(stateStore.getState().creatures.owned.keySet());
	}

	public int ownedCount()
	{
		return stateStore.hasState() ? stateStore.getState().creatures.owned.size() : 0;
	}

	// ------------------------------------------------------------------

	private boolean readyWritable()
	{
		return stateStore.hasState() && !stateStore.isWritesDisabled();
	}
}

package com.runie.core;

import java.security.SecureRandom;
import java.util.SplittableRandom;

/**
 * Seedable RNG abstraction (architecture §2). GachaService (Epic 5) and any other
 * randomness consume this interface only, so tests can bind a fixed seed and
 * fixture-assert exact sequences.
 */
public interface RunieRandom
{
	double nextDouble();

	/** Uniform int in {@code [0, bound)}. */
	int nextInt(int bound);

	/** Production instance: SecureRandom-seeded SplittableRandom. */
	static RunieRandom secure()
	{
		return seeded(new SecureRandom().nextLong());
	}

	/** Deterministic instance for tests and reproducible fixtures. */
	static RunieRandom seeded(long seed)
	{
		SplittableRandom r = new SplittableRandom(seed);
		return new RunieRandom()
		{
			@Override
			public double nextDouble()
			{
				return r.nextDouble();
			}

			@Override
			public int nextInt(int bound)
			{
				return r.nextInt(bound);
			}
		};
	}
}

package com.runie.core;

import java.awt.Color;

/**
 * Duplicate-star color tiers (gameplay rework part 3). Each duplicate hatch of
 * an owned creature adds one star; stars group into five-star color tiers:
 * Bronze (1–5) → Silver (6–10) → Gold (11–15) → Red (16–20) → Pink (21–25).
 * Progression caps at {@link Economy#MAX_STARS} (5 Pink).
 */
public enum StarTier
{
	BRONZE("Bronze", new Color(205, 127, 50)),
	SILVER("Silver", new Color(198, 202, 212)),
	GOLD("Gold", new Color(255, 200, 46)),
	RED("Red", new Color(232, 68, 58)),
	PINK("Pink", new Color(255, 122, 190));

	private final String displayName;
	private final Color color;

	StarTier(String displayName, Color color)
	{
		this.displayName = displayName;
		this.color = color;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public Color getColor()
	{
		return color;
	}

	/**
	 * Color tier for a star count. Returns null for 0 stars (no tier yet);
	 * counts beyond {@link Economy#MAX_STARS} clamp to PINK.
	 */
	public static StarTier tierFor(int stars)
	{
		if (stars <= 0)
		{
			return null;
		}
		int clamped = Math.min(stars, Economy.MAX_STARS);
		return values()[(clamped - 1) / Economy.STARS_PER_TIER];
	}

	/**
	 * Stars shown WITHIN the current tier (1–5). 0 for 0 stars; counts beyond
	 * the cap clamp to 5 (full Pink).
	 */
	public static int starsInTier(int stars)
	{
		if (stars <= 0)
		{
			return 0;
		}
		int clamped = Math.min(stars, Economy.MAX_STARS);
		return ((clamped - 1) % Economy.STARS_PER_TIER) + 1;
	}
}

package com.runie.core;

/**
 * Prestige aura presentation state (architecture §5.1: auras are composited
 * overlay clips — {@code aura_prestige} / {@code aura_gold}). Derived, never
 * persisted: {@code prestigeCount} + level fully determine it, so it can never
 * desync from the creature's real progression.
 */
public enum AuraState
{
	/** Not prestiged: no aura layer. */
	NONE,
	/** Prestiged, below the level-120 cap: faint prestige aura. */
	PRESTIGE,
	/** Prestiged AND level 120 (fully mastered): golden aura. */
	GOLDEN
}

package com.runie.core;

import com.google.gson.Gson;
import com.runie.assets.AssetLoader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Streams the creature art bundle into a local cache on first launch, so the
 * distributed plugin jar stays under the Plugin Hub's 10&nbsp;MB limit
 * (architecture: the ~28&nbsp;MB of animation frames live on the repo's
 * {@code assets} branch, NOT in the jar). Files are fetched once from
 * github.com — the RuneLite maintainers confirmed github.com networking needs
 * no user warning — validated as real PNGs, and written under
 * {@code RUNELITE_DIR/runie/assets/}. {@link AssetLoader} reads that cache first,
 * so once synced Runie is fully local; a missing/failed download simply degrades
 * to a silhouette and retries next launch. No telemetry, no personal data — the
 * only traffic is GETs for static art files.
 */
@Slf4j
@Singleton
public class RunieAssetService
{
	static final String INDEX_RESOURCE = "/com/runie/art_index.json";
	/** Refresh the UI every N freshly downloaded files so art appears progressively. */
	private static final int REFRESH_EVERY = 24;

	/** Test seam over the network so sync() is unit-testable without github.com. */
	public interface Fetcher
	{
		/** GET the URL, returning the raw bytes, or throw on any non-success. */
		byte[] get(String url) throws IOException;
	}

	private static final class Index
	{
		int version;
		String base;
		List<String> files;
	}

	private final AssetLoader assetLoader;
	private final ScheduledExecutorService executor;
	private final Fetcher fetcher;
	private final Gson gson;

	@Inject
	public RunieAssetService(AssetLoader assetLoader, ScheduledExecutorService executor,
		OkHttpClient http, Gson gson)
	{
		// Plugin Hub requires the client's shared, injected Gson (never a fresh instance).
		this(assetLoader, executor, new OkHttpFetcher(http), gson);
	}

	/** Test seam: supply a fake Fetcher + Gson (and typically a same-thread executor). */
	public RunieAssetService(AssetLoader assetLoader, ScheduledExecutorService executor,
		Fetcher fetcher, Gson gson)
	{
		this.assetLoader = assetLoader;
		this.executor = executor;
		this.fetcher = fetcher;
		this.gson = gson;
	}

	/**
	 * Point the loader at {@code RUNELITE_DIR/runie/assets} and kick off a
	 * background sync. Safe to call on the client thread — the actual download
	 * runs on the injected executor.
	 */
	public void start(Path runeliteDir, Runnable onProgress, Runnable onComplete)
	{
		Path cacheDir = runeliteDir.resolve("runie").resolve("assets");
		assetLoader.setAssetCacheDir(cacheDir);
		executor.execute(() -> syncNow(cacheDir, onProgress, onComplete));
	}

	/**
	 * Download any missing art into {@code cacheDir}. Idempotent: files already
	 * present are skipped, and once a full clean sync completes a version marker
	 * lets subsequent launches short-circuit. Returns the number newly fetched.
	 * Package-visible for tests.
	 */
	int syncNow(Path cacheDir, Runnable onProgress, Runnable onComplete)
	{
		int done = 0;
		try
		{
			Index idx = readIndex();
			if (idx == null || idx.files == null || idx.base == null)
			{
				log.warn("Runie: art index missing/invalid; skipping asset sync");
				return 0;
			}
			Files.createDirectories(cacheDir);
			Path versionMarker = cacheDir.resolve(".version");
			if (isSynced(versionMarker, idx.version))
			{
				if (onComplete != null)
				{
					onComplete.run();
				}
				return 0;
			}

			int failed = 0;
			int sinceRefresh = 0;
			for (String rel : idx.files)
			{
				Path target = cacheDir.resolve(rel);
				if (Files.isRegularFile(target))
				{
					continue; // resume-friendly: keep what we already have
				}
				try
				{
					byte[] bytes = fetcher.get(idx.base + rel);
					if (!isPng(bytes))
					{
						failed++;
						log.debug("Runie: not a PNG, skipping {}", rel);
						continue;
					}
					writeAtomic(target, bytes);
					done++;
					if (++sinceRefresh >= REFRESH_EVERY)
					{
						sinceRefresh = 0;
						assetLoader.invalidate();
						if (onProgress != null)
						{
							onProgress.run();
						}
					}
				}
				catch (Exception e)
				{
					failed++;
					log.debug("Runie: asset fetch failed for {}: {}", rel, e.toString());
				}
			}

			assetLoader.invalidate();
			if (failed == 0)
			{
				writeVersion(versionMarker, idx.version); // only mark done when EVERYTHING landed
			}
			else
			{
				log.info("Runie: asset sync incomplete ({} failed); will retry next launch", failed);
			}
			if (onComplete != null)
			{
				onComplete.run();
			}
		}
		catch (Exception e)
		{
			log.warn("Runie: asset sync error", e);
		}
		return done;
	}

	private Index readIndex()
	{
		try (InputStream in = RunieAssetService.class.getResourceAsStream(INDEX_RESOURCE))
		{
			if (in == null)
			{
				return null;
			}
			return gson.fromJson(new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8), Index.class);
		}
		catch (Exception e)
		{
			log.warn("Runie: failed to read art index", e);
			return null;
		}
	}

	private boolean isSynced(Path versionMarker, int version)
	{
		try
		{
			return Files.isRegularFile(versionMarker)
				&& new String(Files.readAllBytes(versionMarker), java.nio.charset.StandardCharsets.UTF_8)
				.trim().equals(Integer.toString(version));
		}
		catch (IOException e)
		{
			return false;
		}
	}

	private void writeVersion(Path versionMarker, int version) throws IOException
	{
		Files.write(versionMarker, Integer.toString(version).getBytes(java.nio.charset.StandardCharsets.UTF_8));
	}

	private static boolean isPng(byte[] b)
	{
		if (b == null || b.length < 8
			|| (b[0] & 0xFF) != 0x89 || b[1] != 'P' || b[2] != 'N' || b[3] != 'G')
		{
			return false;
		}
		try (InputStream in = new ByteArrayInputStream(b))
		{
			return ImageIO.read(in) != null; // fully decodes: rejects truncated/corrupt files
		}
		catch (IOException e)
		{
			return false;
		}
	}

	private static void writeAtomic(Path target, byte[] bytes) throws IOException
	{
		Files.createDirectories(target.getParent());
		Path tmp = target.resolveSibling(target.getFileName() + ".part");
		Files.write(tmp, bytes);
		try
		{
			Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException atomicUnsupported)
		{
			Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	/** Production fetcher over RuneLite's shared OkHttpClient. */
	private static final class OkHttpFetcher implements Fetcher
	{
		private final OkHttpClient http;

		OkHttpFetcher(OkHttpClient http)
		{
			this.http = http;
		}

		@Override
		public byte[] get(String url) throws IOException
		{
			Request req = new Request.Builder().url(url).build();
			try (Response resp = http.newCall(req).execute())
			{
				if (!resp.isSuccessful() || resp.body() == null)
				{
					throw new IOException("HTTP " + resp.code() + " for " + url);
				}
				return resp.body().bytes();
			}
		}
	}
}

