 */
public enum Rarity
{
	COMMON("Common"),
	UNCOMMON("Uncommon"),
	RARE("Rare"),
	ELITE("Elite"),
	MASTER("Master"),
	GRANDMASTER("Grandmaster");

	private final String displayName;

	Rarity(String displayName)
	{
		this.displayName = displayName;
	}

